INSERT INTO lp_resources (slug, kind, perspective, audience, urgency, evidence_level, emoji, title, summary, body, sections, reading_minutes, min_day, max_day, countries, sex, tags, is_featured, review_status, sort_order) VALUES
  ('tn-teenage-brain', 'article', 'scientific', 'shared', 'educational', 'consensus', '🧠', '{"en":"The teenage brain: why teens take risks and need sleep","bn":"কিশোর মস্তিষ্ক: কেন ঝুঁকি নেয়, কেন বেশি ঘুম দরকার"}'::jsonb, '{"en":"The teen brain is rebuilding: the reward system speeds ahead while self-control is still growing. Knowing this helps you guide rather than fight.","bn":"কৈশোরে মস্তিষ্ক নতুন করে গড়ে ওঠে: আনন্দ খোঁজার অংশ আগে এগিয়ে যায়, আর নিজেকে সামলানোর অংশ তখনও বাড়ছে। এটা বুঝলে লড়াই নয়, পথ দেখানো সহজ হয়।"}'::jsonb, '{"en":"Many parents notice that a calm child becomes moody, sleepy and daring around 13 or 14. This is not bad character. The teenage brain is going through one of its biggest rebuilds since early childhood.\n\n## What is changing\n\nThe parts of the brain that seek reward, excitement and approval from friends become very active in the teen years. The front part of the brain, which plans, controls impulses and weighs consequences, keeps developing into the mid-twenties. So a teen can understand a risk perfectly well in a calm moment, yet act on impulse when friends are watching or feelings run high.\n\n## Why teens take risks\n\n- Friends matter more than before; being accepted can feel more important than being safe.\n- New experiences feel more exciting at this age than they will later.\n- Teens are practising independence, a healthy step towards adulthood.\n\nRisk-taking is not all bad. The same drive helps a teen try out for a team, speak in front of the class or learn a new skill. Your job is not to remove it but to steer it towards safe challenges: sport, volunteering, competitions or a real responsibility at home.\n\n## Why teens need more sleep\n\nDuring puberty the body clock shifts later. Most teens genuinely feel sleepy later at night and find it hard to wake early. They still need about 8–10 hours of sleep. Too little sleep worsens mood, concentration, exam results and self-control, and makes accidents, including road crashes, more likely.\n\n## How you can help\n\n- Stay calm and keep rules clear; a steady parent supports a brain that is still developing.\n- Talk through risky situations before they happen: “What would you say if a friend offered you a vape?”\n- Agree a phone-off time together and keep phones out of the bedroom at night.\n- Praise good decisions, not only good marks.\n- Let them take safe risks and make small mistakes; this is how judgement grows.\n\n## When to get help\n\nTalk to a doctor or counsellor if mood changes last more than two weeks, if your teen hardly sleeps or sleeps most of the day, or if risk-taking becomes dangerous: drugs, self-harm or riding without a helmet.","bn":"১৩–১৪ বছরের দিকে অনেক বাবা-মা দেখেন, শান্ত সন্তানটি হঠাৎ মেজাজি, ঘুমকাতুরে আর দুঃসাহসী হয়ে উঠছে। এটা খারাপ স্বভাব নয়। শৈশবের পর এই সময়েই মস্তিষ্ক সবচেয়ে বড় পরিবর্তনের মধ্য দিয়ে যায়।\n\n## কী বদলাচ্ছে\n\nমস্তিষ্কের যে অংশ আনন্দ, উত্তেজনা আর বন্ধুদের বাহবা খোঁজে, কৈশোরে তা খুব সক্রিয় হয়ে ওঠে। অথচ সামনের যে অংশ পরিকল্পনা করে, আবেগ সামলায় আর পরিণাম ভাবে, সেটি পুরোপুরি পরিণত হতে প্রায় বিশের মাঝামাঝি পর্যন্ত সময় লাগে। তাই শান্ত অবস্থায় যে ঝুঁকি সে ভালোভাবেই বোঝে, বন্ধুদের সামনে বা রাগের মুহূর্তে সেই কাজটাই হঠাৎ করে ফেলতে পারে।\n\n## কেন ঝুঁকি নেয়\n\n- আগের চেয়ে বন্ধুরা বেশি গুরুত্বপূর্ণ; দলে জায়গা পাওয়া অনেক সময় নিরাপদ থাকার চেয়েও বড় মনে হয়।\n- এই বয়সে নতুন অভিজ্ঞতা অনেক বেশি রোমাঞ্চকর লাগে।\n- সে স্বাধীন হতে শিখছে — বড় হওয়ার পথে এটা স্বাভাবিক ও দরকারি ধাপ।\n\nঝুঁকি নেওয়ার সবটাই খারাপ নয়। এই একই তাগিদ তাকে খেলার দলে নাম লেখাতে, ক্লাসে সবার সামনে কথা বলতে বা নতুন কিছু শিখতে সাহস দেয়। আপনার কাজ এই তাগিদ বন্ধ করা নয়, বরং নিরাপদ চ্যালেঞ্জের দিকে ঘুরিয়ে দেওয়া — খেলাধুলা, স্বেচ্ছাসেবা, প্রতিযোগিতা বা ঘরের কোনো সত্যিকারের দায়িত্ব।\n\n## কেন বেশি ঘুম দরকার\n\nবয়ঃসন্ধিতে শরীরের ভেতরের ঘড়ি একটু পিছিয়ে যায়। তাই বেশিরভাগ কিশোর-কিশোরীর সত্যিই রাতে দেরিতে ঘুম আসে, সকালে উঠতে কষ্ট হয়। তবু তাদের প্রতিদিন প্রায় ৮–১০ ঘণ্টা ঘুম দরকার। ঘুম কম হলে মেজাজ, মনোযোগ, পরীক্ষার ফল আর নিজেকে সামলানোর ক্ষমতা কমে যায়, রাস্তায় দুর্ঘটনার ঝুঁকিও বাড়ে।\n\n## আপনি যা করতে পারেন\n\n- শান্ত থাকুন, নিয়ম পরিষ্কার রাখুন; স্থির বাবা-মা বেড়ে ওঠা মস্তিষ্ককে ভরসা দেন।\n- ঝুঁকির পরিস্থিতি আগেই আলোচনা করুন: “কোনো বন্ধু ভেপ সাধলে তুমি কী বলবে?”\n- ফোন বন্ধের সময় একসাথে ঠিক করুন, রাতে ফোন শোবার ঘরের বাইরে রাখুন।\n- শুধু ভালো নম্বরের জন্য নয়, ভালো সিদ্ধান্তের জন্যও প্রশংসা করুন।\n- নিরাপদ ঝুঁকি নিতে আর ছোটখাটো ভুল করতে দিন; এভাবেই বিচারবুদ্ধি তৈরি হয়।\n\n## কখন সাহায্য নেবেন\n\nমেজাজের পরিবর্তন দুই সপ্তাহের বেশি থাকলে, প্রায় ঘুমই না হলে বা সারাদিন ঘুমিয়ে কাটালে, কিংবা ঝুঁকি বিপজ্জনক হয়ে উঠলে — মাদক, নিজের ক্ষতি করা বা হেলমেট ছাড়া বাইক চালানো — ডাক্তার বা কাউন্সেলরের সাথে কথা বলুন।"}'::jsonb, '{}'::jsonb, 4, 4748, 7305, '{}'::text[], 'any', ARRAY['teenage brain', 'risk taking', 'sleep', 'puberty', 'adolescence', 'impulse']::text[], false, 'in_review'::lp_review_status, 8001),
  ('tn-talking-so-teens-talk', 'article', 'general', 'shared', 'important', 'consensus', '👂', '{"en":"Talking so teens talk: listening without lecturing","bn":"যেভাবে বললে কিশোর-কিশোরী কথা বলে: উপদেশ নয়, শুনুন"}'::jsonb, '{"en":"Teens still want their parents'' guidance; they shut down when every talk becomes a lecture. Simple listening habits keep the door open.","bn":"কিশোর-কিশোরীরা এখনও বাবা-মায়ের পরামর্শ চায়; প্রতিটি কথা উপদেশে পরিণত হলে তারা চুপ হয়ে যায়। শোনার কয়েকটি সহজ অভ্যাস কথা বলার পথ খোলা রাখে।"}'::jsonb, '{"en":"Teenagers often go quiet just when parents most want to know what is happening. The good news: teens still want their parents'' guidance. They shut down when every conversation turns into a lecture.\n\n## Listen more than you speak\n\n- Let your teen do most of the talking. Nod, ask and wait.\n- Ask open questions. “What was the best and worst part of today?” works better than “How was school?”\n- Say back what you heard: “So you felt left out when they planned without you.” This shows you understood before you advise.\n- Hold back the instant fix. Ask: “Do you want my ideas, or do you just want me to listen?”\n\n## Choose the right moment\n\nMany teens talk more side by side than face to face: in a rickshaw or car, on a walk, while cooking, or late in the evening. Put your own phone away. A few relaxed minutes every day matter more than one big serious talk.\n\n## Stay calm when you hear hard things\n\nIf your teen shares something worrying, such as a friend who smokes, a fight or a mistake, your first reaction teaches them whether it is safe to tell you again. Breathe, thank them for telling you, and say you will work it out together. You can still set limits and consequences later, once everyone is calm.\n\n## Words that close the door\n\n- Comparing: “Look at your cousin, she got GPA 5.”\n- Brushing off feelings: “That''s nothing, you''re too young to be stressed.”\n- Bringing up old mistakes in every argument.\n- Telling relatives their private stories without asking.\n\n## Words that open it\n\n- “I''m glad you told me.”\n- “That sounds hard. What do you think you''ll do?”\n- “I was wrong to shout. Can we try again?”\n\n## Both parents matter\n\nA father who listens without judging gives his teen a second safe adult at home. Grandparents, aunts and uncles can be trusted listeners too. If one parent finds talking easier for now, let that parent lead while the other keeps showing warmth.\n\n## When to get help\n\nIf your teen stays very withdrawn for weeks, or you notice sadness, hopelessness or any talk of self-harm, read the mental-health guide and speak to a doctor or counsellor.","bn":"বাবা-মা যখন সবচেয়ে বেশি জানতে চান কী হচ্ছে, ঠিক তখনই অনেক কিশোর-কিশোরী চুপ হয়ে যায়। সুখবর হলো, তারা এখনও বাবা-মায়ের পরামর্শ চায়। শুধু প্রতিটি কথা যখন উপদেশে গড়ায়, তখনই তারা মুখ বন্ধ করে ফেলে।\n\n## বলার চেয়ে বেশি শুনুন\n\n- সন্তানকে বেশি বলতে দিন। মাথা নাড়ুন, প্রশ্ন করুন, অপেক্ষা করুন।\n- খোলা প্রশ্ন করুন। “স্কুল কেমন ছিল?” এর চেয়ে “আজ সবচেয়ে ভালো আর সবচেয়ে খারাপ কী হলো?” বেশি কাজে দেয়।\n- যা শুনলেন তা ফিরিয়ে বলুন: “মানে, ওরা তোমাকে বাদ দিয়ে প্ল্যান করায় তোমার খারাপ লেগেছে।” এতে সে বোঝে আপনি আগে বুঝেছেন, তারপর পরামর্শ দিচ্ছেন।\n- সাথে সাথে সমাধান দিতে যাবেন না। জিজ্ঞেস করুন: “তুমি কি আমার পরামর্শ চাও, নাকি শুধু শুনলেই হবে?”\n\n## সঠিক সময় বেছে নিন\n\nঅনেক কিশোর-কিশোরী মুখোমুখি বসার চেয়ে পাশাপাশি থাকলে বেশি কথা বলে — রিকশায় বা গাড়িতে, হাঁটতে হাঁটতে, রান্নার সময় বা রাতের দিকে। নিজের ফোনটা সরিয়ে রাখুন। একবারের বড় গুরুগম্ভীর আলাপের চেয়ে প্রতিদিনের কয়েক মিনিটের হালকা গল্প অনেক বেশি কাজের।\n\n## কঠিন কথা শুনলেও শান্ত থাকুন\n\nসে যদি দুশ্চিন্তার কিছু বলে — কোনো বন্ধু সিগারেট খায়, মারামারি হয়েছে বা নিজে ভুল করেছে — আপনার প্রথম প্রতিক্রিয়া থেকেই সে শেখে, আবার আপনাকে বলা নিরাপদ কিনা। একটা গভীর শ্বাস নিন, বলার জন্য ধন্যবাদ দিন, আর বলুন একসাথে সমাধান করবেন। সবাই শান্ত হলে পরে সীমা আর পরিণাম ঠিক করা যাবে।\n\n## যে কথায় দরজা বন্ধ হয়\n\n- তুলনা করা: “তোমার কাজিন দেখো, জিপিএ-৫ পেয়েছে।”\n- অনুভূতি উড়িয়ে দেওয়া: “এটা কিছুই না, তোমার আবার কিসের টেনশন?”\n- প্রতিটি ঝগড়ায় পুরোনো ভুল টেনে আনা।\n- না জিজ্ঞেস করে তার গোপন কথা আত্মীয়দের বলে দেওয়া।\n\n## যে কথায় দরজা খোলে\n\n- “তুমি আমাকে বলেছ, আমি খুশি হয়েছি।”\n- “ব্যাপারটা কঠিন। তুমি কী করবে ভাবছ?”\n- “চিৎকার করাটা আমার ভুল হয়েছে। চলো আবার কথা বলি।”\n\n## বাবা-মা দুজনেই গুরুত্বপূর্ণ\n\nযে বাবা বিচার না করে শোনেন, তিনি সন্তানকে ঘরে আরেকজন নিরাপদ মানুষ দেন। দাদা-দাদি, নানা-নানি, খালা-চাচারাও ভরসার শ্রোতা হতে পারেন। কারও সাথে সন্তান এখন সহজে কথা বললে আপাতত তিনিই এগিয়ে থাকুন, অন্যজন ভালোবাসা দেখিয়ে যান।\n\n## কখন সাহায্য নেবেন\n\nকয়েক সপ্তাহ ধরে একেবারে গুটিয়ে থাকলে, বা দুঃখ, হতাশা কিংবা নিজের ক্ষতি করার কথা শুনলে মানসিক স্বাস্থ্যের গাইডটি পড়ুন এবং ডাক্তার বা কাউন্সেলরের সাথে কথা বলুন।"}'::jsonb, '{}'::jsonb, 4, 4748, 7305, '{}'::text[], 'any', ARRAY['communication', 'listening', 'teen', 'lecturing', 'trust', 'conversation']::text[], false, 'in_review'::lp_review_status, 8002),
  ('tn-privacy-and-trust', 'article', 'general', 'shared', 'important', 'consensus', '🔐', '{"en":"Privacy and safety: building trust with agreed rules","bn":"গোপনীয়তা আর নিরাপত্তা: একসাথে ঠিক করা নিয়মে আস্থা"}'::jsonb, '{"en":"Teens need some privacy to grow up, and parents still need to keep them safe. Open, agreed rules work better than secret checking.","bn":"বড় হতে কিশোর-কিশোরীর কিছুটা গোপনীয়তা দরকার, আবার বাবা-মাকেও তাদের নিরাপদ রাখতে হয়। গোপনে নজরদারির চেয়ে খোলাখুলি ঠিক করা নিয়ম বেশি কাজে দেয়।"}'::jsonb, '{"en":"As children become teenagers, they want a private life: a closed door, a locked phone, conversations with friends that you don''t hear. This is a normal part of growing up. At the same time, teens face real risks online and outside. The goal is neither total freedom nor total control, but trust built step by step.\n\n## Privacy is a healthy need\n\nTeens use privacy to work out who they are. Secretly reading a diary or every message usually breaks trust. When teens find out, they often become more secretive, not safer.\n\n## Safety still comes first\n\nYou have the right and the duty to step in when there are signs of danger: talk of self-harm, a much older “friend”, drugs, threats or blackmail, unexplained money or gifts, or staying away from home without explanation. Tell your teen you are worried and why, and act, even if they are angry.\n\n## Agree rules openly\n\nSit down together and agree a few clear rules, for example:\n\n- Parents know who their friends are and where they are going.\n- Phones stay out of bedrooms at night.\n- No sharing photos, location or passwords with people met online.\n- Parents may look at apps and privacy settings together with the teen, not secretly.\n- If something online feels wrong, they tell a parent, and won''t lose the phone for telling.\n\nWrite the rules down and review them every month or two. As your teen shows responsibility, give more freedom. If a rule is broken, use a fair consequence linked to that rule, then let them earn trust back.\n\n## Respect goes both ways\n\nKnock before entering. Don''t share their secrets with relatives. Ask before posting their photos. Teens who feel respected are more likely to come to you when they are in trouble, and that is the strongest safety tool you have.\n\n## When to get help\n\nIf you discover blackmail, sexual messages from an adult, or signs of self-harm or drug use, do not handle it alone. Keep any evidence, contact the police on 999 for threats or blackmail, and get help from a doctor or counsellor.","bn":"শিশু যখন কিশোর হয়, সে নিজের একটা আলাদা জগৎ চায় — বন্ধ দরজা, লক করা ফোন, বন্ধুদের সাথে এমন আলাপ যা আপনি শোনেন না। বড় হওয়ার এটা স্বাভাবিক অংশ। আবার অনলাইনে আর বাইরে সত্যিকারের ঝুঁকিও আছে। লক্ষ্য তাই পুরো স্বাধীনতাও নয়, পুরো নিয়ন্ত্রণও নয় — ধাপে ধাপে গড়ে তোলা আস্থা।\n\n## গোপনীয়তা একটা সুস্থ চাহিদা\n\nনিজেকে চিনতে কিশোর-কিশোরীর কিছুটা একান্ত জায়গা লাগে। গোপনে ডায়েরি বা প্রতিটি মেসেজ পড়লে সাধারণত আস্থা ভেঙে যায়। জানতে পারলে তারা আরও লুকোতে শেখে, নিরাপদ হয় না।\n\n## তবু নিরাপত্তা আগে\n\nবিপদের লক্ষণ দেখলে হস্তক্ষেপ করা আপনার অধিকার ও দায়িত্ব: নিজের ক্ষতি করার কথা, অনেক বেশি বয়সী কোনো “বন্ধু”, মাদক, হুমকি বা ব্ল্যাকমেইল, হঠাৎ অজানা টাকা বা উপহার, কিংবা কারণ না বলে বাড়ির বাইরে থাকা। সন্তানকে বলুন আপনি চিন্তিত এবং কেন, তারপর ব্যবস্থা নিন — সে রাগ করলেও।\n\n## খোলাখুলি নিয়ম ঠিক করুন\n\nএকসাথে বসে কয়েকটা পরিষ্কার নিয়ম ঠিক করুন, যেমন:\n\n- বাবা-মা জানবেন তার বন্ধু কারা আর সে কোথায় যাচ্ছে।\n- রাতে ফোন শোবার ঘরের বাইরে থাকবে।\n- অনলাইনে পরিচিত কাউকে ছবি, লোকেশন বা পাসওয়ার্ড দেওয়া যাবে না।\n- বাবা-মা অ্যাপ আর প্রাইভেসি সেটিং দেখবেন সন্তানকে সাথে নিয়ে, গোপনে নয়।\n- অনলাইনে কিছু খারাপ লাগলে সে বাবা-মাকে বলবে — আর বলার জন্য ফোন কেড়ে নেওয়া হবে না।\n\nনিয়মগুলো লিখে রাখুন, এক-দুই মাস পরপর আবার দেখুন। দায়িত্বশীলতা দেখালে স্বাধীনতা বাড়ান। নিয়ম ভাঙলে সেই নিয়মের সাথে মিল রেখে ন্যায্য পরিণাম দিন, তারপর আবার আস্থা অর্জনের সুযোগ দিন।\n\n## সম্মান দুই দিক থেকেই\n\nঘরে ঢোকার আগে দরজায় টোকা দিন। তার গোপন কথা আত্মীয়দের বলবেন না। তার ছবি পোস্ট করার আগে জিজ্ঞেস করুন। যে কিশোর-কিশোরী সম্মান পায়, বিপদে পড়লে সে আপনার কাছেই আসে — আর এটাই আপনার সবচেয়ে বড় নিরাপত্তা।\n\n## কখন সাহায্য নেবেন\n\nব্ল্যাকমেইল, কোনো প্রাপ্তবয়স্কের যৌন মেসেজ, বা নিজের ক্ষতি কিংবা মাদকের লক্ষণ পেলে একা সামলানোর চেষ্টা করবেন না। প্রমাণ রেখে দিন, হুমকি বা ব্ল্যাকমেইলের জন্য ৯৯৯-এ পুলিশে যোগাযোগ করুন, আর ডাক্তার বা কাউন্সেলরের সাহায্য নিন।"}'::jsonb, '{}'::jsonb, 4, 4748, 7305, '{}'::text[], 'any', ARRAY['privacy', 'trust', 'phone', 'rules', 'monitoring', 'safety']::text[], false, 'in_review'::lp_review_status, 8003),
  ('tn-family-rules-together', 'article', 'general', 'shared', 'routine', 'consensus', '🤝', '{"en":"Family rules your teen agrees to: curfew and chores","bn":"যে নিয়মে সন্তানও রাজি: বাড়ি ফেরার সময় ও ঘরের কাজ"}'::jsonb, '{"en":"Teens keep rules they helped make. A short family meeting can settle curfew, chores and consequences without daily fights.","bn":"যে নিয়ম বানাতে সে নিজে অংশ নিয়েছে, সেটাই সে মানে। ছোট একটা পারিবারিক বৈঠকে বাড়ি ফেরার সময়, ঘরের কাজ আর পরিণাম ঠিক করলে রোজকার ঝগড়া কমে।"}'::jsonb, '{"en":"Rules work best with teenagers when they help make them. A teen who agreed to a curfew is far more likely to keep it than one who was simply told.\n\n## Why negotiate\n\nNegotiating teaches skills your teen will need as an adult: explaining a point calmly, listening to others and keeping promises. It does not mean parents give up authority. You still decide the non-negotiables: safety, respect at home, and the faith practice your family holds.\n\n## How to hold a family meeting\n\n1. Pick a calm time, not right after a fight.\n2. Each person says what they need. Parent: “I need to know you''re safe.” Teen: “I want to stay for the whole football match.”\n3. Look for a solution that meets both needs, for example home by 9 pm, with a call if plans change.\n4. Agree a fair consequence if the rule is broken, such as an earlier time next week.\n5. Write it down and set a date to review it.\n\n## Curfew\n\nBase the time on age, distance, transport and safety in your area, not on what other families allow. Know where they are, with whom, and how they will get home. Offer a no-questions pick-up: “If you ever feel unsafe, call me and I will come. We''ll talk later.”\n\n## Chores\n\nTeens can take real responsibility: washing their own clothes, cooking a simple meal, shopping at the bazar, helping younger siblings with homework. Share chores fairly between sons and daughters; a boy who can cook and clean is ready for life. Let them choose some tasks and how to do them.\n\n## Keeping it working\n\n- Praise kept promises, not only good marks.\n- Keep rules the same between both parents and grandparents.\n- When a rule is broken, stay calm, apply the agreed consequence, then move on.\n- Avoid hitting, shaming or insults; they damage trust and do not teach better choices.\n- Loosen rules as trust grows.\n\n## When to get help\n\nIf arguments at home are constant and nothing seems to work, a school counsellor or family therapist can help you find a way forward. If anyone at home is being hurt, seek help straight away.","bn":"কিশোর-কিশোরীর বেলায় নিয়ম সবচেয়ে ভালো কাজ করে যখন তারা নিজেরা তা বানাতে অংশ নেয়। শুধু হুকুম পাওয়ার চেয়ে যে নিজে বাড়ি ফেরার সময়ে রাজি হয়েছে, সে সেটা মানে অনেক বেশি।\n\n## কেন আলোচনা করবেন\n\nআলোচনা করে নিয়ম ঠিক করলে সে এমন দক্ষতা শেখে যা বড় হয়ে লাগবে — শান্তভাবে নিজের কথা বলা, অন্যের কথা শোনা, কথা রাখা। এর মানে এই নয় যে বাবা-মা কর্তৃত্ব ছেড়ে দিচ্ছেন। কিছু বিষয় আলোচনার বাইরে থাকবে: নিরাপত্তা, ঘরে সম্মান, আর আপনার পরিবার যে ধর্মীয় চর্চা মেনে চলে।\n\n## পারিবারিক বৈঠক যেভাবে করবেন\n\n১. শান্ত একটা সময় বেছে নিন, ঝগড়ার ঠিক পরে নয়।\n২. প্রত্যেকে বলুক তার কী দরকার। বাবা-মা: “আমার জানা দরকার তুমি নিরাপদ।” সন্তান: “আমি পুরো ফুটবল ম্যাচটা দেখতে চাই।”\n৩. দুজনের চাহিদা মেটে এমন সমাধান খুঁজুন — যেমন রাত ৯টার মধ্যে ফেরা, আর প্ল্যান বদলালে ফোন করা।\n৪. নিয়ম ভাঙলে কী হবে তা আগেই ঠিক করুন, যেমন পরের সপ্তাহে আরও আগে ফেরা।\n৫. লিখে রাখুন, আর কবে আবার দেখবেন সেই তারিখ ঠিক করুন।\n\n## বাড়ি ফেরার সময়\n\nঅন্য পরিবার কী করে তা দেখে নয়, বয়স, দূরত্ব, যানবাহন আর আপনার এলাকার নিরাপত্তা দেখে সময় ঠিক করুন। কোথায়, কার সাথে, কীভাবে ফিরবে — জেনে রাখুন। একটা প্রতিশ্রুতি দিন: “কখনো অনিরাপদ লাগলে ফোন দিও, আমি এসে নিয়ে যাব। কথা পরে হবে।”\n\n## ঘরের কাজ\n\nএই বয়সে সত্যিকারের দায়িত্ব নিতে পারে: নিজের কাপড় ধোয়া, সহজ একটা রান্না, বাজার করা, ছোট ভাইবোনের পড়া দেখিয়ে দেওয়া। ছেলে-মেয়ে সবার মধ্যে কাজ সমানভাবে ভাগ করুন; যে ছেলে রান্না আর ঘর গোছানো জানে, সে জীবনের জন্য তৈরি। কিছু কাজ আর কীভাবে করবে, তা তাকেই বেছে নিতে দিন।\n\n## নিয়ম টিকিয়ে রাখতে\n\n- শুধু ভালো নম্বরে নয়, কথা রাখলেও প্রশংসা করুন।\n- বাবা, মা, দাদা-দাদি বা নানা-নানি — সবার নিয়ম যেন এক থাকে।\n- নিয়ম ভাঙলে শান্ত থাকুন, ঠিক করা পরিণাম দিন, তারপর বিষয়টা শেষ করুন।\n- মারধর, লজ্জা দেওয়া বা অপমান করবেন না; এতে আস্থা নষ্ট হয়, ভালো সিদ্ধান্ত শেখা হয় না।\n- আস্থা বাড়লে নিয়ম একটু একটু করে শিথিল করুন।\n\n## কখন সাহায্য নেবেন\n\nঘরে প্রতিদিন ঝগড়া লেগেই থাকলে আর কিছুতেই কাজ না হলে স্কুলের কাউন্সেলর বা পারিবারিক থেরাপিস্ট পথ খুঁজে দিতে পারেন। ঘরে কেউ আঘাত পেলে দেরি না করে সাহায্য নিন।"}'::jsonb, '{}'::jsonb, 4, 4748, 7305, '{}'::text[], 'any', ARRAY['family rules', 'curfew', 'chores', 'negotiation', 'family meeting', 'discipline']::text[], false, 'in_review'::lp_review_status, 8004),
  ('tn-puberty-girls', 'article', 'scientific', 'shared', 'important', 'guideline', '🌸', '{"en":"Puberty for girls: periods, hygiene, pain and when to see a doctor","bn":"মেয়েদের বয়ঃসন্ধি: মাসিক, পরিচ্ছন্নতা, ব্যথা ও কখন ডাক্তার দেখাবেন"}'::jsonb, '{"en":"How to prepare your daughter for periods, keep pads or cloth clean, ease pain, prevent anaemia and know which signs need a doctor.","bn":"মেয়েকে মাসিকের জন্য কীভাবে তৈরি করবেন, প্যাড বা কাপড় পরিষ্কার রাখবেন, ব্যথা কমাবেন, রক্তস্বল্পতা ঠেকাবেন — আর কোন লক্ষণে ডাক্তার দেখাবেন।"}'::jsonb, '{"en":"Most girls start puberty between about 8 and 13 years. Breasts usually begin to develop first, then body hair grows, hips widen and there is a growth spurt. The first period usually comes about two years after the breasts start to grow, often between 10 and 15 years.\n\n## Talk before it happens\n\nA girl who has never heard about periods can be frightened when she first sees blood. Explain early, calmly and simply: a period is a normal monthly bleed from the womb, it shows the body is growing healthily, and it is nothing to be ashamed of. Mothers, aunts or an older sister often lead this talk, but fathers should know the basics too, especially in single-father homes.\n\n## Pads or cloth: keeping clean\n\n- Disposable pads: change every 4–6 hours, or more often if bleeding is heavy. Wrap used pads in paper and put them in a bin; never flush them.\n- Cloth: use clean, soft cotton cloth. Wash it with soap and clean water, dry it fully in sunlight, and store it in a clean, dry place. Cloth that stays damp or is dried in hidden corners can cause infection.\n- Wash hands before and after changing, and wash the outer genital area with plain water daily. Special soaps, powders or washing inside are not needed.\n- Keep a spare pad or cloth and spare underwear in her school bag.\n\nAsk the school whether the girls'' toilet has water, a bin and a door that locks. Many girls miss school when these are missing.\n\n## Period pain\n\nMild cramps on the first day or two are common. A hot-water bottle on the lower tummy, gentle walking, warm drinks and rest help. A simple painkiller such as paracetamol can be used as your doctor or pharmacist advises. A period is not a reason to stop normal food, bathing or school.\n\n## Iron and anaemia\n\nMonthly blood loss and fast growth increase the need for iron. A girl who is often tired, pale, breathless or dizzy may have anaemia. Give iron-rich food every day, and use iron–folic acid tablets if offered through school or a health programme, as the health worker advises.\n\n## When to see a doctor\n\n- No breast development by 13, or no period by 15.\n- Periods lasting more than 7 days, or soaking a pad every 1–2 hours.\n- Pain that makes her miss school regularly, or that painkillers do not help.\n- Periods still very irregular two to three years after they began.\n- Feeling faint, very pale or short of breath.\n- Bleeding between periods, itching, or a foul-smelling discharge.","bn":"বেশিরভাগ মেয়ের বয়ঃসন্ধি শুরু হয় মোটামুটি ৮ থেকে ১৩ বছরের মধ্যে। সাধারণত প্রথমে স্তন বাড়তে শুরু করে, তারপর শরীরে লোম গজায়, কোমর চওড়া হয়, আর হঠাৎ লম্বা হয়ে ওঠে। প্রথম মাসিক (পিরিয়ড) সাধারণত স্তন বাড়া শুরুর প্রায় দুই বছর পরে হয়, প্রায়ই ১০ থেকে ১৫ বছরের মধ্যে।\n\n## আগেভাগেই কথা বলুন\n\nযে মেয়ে কখনো মাসিকের কথা শোনেনি, প্রথমবার রক্ত দেখে সে ভয় পেয়ে যেতে পারে। আগেই শান্তভাবে, সহজ ভাষায় বুঝিয়ে বলুন: মাসিক হলো জরায়ু থেকে প্রতি মাসে হওয়া স্বাভাবিক রক্তস্রাব, এটা শরীর সুস্থভাবে বেড়ে ওঠার লক্ষণ, এতে লজ্জার কিছু নেই। সাধারণত মা, খালা-ফুপু বা বড় বোন এই আলাপটা করেন, তবে বাবারও মূল কথাগুলো জানা উচিত — বিশেষ করে যেখানে বাবা একাই সন্তান বড় করছেন।\n\n## প্যাড বা কাপড়: পরিচ্ছন্ন থাকা\n\n- স্যানিটারি প্যাড: প্রতি ৪–৬ ঘণ্টায় বদলাতে হবে, রক্তপাত বেশি হলে আরও আগে। ব্যবহৃত প্যাড কাগজে মুড়ে ডাস্টবিনে ফেলুন; কখনো কমোডে ফেলবেন না।\n- কাপড়: পরিষ্কার, নরম সুতি কাপড় ব্যবহার করুন। সাবান আর পরিষ্কার পানি দিয়ে ধুয়ে কড়া রোদে পুরোপুরি শুকিয়ে পরিষ্কার, শুকনো জায়গায় রাখুন। স্যাঁতসেঁতে বা লুকিয়ে চিপায় শুকানো কাপড় থেকে সংক্রমণ হতে পারে।\n- প্যাড বা কাপড় বদলানোর আগে ও পরে হাত ধুতে হবে, আর প্রতিদিন যৌনাঙ্গের বাইরের অংশ শুধু পানি দিয়ে ধুলেই চলে। আলাদা সাবান, পাউডার বা ভেতরে ধোয়ার দরকার নেই।\n- স্কুলব্যাগে একটা বাড়তি প্যাড বা কাপড় আর বাড়তি অন্তর্বাস রাখুন।\n\nস্কুলে মেয়েদের টয়লেটে পানি, ডাস্টবিন আর ভেতর থেকে আটকানো যায় এমন দরজা আছে কিনা খোঁজ নিন। এগুলো না থাকলে অনেক মেয়ে ওই কয়দিন স্কুলে যায় না।\n\n## মাসিকের ব্যথা\n\nপ্রথম এক-দুই দিন তলপেটে হালকা ব্যথা খুব সাধারণ। তলপেটে গরম পানির ব্যাগ, হালকা হাঁটাহাঁটি, গরম পানীয় আর বিশ্রামে আরাম মেলে। ডাক্তার বা ফার্মাসিস্টের পরামর্শমতো প্যারাসিটামলের মতো সাধারণ ব্যথার ওষুধ খাওয়া যায়। মাসিকের জন্য স্বাভাবিক খাবার, গোসল বা স্কুল বন্ধ করার কোনো কারণ নেই।\n\n## আয়রন ও রক্তস্বল্পতা\n\nপ্রতি মাসের রক্তক্ষরণ আর দ্রুত বেড়ে ওঠার কারণে এই বয়সে আয়রন বেশি লাগে। মেয়ে যদি প্রায়ই ক্লান্ত থাকে, ফ্যাকাশে দেখায়, হাঁপিয়ে যায় বা মাথা ঘোরে, তাহলে রক্তস্বল্পতা (anaemia) থাকতে পারে। প্রতিদিন আয়রনসমৃদ্ধ খাবার দিন, আর স্কুল বা স্বাস্থ্য কর্মসূচি থেকে আয়রন–ফলিক অ্যাসিড ট্যাবলেট দিলে স্বাস্থ্যকর্মীর পরামর্শমতো খাওয়ান।\n\n## কখন ডাক্তার দেখাবেন\n\n- ১৩ বছরেও স্তন বাড়া শুরু না হলে, বা ১৫ বছরেও মাসিক না হলে।\n- মাসিক ৭ দিনের বেশি চললে, বা প্রতি ১–২ ঘণ্টায় প্যাড ভিজে গেলে।\n- ব্যথার জন্য নিয়মিত স্কুল কামাই হলে, বা ওষুধেও ব্যথা না কমলে।\n- মাসিক শুরুর দুই-তিন বছর পরও খুব অনিয়মিত থাকলে।\n- মাথা ঘুরে পড়ে যাওয়ার মতো লাগলে, খুব ফ্যাকাশে হলে বা শ্বাসকষ্ট হলে।\n- দুই মাসিকের মাঝে রক্তপাত, চুলকানি বা দুর্গন্ধযুক্ত স্রাব হলে।"}'::jsonb, '{}'::jsonb, 5, 4748, 7305, '{}'::text[], 'female', ARRAY['puberty', 'periods', 'menstruation', 'pads', 'menstrual hygiene', 'period pain', 'anaemia', 'girls']::text[], false, 'in_review'::lp_review_status, 8005),
  ('tn-puberty-boys', 'article', 'scientific', 'shared', 'important', 'guideline', '🧑', '{"en":"Puberty for boys: voice, growth, wet dreams and hygiene","bn":"ছেলেদের বয়ঃসন্ধি: কণ্ঠস্বর, বেড়ে ওঠা, ঘুমের মধ্যে বীর্যপাত ও পরিচ্ছন্নতা"}'::jsonb, '{"en":"What changes in a boy''s body, how to explain wet dreams calmly, daily hygiene, and the few signs that need a doctor.","bn":"ছেলের শরীরে কী কী বদলায়, ঘুমের মধ্যে বীর্যপাতের কথা কীভাবে শান্তভাবে বোঝাবেন, প্রতিদিনের পরিচ্ছন্নতা, আর কোন লক্ষণে ডাক্তার দেখাবেন।"}'::jsonb, '{"en":"Boys usually start puberty between about 9 and 14 years, often a year or two later than girls. Every boy has his own timing, and being a little early or late is usually normal.\n\n## What changes\n\n- The testicles grow first, then hair appears in the pubic area, under the arms and later on the face.\n- A big growth spurt: height, shoulders and muscles increase, and appetite rises.\n- The voice “breaks”: it may crack or jump between high and low for some months, then settles deeper.\n- More sweat, body odour and pimples (acne).\n- Some boys get slight swelling or tenderness under one or both nipples. This is common and usually settles by itself.\n\n## Wet dreams, explained calmly\n\nAs hormones rise, many boys release semen during sleep, sometimes with a dream. This is called a wet dream (nocturnal emission). It is a normal sign of the body maturing. It is not an illness, not a weakness, and not something to be ashamed of. It does not drain strength or harm health, despite what many boys hear from friends. Tell your son before it happens so he is not confused or worried. Religious guidance on bathing afterwards is covered in the app''s Islamic section.\n\n## Hygiene\n\n- Bathe daily, especially after sport, and wash under the arms and the genital area.\n- Change underwear and socks every day.\n- Wash the face twice a day with mild soap; don''t squeeze pimples.\n- When he is ready, show him how to shave safely, and not to share razors.\n\n## Who should talk to him\n\nFathers, uncles or an older brother are often the best people to explain these changes, but mothers can too. Keep it short, matter-of-fact and open to questions: “If anything about your body worries you, you can always ask me or the doctor.” If you feel awkward, a trusted doctor can explain.\n\n## When to see a doctor\n\n- No signs of puberty by 14.\n- A lump, swelling or ongoing pain in a testicle.\n- Sudden, severe pain in a testicle: this is an emergency. Go to hospital now.\n- Breast swelling that is large, painful or not settling.\n- Severe acne that scars or upsets him a lot.\n- Worries about height, weight or body changes that are affecting his mood.","bn":"ছেলেদের বয়ঃসন্ধি সাধারণত শুরু হয় মোটামুটি ৯ থেকে ১৪ বছরের মধ্যে, প্রায়ই মেয়েদের চেয়ে এক-দুই বছর পরে। প্রত্যেকের সময় আলাদা; একটু আগে বা পরে হওয়া সাধারণত স্বাভাবিক।\n\n## কী কী বদলায়\n\n- প্রথমে অণ্ডকোষ বড় হয়, তারপর যৌনাঙ্গের চারপাশে, বগলে আর পরে মুখে লোম গজায়।\n- হঠাৎ দ্রুত বেড়ে ওঠা: উচ্চতা, কাঁধ আর পেশি বাড়ে, খিদেও বাড়ে।\n- গলা “ভাঙে”: কয়েক মাস কণ্ঠ কখনো চিকন, কখনো মোটা হয়, তারপর ভারী হয়ে স্থির হয়।\n- ঘাম, গায়ের গন্ধ আর ব্রণ বাড়ে।\n- কারও কারও এক বা দুই বোঁটার নিচে সামান্য ফোলা বা ব্যথা হয়। এটা খুব সাধারণ, সাধারণত নিজে থেকেই সেরে যায়।\n\n## ঘুমের মধ্যে বীর্যপাত: শান্তভাবে বুঝিয়ে বলুন\n\nহরমোন বাড়ার সাথে সাথে অনেক ছেলের ঘুমের মধ্যে বীর্যপাত হয়, কখনো স্বপ্নের সাথে। অনেকে একে “স্বপ্নদোষ” বলেন, কিন্তু এটা আসলে কোনো দোষ নয়। এটা শরীর পরিণত হওয়ার স্বাভাবিক লক্ষণ — কোনো রোগ নয়, দুর্বলতা নয়, লজ্জারও কিছু নয়। বন্ধুদের কাছে যা-ই শুনুক, এতে শক্তি কমে না বা স্বাস্থ্যের ক্ষতি হয় না। ঘটার আগেই ছেলেকে জানিয়ে রাখুন, যেন সে বিভ্রান্ত বা ভীত না হয়। এরপর গোসল নিয়ে ধর্মীয় নির্দেশনা অ্যাপের ইসলামিক অংশে আলাদা করে আছে।\n\n## পরিচ্ছন্নতা\n\n- প্রতিদিন গোসল করবে, বিশেষ করে খেলাধুলার পরে; বগল আর যৌনাঙ্গ ভালোভাবে ধোবে।\n- প্রতিদিন অন্তর্বাস আর মোজা বদলাবে।\n- দিনে দুবার হালকা সাবানে মুখ ধোবে; ব্রণ টিপবে না।\n- সময় হলে নিরাপদে শেভ করা শিখিয়ে দিন, আর রেজর কারও সাথে ভাগ না করতে বলুন।\n\n## কে কথা বলবেন\n\nবাবা, চাচা-মামা বা বড় ভাই অনেক সময় এই পরিবর্তনগুলো সবচেয়ে ভালো বোঝাতে পারেন, তবে মা-ও পারেন। কথা ছোট রাখুন, সহজভাবে বলুন, প্রশ্নের সুযোগ রাখুন: “শরীর নিয়ে কিছু নিয়ে চিন্তা হলে আমাকে বা ডাক্তারকে যেকোনো সময় জিজ্ঞেস করতে পারো।” নিজের অস্বস্তি লাগলে ভরসার কোনো ডাক্তার বুঝিয়ে বলতে পারেন।\n\n## কখন ডাক্তার দেখাবেন\n\n- ১৪ বছরেও বয়ঃসন্ধির কোনো লক্ষণ না দেখা দিলে।\n- অণ্ডকোষে চাকা, ফোলা বা লেগে থাকা ব্যথা হলে।\n- অণ্ডকোষে হঠাৎ তীব্র ব্যথা হলে — এটা জরুরি অবস্থা, এখনই হাসপাতালে যান।\n- বুকের ফোলা বড় হলে, ব্যথা করলে বা না কমলে।\n- ব্রণ খুব বেশি হয়ে দাগ ফেললে বা তাকে খুব মন খারাপ করে দিলে।\n- উচ্চতা, ওজন বা শরীরের পরিবর্তন নিয়ে দুশ্চিন্তায় মন ভেঙে পড়লে।"}'::jsonb, '{}'::jsonb, 4, 4748, 7305, '{}'::text[], 'male', ARRAY['puberty', 'boys', 'voice change', 'wet dreams', 'hygiene', 'growth spurt', 'acne']::text[], false, 'in_review'::lp_review_status, 8006),
  ('tn-body-image-eating', 'article', 'scientific', 'shared', 'important', 'consensus', '🪞', '{"en":"Body image, eating and the signs of an eating disorder","bn":"শরীর নিয়ে ধারণা, খাওয়াদাওয়া ও খাদ্যাভ্যাসজনিত রোগের লক্ষণ"}'::jsonb, '{"en":"Fast-changing bodies and online comparison make many teens unhappy with how they look. How to protect body confidence, and the warning signs of an eating disorder.","bn":"দ্রুত বদলানো শরীর আর অনলাইনে তুলনার কারণে অনেক কিশোর-কিশোরী নিজের চেহারা নিয়ে অসন্তুষ্ট থাকে। কীভাবে আত্মবিশ্বাস রক্ষা করবেন, আর খাদ্যাভ্যাসজনিত রোগের সতর্কসংকেত কী।"}'::jsonb, '{"en":"During puberty bodies change fast, and teens compare themselves with friends, film stars and filtered photos online. Many worry about being too fat, too thin, too dark, too short or not muscular enough. Most of this passes, but for some it grows into unhealthy eating or an eating disorder.\n\n## How families can help\n\n- Comment on effort, kindness and skills, not on weight or skin colour. Remarks like “You''ve got fat” or “Use fairness cream” hurt deeply, even from loving relatives.\n- Eat regular family meals together, without talk of dieting.\n- Talk about how photos online are edited and filtered.\n- Encourage activity for fun and strength, not to “burn off” food.\n- Notice what you say about your own body; teens copy it.\n- Politely ask relatives not to tease about appearance.\n\n## Healthy eating for teens\n\nGrowing teens need three meals and healthy snacks: rice or roti, dal, fish, eggs, meat, milk, vegetables and fruit. Skipping meals, especially breakfast, makes it harder to concentrate. Limit sugary drinks, fried snacks and fast food, but avoid labelling foods as forbidden; that can make cravings and guilt worse.\n\n## Warning signs of an eating disorder\n\n- Fast weight loss, or not gaining weight while growing.\n- Skipping meals, eating very little, or avoiding family meals.\n- Strong fear of gaining weight; checking the mirror or scales again and again.\n- Eating large amounts in secret, then feeling ashamed.\n- Going to the bathroom straight after meals, or using vomiting or pills to lose weight.\n- Exercising hard even when ill or injured.\n- Periods stopping in girls; dizziness, fainting, or feeling cold all the time.\n\nEating disorders affect boys too, sometimes as an obsession with muscles or supplements. Be cautious about powders and pills sold online for muscle gain or weight loss.\n\n## What to do\n\nIf you notice several signs, talk privately and gently: “I''ve noticed you''re skipping meals and seem worried. I care about you. Can we see a doctor together?” Avoid blame or forcing food. See a doctor soon; eating disorders are serious but treatable, and early help works best. Fainting, chest pain, confusion or vomiting blood need emergency care now: call 999 or go to hospital.","bn":"বয়ঃসন্ধিতে শরীর দ্রুত বদলায়, আর কিশোর-কিশোরীরা নিজেদের তুলনা করে বন্ধু, সিনেমার তারকা আর অনলাইনের ফিল্টার করা ছবির সাথে। অনেকেই ভাবে সে বেশি মোটা, বেশি চিকন, বেশি কালো, খাটো, বা যথেষ্ট পেশিবহুল নয়। বেশিরভাগের এই চিন্তা সময়ের সাথে কেটে যায়, কিন্তু কারও কারও বেলায় তা অস্বাস্থ্যকর খাওয়া বা খাদ্যাভ্যাসজনিত রোগে (eating disorder) গড়ায়।\n\n## পরিবার যেভাবে সাহায্য করতে পারে\n\n- ওজন বা গায়ের রং নয়, চেষ্টা, দয়া আর দক্ষতা নিয়ে কথা বলুন। “মোটা হয়ে গেছ” বা “ফর্সা হওয়ার ক্রিম মাখো” — এমন কথা ভালোবাসার মানুষের মুখ থেকে এলেও গভীরভাবে আঘাত করে।\n- নিয়মিত পরিবারের সবাই একসাথে খান, ডায়েট নিয়ে আলোচনা ছাড়া।\n- অনলাইনের ছবি কীভাবে এডিট আর ফিল্টার করা হয়, তা নিয়ে কথা বলুন।\n- খাবার “পোড়ানোর” জন্য নয়, আনন্দ আর শক্তির জন্য খেলাধুলায় উৎসাহ দিন।\n- নিজের শরীর নিয়ে আপনি কী বলেন খেয়াল করুন; সন্তান সেটাই শেখে।\n- আত্মীয়দের ভদ্রভাবে অনুরোধ করুন চেহারা নিয়ে ঠাট্টা না করতে।\n\n## কিশোর বয়সের স্বাস্থ্যকর খাবার\n\nবেড়ে ওঠার এই সময়ে তিন বেলা খাবার আর মাঝে স্বাস্থ্যকর নাশতা দরকার: ভাত বা রুটি, ডাল, মাছ, ডিম, মাংস, দুধ, শাকসবজি আর ফল। খাবার বাদ দিলে, বিশেষ করে সকালের নাশতা, পড়ায় মন বসানো কঠিন হয়। চিনিযুক্ত পানীয়, ভাজাপোড়া আর ফাস্টফুড কমান, তবে কোনো খাবারকে “নিষিদ্ধ” বলে দাগিয়ে দেবেন না; এতে লোভ আর অপরাধবোধ দুটোই বাড়ে।\n\n## খাদ্যাভ্যাসজনিত রোগের সতর্কসংকেত\n\n- দ্রুত ওজন কমে যাওয়া, বা বাড়ার বয়সেও ওজন না বাড়া।\n- বেলা বাদ দেওয়া, খুব কম খাওয়া, বা পরিবারের সাথে খেতে না বসা।\n- ওজন বাড়ার তীব্র ভয়; বারবার আয়না দেখা বা ওজন মাপা।\n- লুকিয়ে অনেক খেয়ে ফেলা, তারপর লজ্জা পাওয়া।\n- খাওয়ার ঠিক পরেই বাথরুমে যাওয়া, বা ওজন কমাতে বমি করা বা ওষুধ খাওয়া।\n- অসুস্থ বা আহত অবস্থায়ও জোর করে ব্যায়াম করা।\n- মেয়েদের মাসিক বন্ধ হয়ে যাওয়া; মাথা ঘোরা, অজ্ঞান হওয়া বা সবসময় শীত লাগা।\n\nছেলেরাও এতে আক্রান্ত হয়, কখনো পেশি বা সাপ্লিমেন্টের প্রতি অতিরিক্ত ঝোঁক হিসেবে। অনলাইনে বিক্রি হওয়া পেশি বাড়ানো বা ওজন কমানোর পাউডার ও ওষুধ নিয়ে সতর্ক থাকুন।\n\n## কী করবেন\n\nকয়েকটি লক্ষণ চোখে পড়লে একান্তে, নরমভাবে কথা বলুন: “দেখছি তুমি খাবার বাদ দিচ্ছ, আর কেমন যেন চিন্তায় আছ। তোমাকে নিয়ে আমার চিন্তা হয়। চলো একসাথে ডাক্তারের কাছে যাই?” দোষ দেবেন না, জোর করে খাওয়াবেন না। দ্রুত ডাক্তার দেখান; এই রোগ গুরুতর হলেও চিকিৎসায় সারে, আর যত আগে সাহায্য নেওয়া যায় তত ভালো। অজ্ঞান হয়ে পড়া, বুকে ব্যথা, বিভ্রান্তি বা রক্তবমি হলে এখনই জরুরি চিকিৎসা দরকার: ৯৯৯-এ ফোন করুন বা হাসপাতালে যান।"}'::jsonb, '{}'::jsonb, 4, 4748, 7305, '{}'::text[], 'any', ARRAY['body image', 'eating disorder', 'anorexia', 'bulimia', 'dieting', 'weight', 'skin colour']::text[], false, 'in_review'::lp_review_status, 8007),
  ('tn-iron-anaemia', 'article', 'scientific', 'shared', 'important', 'guideline', '🥬', '{"en":"Iron-rich food and anaemia in teenage girls","bn":"আয়রনসমৃদ্ধ খাবার ও কিশোরীদের রক্তস্বল্পতা"}'::jsonb, '{"en":"Anaemia is common in adolescent girls in Bangladesh and often goes unnoticed. Simple food choices, iron–folic acid tablets when offered, and a blood test can fix it.","bn":"বাংলাদেশে কিশোরীদের মধ্যে রক্তস্বল্পতা বেশ সাধারণ, আর প্রায়ই তা চোখ এড়িয়ে যায়। সহজ কিছু খাবার, দেওয়া হলে আয়রন–ফলিক অ্যাসিড ট্যাবলেট আর একটা রক্ত পরীক্ষা দিয়েই এর সমাধান সম্ভব।"}'::jsonb, '{"en":"Anaemia means the blood does not have enough healthy red cells or haemoglobin to carry oxygen around the body. It is common among adolescent girls in Bangladesh, and it often goes unnoticed because the signs build up slowly.\n\n## Why teenage girls are at risk\n\n- Fast growth during puberty needs more iron.\n- Monthly periods lose iron with the blood.\n- Meals that are mostly rice, with little fish, meat, eggs or green vegetables, give too little iron.\n- Worm infections can also cause blood loss.\n- In some homes girls eat last or less; make sure your daughter gets her fair share.\n\nBoys need extra iron during their growth spurt too, so the same foods help the whole family.\n\n## Signs of anaemia\n\n- Tiredness, weakness, poor concentration in class.\n- Pale skin, inner eyelids, lips or nails.\n- Breathlessness or a racing heart when climbing stairs.\n- Dizziness, headaches, feeling cold.\n\nA simple haemoglobin blood test at a health centre or Upazila Health Complex can confirm it.\n\n## Iron-rich foods\n\n- From animals, and best absorbed: liver, red meat, chicken, fish, including small fish eaten whole, and eggs.\n- From plants: dal (lentils), chickpeas, beans, dark green leafy vegetables such as lal shak, pui shak and kochu shak, and seeds.\n\n## Help the body absorb iron\n\n- Eat vitamin C foods with meals: guava, amloki, lemon, orange, tomato.\n- Keep tea and coffee away from mealtimes, as they reduce iron absorption.\n\n## Iron–folic acid tablets\n\nSchool and health programmes in Bangladesh may give adolescent girls a weekly iron–folic acid tablet. Take it as the health worker advises; taking it after food can reduce stomach upset. Dark or black stools while taking iron are expected. Do not give extra iron tablets without advice, because too much iron is harmful, and keep all iron tablets out of reach of small children.\n\n## Deworming\n\nDeworming tablets are often given through school campaigns. Take them as advised, and wear shoes or sandals outside and wash hands before eating to prevent worms.\n\n## When to see a doctor\n\nSee a doctor if signs of anaemia do not improve after some weeks of better food and tablets, if periods are very heavy or long, or if your teen feels faint or very breathless.","bn":"রক্তস্বল্পতা (anaemia) মানে রক্তে যথেষ্ট সুস্থ লোহিত কণিকা বা হিমোগ্লোবিন নেই, যা সারা শরীরে অক্সিজেন বয়ে নিয়ে যায়। বাংলাদেশে কিশোরীদের মধ্যে এটা বেশ সাধারণ, আর লক্ষণগুলো ধীরে ধীরে আসে বলে প্রায়ই কেউ খেয়াল করে না।\n\n## কেন কিশোরীদের ঝুঁকি বেশি\n\n- বয়ঃসন্ধিতে দ্রুত বেড়ে ওঠায় আয়রন বেশি লাগে।\n- প্রতি মাসে মাসিকের রক্তের সাথে আয়রন বেরিয়ে যায়।\n- শুধু ভাতনির্ভর খাবারে, যেখানে মাছ, মাংস, ডিম বা সবুজ শাকসবজি কম, আয়রন যথেষ্ট থাকে না।\n- কৃমির সংক্রমণেও রক্তক্ষয় হতে পারে।\n- কোনো কোনো পরিবারে মেয়েরা সবার শেষে বা কম খায়; খেয়াল রাখুন আপনার মেয়ে যেন তার ন্যায্য ভাগ পায়।\n\nবেড়ে ওঠার সময় ছেলেদেরও বাড়তি আয়রন লাগে, তাই এই খাবারগুলো পুরো পরিবারের জন্যই ভালো।\n\n## রক্তস্বল্পতার লক্ষণ\n\n- ক্লান্তি, দুর্বলতা, ক্লাসে মন বসাতে না পারা।\n- ত্বক, চোখের পাতার ভেতর, ঠোঁট বা নখ ফ্যাকাশে।\n- সিঁড়ি ভাঙলে হাঁপিয়ে যাওয়া বা বুক ধড়ফড় করা।\n- মাথা ঘোরা, মাথাব্যথা, শীত শীত লাগা।\n\nস্বাস্থ্যকেন্দ্র বা উপজেলা স্বাস্থ্য কমপ্লেক্সে হিমোগ্লোবিনের একটা সাধারণ রক্ত পরীক্ষা করলেই নিশ্চিত হওয়া যায়।\n\n## আয়রনসমৃদ্ধ খাবার\n\n- প্রাণিজ উৎস, যা থেকে শরীর সবচেয়ে ভালোভাবে আয়রন নেয়: কলিজা, গরু-খাসির মাংস, মুরগি, মাছ — কাঁটাসহ খাওয়া ছোট মাছও — আর ডিম।\n- উদ্ভিজ্জ উৎস: ডাল, ছোলা, শিম-বরবটি জাতীয় বীজ, গাঢ় সবুজ শাক যেমন লালশাক, পুঁইশাক, কচুশাক, আর বিভিন্ন বীজ।\n\n## আয়রন শরীরে নিতে সাহায্য করুন\n\n- খাবারের সাথে ভিটামিন সি-যুক্ত খাবার খান: পেয়ারা, আমলকী, লেবু, কমলা, টমেটো।\n- খাবারের আগে-পরে চা-কফি এড়িয়ে চলুন; এগুলো আয়রন শোষণ কমায়।\n\n## আয়রন–ফলিক অ্যাসিড ট্যাবলেট\n\nবাংলাদেশে স্কুল বা স্বাস্থ্য কর্মসূচির মাধ্যমে কিশোরীদের সপ্তাহে একটি আয়রন–ফলিক অ্যাসিড ট্যাবলেট দেওয়া হতে পারে। স্বাস্থ্যকর্মীর পরামর্শমতো খান; খাবারের পরে খেলে পেটের অস্বস্তি কম হয়। আয়রন খাওয়ার সময় পায়খানা কালচে হওয়া স্বাভাবিক। পরামর্শ ছাড়া বাড়তি আয়রন ট্যাবলেট দেবেন না, কারণ বেশি আয়রন ক্ষতিকর; আর সব আয়রন ট্যাবলেট ছোট শিশুদের নাগালের বাইরে রাখুন।\n\n## কৃমিনাশক\n\nস্কুলের কর্মসূচিতে প্রায়ই কৃমিনাশক ট্যাবলেট দেওয়া হয়; পরামর্শমতো খান। কৃমি ঠেকাতে বাইরে জুতা-স্যান্ডেল পরুন, খাওয়ার আগে হাত ধুয়ে নিন।\n\n## কখন ডাক্তার দেখাবেন\n\nকয়েক সপ্তাহ ভালো খাবার আর ট্যাবলেট খাওয়ার পরও লক্ষণ না কমলে, মাসিক খুব বেশি বা দীর্ঘ হলে, কিংবা মাথা ঘুরে পড়ে যাওয়ার মতো লাগলে বা খুব শ্বাসকষ্ট হলে ডাক্তার দেখান।"}'::jsonb, '{}'::jsonb, 4, 4748, 7305, '{}'::text[], 'any', ARRAY['iron', 'anaemia', 'girls', 'iron folic acid', 'diet', 'deworming', 'haemoglobin']::text[], false, 'in_review'::lp_review_status, 8008),
  ('tn-teen-mental-health', 'article', 'scientific', 'shared', 'important', 'guideline', '💚', '{"en":"Mental health in teens: stress, depression, anxiety and signs to act on","bn":"কৈশোরের মানসিক স্বাস্থ্য: মানসিক চাপ, বিষণ্নতা, উদ্বেগ ও যে লক্ষণে ব্যবস্থা নেবেন"}'::jsonb, '{"en":"Depression and anxiety often begin in the teen years and can look like laziness or bad behaviour. What is normal, what to watch for, and where to get help in Bangladesh.","bn":"বিষণ্নতা আর উদ্বেগ প্রায়ই কৈশোরে শুরু হয়, আর তা দেখতে আলসেমি বা খারাপ আচরণের মতো লাগতে পারে। কোনটা স্বাভাবিক, কী খেয়াল রাখবেন, আর বাংলাদেশে কোথায় সাহায্য পাবেন।"}'::jsonb, '{"en":"The teen years bring pressure: exams, friendships, changing bodies, social media and worries about the future. Some stress is normal and can even help a teen prepare. But depression and anxiety often begin in adolescence and are easy to miss, because they can look like laziness or bad behaviour.\n\n## Normal ups and downs\n\nMoodiness, wanting time alone, arguing about rules and worrying before exams are part of growing up, as long as your teen still sleeps, eats, studies, sees friends and enjoys some things.\n\n## Signs to watch for\n\nLook for changes that last two weeks or more:\n\n- Sadness, crying, irritability or anger most days.\n- Losing interest in things they used to enjoy.\n- Sleeping or eating much more or much less than usual.\n- Pulling away from friends and family.\n- Falling grades, skipping school, trouble concentrating.\n- Constant worry, panic attacks, or stomach aches and headaches with no medical cause.\n- Saying they feel worthless, hopeless or a burden.\n- Using cigarettes, vapes, drugs or alcohol to cope.\n\n## How to talk\n\nPick a quiet moment and say what you have noticed, without blame: “You seem low lately, and you''ve stopped playing football. I''m worried and I want to understand.” Listen, and take their feelings seriously even if the cause seems small to you. Avoid “Others have it worse” or “It''s all in your head”. For many families faith and prayer bring real comfort; they work best alongside medical care, not instead of it.\n\n## What helps\n\n- Regular sleep, daily physical activity and regular meals.\n- Time with supportive friends and family.\n- Limits on late-night phone use.\n- Less pressure about marks, more praise for effort.\n- Learning to name feelings and calm the body: slow breathing, a walk, writing thoughts down.\n\n## Getting help\n\nTalk to a school counsellor, your doctor, a psychiatrist or a clinical psychologist. In Bangladesh, psychiatry departments of medical college hospitals and the National Institute of Mental Health in Dhaka see young people. Depression and anxiety are common and treatable, and early help works best.\n\n## Act now if\n\nYour teen talks about wanting to die, harms themselves, or you fear they are not safe. Stay with them and call 999 or go to the nearest hospital emergency now.","bn":"কৈশোর মানেই নানা চাপ: পরীক্ষা, বন্ধুত্ব, বদলে যাওয়া শরীর, সোশ্যাল মিডিয়া আর ভবিষ্যৎ নিয়ে দুশ্চিন্তা। কিছুটা চাপ স্বাভাবিক, এমনকি প্রস্তুতিতেও সাহায্য করে। কিন্তু বিষণ্নতা (depression) আর উদ্বেগ (anxiety) প্রায়ই এই বয়সেই শুরু হয়, আর সহজে চোখ এড়িয়ে যায় — কারণ এগুলো দেখতে আলসেমি বা বেয়াদবির মতো লাগে।\n\n## স্বাভাবিক ওঠানামা\n\nমেজাজ বদলানো, একা থাকতে চাওয়া, নিয়ম নিয়ে তর্ক করা, পরীক্ষার আগে দুশ্চিন্তা — এসব বড় হওয়ারই অংশ, যদি সে ঠিকমতো ঘুমায়, খায়, পড়াশোনা করে, বন্ধুদের সাথে মেশে আর কিছু কাজে আনন্দ পায়।\n\n## যে লক্ষণ খেয়াল রাখবেন\n\nদুই সপ্তাহ বা তার বেশি সময় ধরে থাকা পরিবর্তন:\n\n- বেশিরভাগ দিন মন খারাপ, কান্না, খিটখিটে মেজাজ বা রাগ।\n- আগে যা ভালো লাগত, তাতে আর আগ্রহ না থাকা।\n- স্বাভাবিকের চেয়ে অনেক বেশি বা অনেক কম ঘুম বা খাওয়া।\n- বন্ধু আর পরিবার থেকে দূরে সরে যাওয়া।\n- ফল খারাপ হওয়া, স্কুল ফাঁকি দেওয়া, মনোযোগ দিতে না পারা।\n- সারাক্ষণ দুশ্চিন্তা, হঠাৎ প্রচণ্ড ভয় (প্যানিক অ্যাটাক), বা কারণ ছাড়া পেটব্যথা-মাথাব্যথা।\n- নিজেকে মূল্যহীন, আশাহীন বা সবার বোঝা মনে করার কথা বলা।\n- সামলাতে সিগারেট, ভেপ, মাদক বা মদ ব্যবহার করা।\n\n## কীভাবে কথা বলবেন\n\nনিরিবিলি একটা সময়ে দোষ না দিয়ে যা দেখেছেন তা বলুন: “কিছুদিন ধরে তোমাকে মনমরা লাগছে, ফুটবল খেলাও ছেড়ে দিয়েছ। আমার চিন্তা হচ্ছে, আমি বুঝতে চাই।” মন দিয়ে শুনুন; কারণটা আপনার কাছে ছোট মনে হলেও তার অনুভূতিকে গুরুত্ব দিন। “অন্যদের অবস্থা আরও খারাপ” বা “এসব তোমার মনের ভুল” বলবেন না। অনেক পরিবারের কাছে ঈমান আর দোয়া সত্যিকারের সান্ত্বনা; চিকিৎসার বদলে নয়, চিকিৎসার পাশাপাশি এগুলো সবচেয়ে ভালো কাজ করে।\n\n## যা সাহায্য করে\n\n- নিয়মিত ঘুম, প্রতিদিন শারীরিক কর্মকাণ্ড আর সময়মতো খাওয়া।\n- পাশে থাকা বন্ধু আর পরিবারের সাথে সময় কাটানো।\n- গভীর রাতে ফোন ব্যবহারে সীমা।\n- নম্বর নিয়ে চাপ কম, চেষ্টার প্রশংসা বেশি।\n- অনুভূতির নাম দিতে আর শরীর শান্ত করতে শেখা: ধীরে শ্বাস নেওয়া, হাঁটা, মনের কথা লিখে রাখা।\n\n## সাহায্য নেওয়া\n\nস্কুলের কাউন্সেলর, পরিচিত ডাক্তার, মনোরোগ বিশেষজ্ঞ (psychiatrist) বা ক্লিনিক্যাল সাইকোলজিস্টের সাথে কথা বলুন। বাংলাদেশে মেডিকেল কলেজ হাসপাতালগুলোর মনোরোগ বিভাগ আর ঢাকার জাতীয় মানসিক স্বাস্থ্য ইনস্টিটিউটে কিশোর-কিশোরীদেরও চিকিৎসা দেওয়া হয়। বিষণ্নতা আর উদ্বেগ খুব সাধারণ, চিকিৎসায় ভালো হয়, আর যত আগে সাহায্য নেওয়া যায় তত ভালো।\n\n## এখনই ব্যবস্থা নিন যদি\n\nসে মরে যাওয়ার কথা বলে, নিজের ক্ষতি করে, বা আপনার মনে হয় সে নিরাপদ নয়। তার সাথে থাকুন, এখনই ৯৯৯-এ ফোন করুন বা নিকটস্থ হাসপাতালের জরুরি বিভাগে যান।"}'::jsonb, '{}'::jsonb, 5, 4748, 7305, '{}'::text[], 'any', ARRAY['mental health', 'depression', 'anxiety', 'stress', 'teen', 'counselling', 'warning signs']::text[], false, 'in_review'::lp_review_status, 8009),
  ('tn-self-harm-suicide-signs', 'article', 'scientific', 'shared', 'important', 'guideline', '🆘', '{"en":"Self-harm and suicide warning signs: what to do now","bn":"নিজের ক্ষতি ও আত্মহত্যার সতর্কসংকেত: এখনই যা করবেন"}'::jsonb, '{"en":"The warning signs to know, and clear steps if you are worried: stay with your teen, remove dangerous items, and get professional or emergency help now.","bn":"যে সতর্কসংকেতগুলো জানা দরকার, আর দুশ্চিন্তা হলে পরিষ্কার করণীয়: সন্তানের পাশে থাকুন, বিপজ্জনক জিনিস সরান, এখনই বিশেষজ্ঞ বা জরুরি সাহায্য নিন।"}'::jsonb, '{"en":"This guide is for any parent worried that their teen might hurt themselves or is thinking about suicide. Reading it now, before a crisis, helps you act quickly.\n\n## If your teen is in danger right now\n\nIf they have taken an overdose, swallowed poison or pesticide, have a serious wound, or say they are about to end their life: call 999 or take them to the nearest hospital emergency now. Do not leave them alone.\n\n## Warning signs\n\n- Talking or writing about death, wanting to disappear, or being a burden.\n- Saying goodbye or giving away valued things.\n- Searching for ways to die, or collecting tablets.\n- Hidden cuts, burns or bruises, often on arms or thighs; long sleeves in hot weather.\n- Sudden calm after a long period of deep sadness.\n- A recent painful event: exam failure, a break-up, bullying, abuse, a death, or a private photo leaked online.\n- Heavy drug or alcohol use.\n\n## What to do\n\n1. Stay calm and stay with them. Your calm presence matters more than perfect words.\n2. Ask directly: “Are you thinking about killing yourself?” Asking does not put the idea in their head; it shows you can handle the truth.\n3. Listen without arguing, lecturing or shaming. Say: “Thank you for telling me. I''m here, and we''ll get help together.”\n4. Remove means: lock away or remove medicines, pesticides, rat poison, blades, ropes and similar items. In rural homes, keep pesticides and poisons locked up.\n5. Get professional help the same day: a doctor, a hospital emergency department or a psychiatrist. If there is immediate danger, call 999.\n6. Keep supporting them after the crisis. Go with them to appointments and check in every day.\n\n## Self-harm without wanting to die\n\nSome teens cut or hurt themselves to cope with overwhelming feelings rather than to die. It is still a sign of serious distress, and it raises the risk of suicide. Treat any self-harm seriously and get help. Clean and cover small wounds; take deep or infected wounds to a doctor.\n\n## Avoid\n\n- Promising to keep it secret.\n- Saying “You''re doing it for attention” or “Think of the family''s honour”.\n- Shouting, beating or withdrawing your support.\n- Leaving them alone with dangerous items.\n\n## Look after yourself\n\nThis is frightening for any parent. Share the load with your partner or another trusted adult, and get support for yourself too.","bn":"সন্তান নিজের ক্ষতি করতে পারে বা আত্মহত্যার কথা ভাবছে — এমন দুশ্চিন্তা যে বাবা-মায়ের আছে, এই গাইড তাদের জন্য। সংকট আসার আগেই পড়ে রাখলে দ্রুত ব্যবস্থা নিতে পারবেন।\n\n## সন্তান যদি এখনই বিপদে থাকে\n\nবেশি ওষুধ খেয়ে ফেললে, বিষ বা কীটনাশক গিললে, গুরুতর ক্ষত থাকলে, বা বলে যে এখনই জীবন শেষ করে দেবে: এখনই ৯৯৯-এ ফোন করুন বা নিকটস্থ হাসপাতালের জরুরি বিভাগে নিয়ে যান। তাকে একা রাখবেন না।\n\n## সতর্কসংকেত\n\n- মৃত্যু, হারিয়ে যেতে চাওয়া বা সবার বোঝা হওয়া নিয়ে কথা বলা বা লেখা।\n- বিদায় নেওয়ার মতো কথা বলা, প্রিয় জিনিস অন্যকে দিয়ে দেওয়া।\n- মরার উপায় খোঁজা, বা ওষুধ জমিয়ে রাখা।\n- হাতে বা ঊরুতে লুকানো কাটা, পোড়া বা কালশিটে দাগ; গরমেও লম্বা হাতার জামা পরা।\n- দীর্ঘদিনের গভীর মন খারাপের পর হঠাৎ শান্ত হয়ে যাওয়া।\n- সম্প্রতি কোনো কষ্টের ঘটনা: পরীক্ষায় ফেল, সম্পর্ক ভেঙে যাওয়া, বুলিং, নির্যাতন, কারও মৃত্যু, বা অনলাইনে ব্যক্তিগত ছবি ছড়িয়ে পড়া।\n- অতিরিক্ত মাদক বা মদ্যপান।\n\n## কী করবেন\n\n১. শান্ত থাকুন, তার পাশে থাকুন। নিখুঁত কথার চেয়ে আপনার শান্ত উপস্থিতি বেশি জরুরি।\n২. সরাসরি জিজ্ঞেস করুন: “তুমি কি আত্মহত্যার কথা ভাবছ?” এভাবে জিজ্ঞেস করলে মাথায় নতুন করে চিন্তা ঢোকে না; বরং সে বোঝে আপনি সত্যিটা শুনতে প্রস্তুত।\n৩. তর্ক, উপদেশ বা লজ্জা না দিয়ে শুনুন। বলুন: “আমাকে বলার জন্য ধন্যবাদ। আমি আছি, আমরা একসাথে সাহায্য নেব।”\n৪. উপায় সরিয়ে ফেলুন: ওষুধ, কীটনাশক, ইঁদুর মারার বিষ, ব্লেড, দড়ি এ ধরনের জিনিস তালাবন্ধ করুন বা সরিয়ে ফেলুন। গ্রামের বাড়িতে কীটনাশক আর বিষ অবশ্যই তালা দিয়ে রাখুন।\n৫. সেদিনই বিশেষজ্ঞের সাহায্য নিন: ডাক্তার, হাসপাতালের জরুরি বিভাগ বা মনোরোগ বিশেষজ্ঞ। তাৎক্ষণিক বিপদ থাকলে ৯৯৯-এ ফোন করুন।\n৬. সংকট কেটে গেলেও পাশে থাকুন। ডাক্তারের কাছে সাথে যান, প্রতিদিন খোঁজ নিন।\n\n## মরতে না চেয়েও নিজের ক্ষতি\n\nকেউ কেউ মরার জন্য নয়, প্রচণ্ড কষ্ট সামলাতে নিজের শরীর কাটে বা আঘাত করে। তবু এটা গুরুতর মানসিক যন্ত্রণার লক্ষণ, আর এতে আত্মহত্যার ঝুঁকি বাড়ে। নিজের যেকোনো ক্ষতিকেই গুরুত্ব দিন, সাহায্য নিন। ছোট ক্ষত পরিষ্কার করে ঢেকে দিন; গভীর বা পেকে যাওয়া ক্ষত ডাক্তারকে দেখান।\n\n## যা করবেন না\n\n- গোপন রাখার প্রতিশ্রুতি দেবেন না।\n- “মনোযোগ পাওয়ার জন্য করছ” বা “পরিবারের মান-সম্মানের কথা ভাবো” বলবেন না।\n- চিৎকার, মারধর বা পাশ থেকে সরে যাওয়া — কোনোটাই নয়।\n- বিপজ্জনক জিনিসের সাথে তাকে একা রাখবেন না।\n\n## নিজের যত্ন নিন\n\nযেকোনো বাবা-মায়ের জন্যই এটা ভয়ের। জীবনসঙ্গী বা ভরসার আরেকজন মানুষের সাথে ভার ভাগ করুন, আর নিজের জন্যও সহায়তা নিন।"}'::jsonb, '{}'::jsonb, 5, 4748, 7305, '{}'::text[], 'any', ARRAY['self-harm', 'suicide', 'warning signs', 'crisis', '999', 'cutting', 'poisoning']::text[], false, 'in_review'::lp_review_status, 8010),
  ('tn-exam-stress', 'article', 'general', 'shared', 'routine', 'consensus', '📝', '{"en":"Exam stress (SSC/HSC) and healthy study","bn":"এসএসসি/এইচএসসির পরীক্ষার চাপ ও স্বাস্থ্যকর পড়াশোনা"}'::jsonb, '{"en":"A little stress helps focus; too much harms sleep, health and results. A healthy routine, calm home and steady support make the biggest difference.","bn":"অল্প চাপ মনোযোগ বাড়ায়; বেশি চাপ ঘুম, স্বাস্থ্য আর ফলাফল সবই নষ্ট করে। স্বাস্থ্যকর রুটিন, শান্ত পরিবেশ আর পাশে থাকাই সবচেয়ে বেশি কাজে দেয়।"}'::jsonb, '{"en":"SSC and HSC are big moments in Bangladesh, and pressure from family, school, coaching and neighbours can be heavy. A little stress helps focus. Too much harms sleep, health and even results.\n\n## Signs of too much stress\n\n- Trouble sleeping, or studying very late every night.\n- Headaches, stomach aches, loss of appetite.\n- Crying, anger or panic before tests.\n- Going blank in exams despite studying.\n- Saying “I''m useless” or “My life is over if I fail”.\n\n## A healthy study routine\n\n- Study in blocks of about 25–50 minutes, then take a short break to stretch, drink water or walk.\n- Make a simple timetable together that includes sleep, meals, prayer or quiet time, and some exercise.\n- Practise past papers against the clock; it reduces fear of the real exam.\n- Keep phones in another room while studying.\n- Protect 8–10 hours of sleep. Studying all night before an exam weakens memory and performance.\n- Eat regular meals, with breakfast on exam days, and drink enough water.\n- Daily physical activity improves mood and concentration.\n\n## What parents can do\n\n- Say often: “We love you whatever the result. We care that you try your best.”\n- Don''t compare with cousins, neighbours'' children or siblings.\n- Ease chores and family events during exams, but keep some normal life and fun.\n- Keep the home calm; avoid arguments before exam days.\n- Check the admit card, pens, exam centre and transport the day before.\n- Fathers: take charge of transport and logistics on exam days so your teen can focus.\n\n## After the results\n\nCelebrate effort, whatever the GPA. If results disappoint, allow a day or two to feel it, then plan together: applying for a result review if a mark looks wrong, sitting again, extra help, or another route. One exam does not decide a whole life.\n\n## When to get help\n\nIf your teen panics often, can''t sleep for many nights, stops eating, or talks about being worthless, talk to a doctor or counsellor. If they say they would rather die than fail, or talk of suicide, stay with them and call 999 or go to hospital now.","bn":"বাংলাদেশে এসএসসি আর এইচএসসি জীবনের বড় মুহূর্ত, আর পরিবার, স্কুল, কোচিং, প্রতিবেশী — সবার দিক থেকে চাপ অনেক ভারী হয়ে যেতে পারে। অল্প চাপ মনোযোগ বাড়ায়। বেশি চাপ ঘুম, স্বাস্থ্য, এমনকি ফলাফলেরও ক্ষতি করে।\n\n## অতিরিক্ত চাপের লক্ষণ\n\n- ঘুম না আসা, বা প্রতিরাতে অনেক রাত পর্যন্ত পড়া।\n- মাথাব্যথা, পেটব্যথা, খিদে কমে যাওয়া।\n- পরীক্ষার আগে কান্না, রাগ বা আতঙ্ক।\n- পড়েও পরীক্ষার হলে সব ভুলে যাওয়া।\n- “আমাকে দিয়ে কিছু হবে না” বা “ফেল করলে জীবন শেষ” — এমন কথা বলা।\n\n## স্বাস্থ্যকর পড়ার রুটিন\n\n- ২৫–৫০ মিনিট করে পড়া, তারপর একটু বিরতি — হাত-পা টানা, পানি খাওয়া বা হাঁটা।\n- একসাথে সহজ একটা রুটিন বানান, যেখানে ঘুম, খাওয়া, নামাজ বা নিরিবিলি সময় আর কিছু ব্যায়াম থাকবে।\n- সময় ধরে আগের বছরের প্রশ্ন সমাধান করা; এতে আসল পরীক্ষার ভয় কমে।\n- পড়ার সময় ফোন অন্য ঘরে রাখা।\n- ৮–১০ ঘণ্টা ঘুম রক্ষা করা। পরীক্ষার আগের রাত জেগে পড়লে স্মৃতিশক্তি আর পারফরম্যান্স দুটোই কমে।\n- সময়মতো খাওয়া, পরীক্ষার দিন সকালের নাশতা, আর যথেষ্ট পানি।\n- প্রতিদিন কিছু শারীরিক কর্মকাণ্ড মন ভালো রাখে, মনোযোগ বাড়ায়।\n\n## বাবা-মা যা করতে পারেন\n\n- বারবার বলুন: “ফল যা-ই হোক, আমরা তোমাকে ভালোবাসি। তুমি সাধ্যমতো চেষ্টা করো, সেটাই আমাদের কাছে বড়।”\n- কাজিন, প্রতিবেশীর ছেলেমেয়ে বা ভাইবোনের সাথে তুলনা করবেন না।\n- পরীক্ষার সময় ঘরের কাজ আর দাওয়াত-অনুষ্ঠান কমান, তবে একেবারে সব আনন্দ বন্ধ করবেন না।\n- ঘরের পরিবেশ শান্ত রাখুন; পরীক্ষার আগে ঝগড়া এড়িয়ে চলুন।\n- আগের দিনই প্রবেশপত্র, কলম, পরীক্ষাকেন্দ্র আর যাতায়াত দেখে রাখুন।\n- বাবারা: পরীক্ষার দিনের যাতায়াত আর সব ব্যবস্থার দায়িত্ব নিন, যেন সন্তান শুধু পরীক্ষায় মন দিতে পারে।\n\n## ফল বের হওয়ার পর\n\nজিপিএ যা-ই হোক, চেষ্টাকে উদযাপন করুন। ফল আশানুরূপ না হলে এক-দুই দিন মন খারাপ করার সুযোগ দিন, তারপর একসাথে পরিকল্পনা করুন: নম্বরে ভুল মনে হলে ফল পুনর্নিরীক্ষণের আবেদন, আবার পরীক্ষা দেওয়া, বাড়তি সাহায্য, বা অন্য কোনো পথ। একটা পরীক্ষা পুরো জীবন ঠিক করে দেয় না।\n\n## কখন সাহায্য নেবেন\n\nপ্রায়ই আতঙ্কে ভুগলে, অনেক রাত ঘুম না হলে, খাওয়া বন্ধ করে দিলে বা নিজেকে মূল্যহীন বললে ডাক্তার বা কাউন্সেলরের সাথে কথা বলুন। যদি বলে ফেল করার চেয়ে মরে যাওয়া ভালো, বা আত্মহত্যার কথা বলে — তার পাশে থাকুন, এখনই ৯৯৯-এ ফোন করুন বা হাসপাতালে যান।"}'::jsonb, '{}'::jsonb, 4, 4748, 7305, '{}'::text[], 'any', ARRAY['exam stress', 'ssc', 'hsc', 'study routine', 'results', 'gpa', 'pressure']::text[], false, 'in_review'::lp_review_status, 8011),
  ('tn-study-group-career', 'article', 'general', 'shared', 'routine', 'consensus', '🧭', '{"en":"Choosing a study group and career: respecting your teen''s interests","bn":"বিভাগ আর পেশা বেছে নেওয়া: সন্তানের আগ্রহকে সম্মান করুন"}'::jsonb, '{"en":"Science, business studies, humanities, technical and vocational paths can all lead to a good, honest living. How to help your teen choose a path they will own.","bn":"বিজ্ঞান, ব্যবসায় শিক্ষা, মানবিক, কারিগরি বা বৃত্তিমূলক — যেকোনো পথই সম্মানজনক জীবিকার দিকে নিতে পারে। সন্তান যেন নিজের পথ নিজে বেছে নিতে পারে, তাতে কীভাবে সাহায্য করবেন।"}'::jsonb, '{"en":"Around class 9, most students in Bangladesh choose a group, and after SSC and HSC more choices follow. Many families feel there is only one ''good'' path, usually science and then medicine or engineering. In reality, there are many routes to a good, honest living.\n\n## The main paths\n\n- **Science:** for those who enjoy maths, physics, chemistry or biology. It leads to medicine, engineering, agriculture, IT and research, among others.\n- **Business studies:** accounting, finance, banking, marketing and running a business.\n- **Humanities:** law, journalism, teaching, social work, public service, languages, the arts and more.\n- **Technical and vocational:** vocational SSC and HSC courses, diplomas from polytechnic institutes, and short skills courses at technical training centres, for example in electrical work, IT or garments technology. Skilled technicians are in demand at home and abroad.\n- **Madrasah education** also leads on to higher studies and many careers.\n\nRules about when and how groups are chosen have changed in recent years, so check the current system with your teen''s school.\n\n## Help your teen choose\n\n- Ask which subjects they enjoy and what they are good at, not only what earns the most.\n- Look at their results across subjects, and talk to teachers who know them well.\n- Encourage them to talk to people in different jobs: a nurse, an electrician, a banker, a teacher.\n- Look at what each path needs: years of study, cost, admission tests and where the jobs are.\n- Remember that interests change; many people switch fields later in life.\n\n## Respect their interests\n\nForcing a teen into a group they dislike often leads to poor results, stress and resentment. If you disagree, explain your worries honestly, such as cost, jobs or safety, and listen to theirs. Aim for a choice they own. If they are unsure, choose a path that keeps more doors open.\n\n## Daughters and sons equally\n\nEncourage daughters and sons equally in every field, including science, technology and skilled trades. Don''t let marriage plans cut a daughter''s education short; in Bangladesh the legal minimum age of marriage is 18 for women and 21 for men.\n\n## When to get help\n\nIf your teen is very anxious, stuck, or in constant conflict with you about the future, a school counsellor or career adviser can help. If worry about the future comes with low mood for weeks, read the mental-health guide.","bn":"নবম শ্রেণির দিকে বাংলাদেশের বেশিরভাগ শিক্ষার্থী একটা বিভাগ বেছে নেয়, আর এসএসসি-এইচএসসির পরে আরও সিদ্ধান্ত আসে। অনেক পরিবার মনে করে “ভালো” পথ একটাই — সাধারণত বিজ্ঞান, তারপর ডাক্তারি বা ইঞ্জিনিয়ারিং। আসলে সৎ ও সম্মানজনক জীবিকার পথ অনেক।\n\n## প্রধান পথগুলো\n\n- **বিজ্ঞান:** যারা গণিত, পদার্থ, রসায়ন বা জীববিজ্ঞান পছন্দ করে। এখান থেকে চিকিৎসা, প্রকৌশল, কৃষি, আইটি, গবেষণাসহ নানা পথ খোলে।\n- **ব্যবসায় শিক্ষা:** হিসাববিজ্ঞান, ফিন্যান্স, ব্যাংকিং, মার্কেটিং আর নিজের ব্যবসা চালানো।\n- **মানবিক:** আইন, সাংবাদিকতা, শিক্ষকতা, সমাজকর্ম, সরকারি চাকরি, ভাষা, শিল্পকলা আরও অনেক কিছু।\n- **কারিগরি ও বৃত্তিমূলক:** ভোকেশনাল এসএসসি-এইচএসসি, পলিটেকনিক ইনস্টিটিউটের ডিপ্লোমা, আর কারিগরি প্রশিক্ষণ কেন্দ্রের স্বল্পমেয়াদি কোর্স — যেমন ইলেকট্রিক্যাল, আইটি বা গার্মেন্টস প্রযুক্তি। দক্ষ কারিগরের চাহিদা দেশে-বিদেশে দুই জায়গাতেই আছে।\n- **মাদ্রাসা শিক্ষা** থেকেও উচ্চশিক্ষা আর নানা পেশায় যাওয়া যায়।\n\nকখন ও কীভাবে বিভাগ বাছাই হবে, সেই নিয়ম গত কয়েক বছরে বদলেছে; তাই বর্তমান নিয়ম সন্তানের স্কুল থেকে জেনে নিন।\n\n## বেছে নিতে সাহায্য করুন\n\n- শুধু কোন পেশায় বেশি আয় তা নয়, জিজ্ঞেস করুন কোন বিষয় তার ভালো লাগে আর কোনটায় সে ভালো।\n- সব বিষয়ের ফলাফল দেখুন, আর যে শিক্ষকরা তাকে ভালো চেনেন তাঁদের সাথে কথা বলুন।\n- নানা পেশার মানুষের সাথে কথা বলতে উৎসাহ দিন: নার্স, ইলেকট্রিশিয়ান, ব্যাংকার, শিক্ষক।\n- প্রতিটি পথে কী লাগে দেখুন: কত বছর পড়া, খরচ, ভর্তি পরীক্ষা, আর চাকরি কোথায়।\n- মনে রাখুন আগ্রহ বদলায়; অনেকেই পরে পেশা বদলান।\n\n## তার আগ্রহকে সম্মান করুন\n\nঅপছন্দের বিভাগে জোর করে ভর্তি করালে প্রায়ই ফল খারাপ হয়, চাপ বাড়ে, মনে ক্ষোভ জমে। আপনি একমত না হলে খোলাখুলি নিজের দুশ্চিন্তার কথা বলুন — খরচ, চাকরি বা নিরাপত্তা — আর তার কথাও শুনুন। চেষ্টা করুন সিদ্ধান্তটা যেন তার নিজের হয়। সে নিশ্চিত না হলে এমন পথ বেছে নিন, যেখানে পরে আরও দরজা খোলা থাকে।\n\n## ছেলে-মেয়ে সমান\n\nবিজ্ঞান, প্রযুক্তি, কারিগরি — সব ক্ষেত্রে ছেলে ও মেয়েকে সমানভাবে উৎসাহ দিন। বিয়ের পরিকল্পনা যেন মেয়ের পড়াশোনা থামিয়ে না দেয়; বাংলাদেশে বিয়ের আইনি ন্যূনতম বয়স মেয়েদের ১৮ আর ছেলেদের ২১ বছর।\n\n## কখন সাহায্য নেবেন\n\nভবিষ্যৎ নিয়ে সে খুব উদ্বিগ্ন থাকলে, কিছুই ঠিক করতে না পারলে, বা এ নিয়ে আপনার সাথে লেগেই থাকলে স্কুলের কাউন্সেলর বা ক্যারিয়ার পরামর্শকের সাহায্য নিন। ভবিষ্যতের দুশ্চিন্তার সাথে কয়েক সপ্তাহ ধরে মন খারাপ থাকলে মানসিক স্বাস্থ্যের গাইডটি পড়ুন।"}'::jsonb, '{}'::jsonb, 4, 4748, 7305, '{}'::text[], 'any', ARRAY['career', 'study group', 'science', 'commerce', 'humanities', 'vocational', 'polytechnic', 'future']::text[], false, 'in_review'::lp_review_status, 8012),
  ('tn-money-scams-gambling', 'article', 'general', 'shared', 'important', 'consensus', '💰', '{"en":"Money: earning, saving, and avoiding scams and gambling apps","bn":"টাকাপয়সা: আয়, সঞ্চয়, আর প্রতারণা ও জুয়ার অ্যাপ থেকে দূরে থাকা"}'::jsonb, '{"en":"Teens handle more money than ever, including mobile banking. Teach saving and budgeting, PIN and OTP safety, common scams, and the real danger of betting apps.","bn":"কিশোর-কিশোরীরা এখন আগের চেয়ে বেশি টাকা নাড়াচাড়া করে, মোবাইল ব্যাংকিংও। সঞ্চয় আর বাজেট, পিন ও ওটিপির নিরাপত্তা, প্রচলিত প্রতারণা আর বাজির অ্যাপের আসল বিপদ — এসব শেখান।"}'::jsonb, '{"en":"Teens handle more money than before: pocket money, Eid salami, tuition fees, mobile recharges and online payments. Learning to manage it now protects them later.\n\n## Earning\n\nOlder teens can earn safely by tutoring younger children, helping in a family business, freelancing skills such as design or writing, or seasonal work. Check that the work is safe, suitable for their age, and does not harm studies or sleep. Be wary of online “jobs” that ask for money first; real employers pay you, not the other way round.\n\n## Saving and budgeting\n\n- Use the ''spend, save, share'' idea: split money into what to spend, what to save, and what to give to others or to charity.\n- Help them set a savings goal, such as a bicycle or a course.\n- Many banks in Bangladesh offer student accounts; ask your bank how a parent can help open one.\n- Track spending for a month in a notebook or app, then review it together.\n\n## Mobile banking safety\n\n- Never share a PIN or one-time code (OTP) with anyone, even someone who says they are from the company.\n- No genuine company calls to ask for your PIN.\n- Check the number before sending money; payments are hard to reverse.\n- Never use someone else''s account or ID, and never let others use yours.\n\n## Common scams aimed at teens\n\n- “You''ve won a prize; send a fee to claim it.”\n- Fake online shops selling phones or game items very cheaply.\n- A message from a ''friend'' urgently asking for money (their account may be hacked).\n- Schemes that promise to double money fast, including crypto.\n- Job offers that require a registration fee.\n\n## Betting and gambling apps\n\nOnline betting apps, including sports betting and casino-style games, often target young people through social media and games. Betting is illegal in Bangladesh, and these apps are designed so that most players lose. Some teens borrow or steal to cover losses. Talk about this openly, watch for secret transactions, debts or mood swings around money, and act early. Paid ''loot boxes'' in games work in a similar way, so set spending limits.\n\n## When to get help\n\nIf your teen has lost money to a scam, contact the mobile banking provider straight away and report it to the police. If betting or gaming spending has become hard to stop, talk to a doctor or counsellor.","bn":"কিশোর-কিশোরীরা এখন আগের চেয়ে বেশি টাকা নাড়াচাড়া করে: হাতখরচ, ঈদের সালামি, টিউশন ফি, মোবাইল রিচার্জ, অনলাইন পেমেন্ট। এখনই টাকা সামলাতে শিখলে পরে তারা সুরক্ষিত থাকবে।\n\n## আয়\n\nবড় কিশোর-কিশোরীরা নিরাপদে আয় করতে পারে ছোটদের পড়িয়ে, পারিবারিক ব্যবসায় সাহায্য করে, ডিজাইন বা লেখালেখির মতো দক্ষতা দিয়ে ফ্রিল্যান্সিং করে, বা মৌসুমি কাজে। দেখে নিন কাজটা নিরাপদ কিনা, বয়সের সাথে মানানসই কিনা, আর পড়াশোনা বা ঘুমের ক্ষতি করছে কিনা। যে অনলাইন “চাকরি”তে আগে টাকা দিতে হয়, সেখান থেকে সাবধান; আসল নিয়োগকর্তা টাকা দেন, নেন না।\n\n## সঞ্চয় ও বাজেট\n\n- “খরচ, সঞ্চয়, দান” ভাবনাটা শেখান: টাকা ভাগ করুন — কতটা খরচ, কতটা জমানো, আর কতটা অন্যকে সাহায্য বা দান।\n- একটা সঞ্চয়ের লক্ষ্য ঠিক করতে সাহায্য করুন, যেমন সাইকেল বা কোনো কোর্স।\n- বাংলাদেশে অনেক ব্যাংক শিক্ষার্থীদের জন্য হিসাব খোলার সুযোগ দেয়; অভিভাবক কীভাবে সাহায্য করতে পারেন, ব্যাংকে জেনে নিন।\n- এক মাসের খরচ খাতায় বা অ্যাপে লিখে রাখুক, তারপর একসাথে বসে দেখুন।\n\n## মোবাইল ব্যাংকিংয়ের নিরাপত্তা\n\n- পিন বা ওটিপি (এককালীন কোড) কাউকে দেওয়া যাবে না — কোম্পানির লোক পরিচয় দিলেও না।\n- কোনো আসল কোম্পানি ফোন করে পিন চায় না।\n- টাকা পাঠানোর আগে নম্বর মিলিয়ে নিন; পাঠানো টাকা ফেরত আনা কঠিন।\n- অন্যের অ্যাকাউন্ট বা পরিচয়পত্র ব্যবহার করা যাবে না, নিজেরটাও কাউকে ব্যবহার করতে দেওয়া যাবে না।\n\n## কিশোরদের লক্ষ্য করে প্রচলিত প্রতারণা\n\n- “আপনি পুরস্কার জিতেছেন, ফি পাঠিয়ে নিয়ে নিন।”\n- খুব সস্তায় ফোন বা গেমের জিনিস বিক্রির ভুয়া অনলাইন দোকান।\n- কোনো “বন্ধুর” কাছ থেকে জরুরি টাকা চেয়ে মেসেজ (তার অ্যাকাউন্ট হ্যাক হয়ে থাকতে পারে)।\n- দ্রুত টাকা দ্বিগুণ করার স্কিম, ক্রিপ্টোসহ।\n- রেজিস্ট্রেশন ফি চাওয়া চাকরির প্রস্তাব।\n\n## বাজি ও জুয়ার অ্যাপ\n\nখেলার বাজি আর ক্যাসিনো ধাঁচের গেমসহ অনলাইন বেটিং অ্যাপগুলো প্রায়ই সোশ্যাল মিডিয়া আর গেমের মাধ্যমে তরুণদের টার্গেট করে। বাংলাদেশে বাজি বেআইনি, আর এই অ্যাপগুলো এমনভাবে বানানো যে বেশিরভাগ খেলোয়াড়ই হারে। কেউ কেউ লোকসান মেটাতে ধার করে বা চুরি করে। খোলাখুলি কথা বলুন; গোপন লেনদেন, ধারদেনা বা টাকা নিয়ে হঠাৎ মেজাজ বদল খেয়াল করুন, আর দেরি না করে ব্যবস্থা নিন। গেমের ভেতরে টাকা দিয়ে কেনা “লুট বক্স”ও প্রায় একই রকম, তাই খরচের সীমা ঠিক করে দিন।\n\n## কখন সাহায্য নেবেন\n\nপ্রতারণায় টাকা গেলে সাথে সাথে মোবাইল ব্যাংকিং প্রতিষ্ঠানে যোগাযোগ করুন আর পুলিশে জানান। বাজি বা গেমে খরচ থামাতে না পারলে ডাক্তার বা কাউন্সেলরের সাথে কথা বলুন।"}'::jsonb, '{}'::jsonb, 4, 4748, 7305, '{}'::text[], 'any', ARRAY['money', 'saving', 'budget', 'scams', 'mobile banking', 'gambling', 'betting apps', 'pin', 'otp']::text[], false, 'in_review'::lp_review_status, 8013),
  ('tn-friendships-relationships-consent', 'article', 'general', 'shared', 'important', 'consensus', '🧑‍🤝‍🧑', '{"en":"Friendships, crushes and relationships: values, boundaries and consent","bn":"বন্ধুত্ব, ভালো লাগা ও সম্পর্ক: মূল্যবোধ, সীমা ও সম্মতি"}'::jsonb, '{"en":"Crushes and strong friendships are a normal part of the teen years. Share your family''s values calmly, and make sure your teen knows their body and their “no” must be respected.","bn":"কৈশোরে গভীর বন্ধুত্ব আর কাউকে ভালো লাগা স্বাভাবিক। শান্তভাবে পরিবারের মূল্যবোধ জানান, আর নিশ্চিত করুন সন্তান জানে — তার শরীর আর তার “না” সবাইকে মানতে হবে।"}'::jsonb, '{"en":"Friendships become very important in the teen years, and many teens also have their first crushes or romantic feelings. These feelings are a normal part of puberty. How your family talks about them affects whether your teen stays safe and keeps talking to you.\n\n## Friendships\n\nGood friends make teens happier and more confident. Get to know your teen''s friends, welcome them home, and talk about what makes a friendship healthy: kindness, honesty, loyalty and respecting “no”. Talk too about unhealthy pressure: friends who push smoking, skipping school or risky dares to fit in.\n\n## Crushes and feelings\n\nHaving feelings for someone is natural. Shaming or mocking a teen for it usually pushes the topic underground. You can share your family''s and your faith''s values clearly and calmly, explain why you hold them, and still keep the door open: “Feelings are normal. What you do with them is a choice, and I''m always here to talk about it.” Questions about religious rulings are best discussed with a trusted, knowledgeable scholar.\n\n## Boundaries and consent\n\nEvery teen should know:\n\n- Their body belongs to them. No one, whether friend, relative, teacher, partner or stranger, has the right to touch them without permission or pressure them into anything.\n- They have the right to say no, and to change their mind.\n- Someone who truly cares does not threaten, force, guilt-trip or constantly check their phone.\n- They must respect other people''s “no” too.\n- Sending intimate photos is never safe; images can be shared or used for blackmail.\n\n## Signs of an unhealthy or abusive relationship\n\n- Jealousy, or controlling who they meet or what they wear.\n- Demands for passwords, location or photos.\n- Threats, insults or hitting.\n- Pressure to keep the relationship secret from everyone.\n- A much older person showing special interest, or giving gifts or money.\n\nAn adult who seeks a romantic or sexual relationship with a child is committing abuse, whatever the child says.\n\n## What parents can do\n\nStay calm if you learn about a relationship. Find out who the other person is, check that your teen is safe, and talk about values and limits. Avoid beating, locking your teen up or arranging an early marriage; these increase risk and destroy trust. If there are signs of abuse, threats or blackmail, contact the police on 999 and get support from a counsellor.","bn":"কৈশোরে বন্ধুত্ব খুব গুরুত্বপূর্ণ হয়ে ওঠে, আর অনেকের মনে প্রথমবার কাউকে ভালো লাগে বা প্রেমের অনুভূতি জাগে। বয়ঃসন্ধিতে এমন অনুভূতি স্বাভাবিক। পরিবার এ নিয়ে কীভাবে কথা বলে, তার ওপর নির্ভর করে সন্তান নিরাপদ থাকবে কিনা আর আপনার সাথে কথা বলা চালিয়ে যাবে কিনা।\n\n## বন্ধুত্ব\n\nভালো বন্ধু কিশোর-কিশোরীকে বেশি খুশি আর আত্মবিশ্বাসী করে। সন্তানের বন্ধুদের চিনুন, বাসায় আসতে দিন, আর আলোচনা করুন সুস্থ বন্ধুত্ব কেমন হয়: দয়া, সততা, বিশ্বস্ততা, আর “না”-কে সম্মান করা। অসুস্থ চাপ নিয়েও কথা বলুন — যে বন্ধুরা দলে টিকতে সিগারেট, ক্লাস ফাঁকি বা ঝুঁকির বাজিতে টানে।\n\n## ভালো লাগা ও অনুভূতি\n\nকাউকে ভালো লাগা স্বাভাবিক। এ নিয়ে লজ্জা দিলে বা ঠাট্টা করলে সাধারণত বিষয়টা লুকিয়ে যায়। আপনি পরিবারের আর ধর্মের মূল্যবোধ পরিষ্কার ও শান্তভাবে জানাতে পারেন, কেন মানেন তা বুঝিয়ে বলতে পারেন, আবার কথা বলার পথও খোলা রাখতে পারেন: “অনুভূতি হওয়া স্বাভাবিক। সেটা নিয়ে কী করবে, তা তোমার সিদ্ধান্ত — আর এ নিয়ে কথা বলতে আমি সবসময় আছি।” ধর্মীয় বিধান নিয়ে প্রশ্ন থাকলে ভরসার, জ্ঞানী কোনো আলেমের সাথে আলোচনা করাই ভালো।\n\n## সীমা ও সম্মতি\n\nপ্রত্যেক কিশোর-কিশোরীর জানা দরকার:\n\n- তার শরীর তার নিজের। বন্ধু, আত্মীয়, শিক্ষক, প্রেমিক-প্রেমিকা বা অপরিচিত — কেউই অনুমতি ছাড়া তাকে ছুঁতে বা কোনো কিছুতে চাপ দিতে পারে না।\n- “না” বলার অধিকার তার আছে, মত বদলানোর অধিকারও আছে।\n- যে সত্যিই ভালোবাসে, সে হুমকি দেয় না, জোর করে না, অপরাধবোধে ফেলে না, বারবার ফোন ঘাঁটে না।\n- অন্যের “না”-কেও তাকে সম্মান করতে হবে।\n- অন্তরঙ্গ ছবি পাঠানো কখনোই নিরাপদ নয়; ছবি ছড়িয়ে যেতে পারে বা ব্ল্যাকমেইলে ব্যবহার হতে পারে।\n\n## অসুস্থ বা নির্যাতনমূলক সম্পর্কের লক্ষণ\n\n- হিংসা, বা কার সাথে মিশবে, কী পরবে তা নিয়ন্ত্রণ করা।\n- পাসওয়ার্ড, লোকেশন বা ছবি দাবি করা।\n- হুমকি, অপমান বা গায়ে হাত তোলা।\n- সম্পর্কটা সবার কাছ থেকে গোপন রাখার চাপ।\n- অনেক বেশি বয়সী কারও বিশেষ আগ্রহ, উপহার বা টাকা দেওয়া।\n\nকোনো প্রাপ্তবয়স্ক যদি শিশুর সাথে প্রেম বা যৌন সম্পর্ক চায়, শিশু যা-ই বলুক, সেটা নির্যাতন।\n\n## বাবা-মা যা করতে পারেন\n\nসম্পর্কের কথা জানলে শান্ত থাকুন। অন্যজন কে তা জানুন, সন্তান নিরাপদ কিনা দেখুন, আর মূল্যবোধ ও সীমা নিয়ে কথা বলুন। মারধর, ঘরে আটকে রাখা বা তাড়াহুড়ো করে বিয়ে দেওয়া থেকে বিরত থাকুন; এতে ঝুঁকি বাড়ে, আস্থা ভেঙে যায়। নির্যাতন, হুমকি বা ব্ল্যাকমেইলের লক্ষণ পেলে ৯৯৯-এ পুলিশে যোগাযোগ করুন আর কাউন্সেলরের সহায়তা নিন।"}'::jsonb, '{}'::jsonb, 4, 4748, 7305, '{}'::text[], 'any', ARRAY['friendship', 'crush', 'relationships', 'boundaries', 'consent', 'peer pressure', 'abuse', 'values']::text[], false, 'in_review'::lp_review_status, 8014),
  ('tn-online-risks-sextortion', 'article', 'general', 'shared', 'important', 'consensus', '🛡️', '{"en":"Online risks: sextortion and blackmail, scams and harassment","bn":"অনলাইনের ঝুঁকি: ছবি দিয়ে ব্ল্যাকমেইল, প্রতারণা ও হয়রানি"}'::jsonb, '{"en":"If someone threatens to share a teen''s images: never pay, tell a parent, keep evidence, and report to the platform and the police. How to prepare your teen before it happens.","bn":"কেউ ছবি ছড়িয়ে দেওয়ার হুমকি দিলে: কখনো টাকা দেবে না, বাবা-মাকে জানাবে, প্রমাণ রাখবে, আর প্ল্যাটফর্ম ও পুলিশে রিপোর্ট করবে। আগে থেকেই সন্তানকে কীভাবে প্রস্তুত করবেন।"}'::jsonb, '{"en":"Most teens are online on social media, games and chat apps. Alongside the good, there are three big risks: sextortion, scams and harassment.\n\n## Sextortion and blackmail\n\nSomeone, often a stranger with a fake profile but sometimes a person the teen knows, gets an intimate photo or video and threatens to share it unless the teen sends money, more images or agrees to meet. Sometimes the images are fake or edited. Both girls and boys are targeted.\n\nTeach your teen, and remind them often:\n\n- **Never pay and never send more.** Paying rarely stops the threats; it usually leads to more demands.\n- **Tell a parent or trusted adult straight away.** Promise: “You won''t be in trouble for telling me. We''ll handle this together.”\n- **Keep evidence.** Screenshot messages, usernames, profile links and payment requests. Don''t delete the chat yet.\n- **Stop replying and block** once evidence is saved.\n- **Report** the account to the app, and to the police by calling 999 or going to your local police station. Bangladesh Police has cyber crime units that deal with these cases.\n\nBlackmail is the fault of the blackmailer, never the teen. Shame keeps teens silent, and silence is dangerous: some teens in this situation have harmed themselves. Your calm, protective reaction can save a life.\n\n## Scams\n\nFake prizes, very cheap phones, game currency, job offers and ''friends'' asking for money. The rules: never share a password, PIN or OTP, and never pay to receive a prize or a job.\n\n## Harassment and bullying\n\nThis includes insulting comments, fake profiles, sharing private photos, threats and unwanted sexual messages. Encourage your teen not to reply in anger, to save evidence, block and report, and to tell you. If threats are serious or involve sexual images, contact the police.\n\n## Prevention\n\n- Keep accounts private and accept only people known in real life.\n- Turn off location sharing.\n- Never share intimate images with anyone.\n- Be wary of new online ''friends'' who flatter, move fast or ask to switch to private apps.\n- Talk about online safety regularly, not only after a problem.\n\n## When to get help\n\nIf your teen seems frightened or withdrawn, or talks about self-harm after an online incident, stay with them and get help immediately. In danger, call 999.","bn":"বেশিরভাগ কিশোর-কিশোরী সোশ্যাল মিডিয়া, গেম আর চ্যাট অ্যাপে সক্রিয়। ভালো দিকের পাশাপাশি তিনটা বড় ঝুঁকি আছে: ছবি দিয়ে ব্ল্যাকমেইল (sextortion), প্রতারণা আর হয়রানি।\n\n## ছবি দিয়ে ব্ল্যাকমেইল\n\nকেউ — প্রায়ই ভুয়া প্রোফাইলের অপরিচিত মানুষ, কখনো পরিচিত কেউ — একটা অন্তরঙ্গ ছবি বা ভিডিও হাতে পেয়ে হুমকি দেয়: টাকা, আরও ছবি না দিলে বা দেখা না করলে সেটা ছড়িয়ে দেবে। কখনো ছবিগুলো ভুয়া বা এডিট করা। ছেলে-মেয়ে দুজনেই এর শিকার হয়।\n\nসন্তানকে শেখান, বারবার মনে করিয়ে দিন:\n\n- **কখনো টাকা দেবে না, আর কিছু পাঠাবে না।** টাকা দিলে হুমকি থামে না, সাধারণত দাবি আরও বাড়ে।\n- **সাথে সাথে বাবা-মা বা ভরসার কোনো বড়কে জানাবে।** কথা দিন: “বললে তোমার কোনো শাস্তি হবে না। আমরা একসাথে সামলাব।”\n- **প্রমাণ রাখবে।** মেসেজ, ইউজারনেম, প্রোফাইল লিংক আর টাকা চাওয়ার স্ক্রিনশট নেবে। এখনই চ্যাট মুছবে না।\n- **প্রমাণ রাখার পর উত্তর দেওয়া বন্ধ করে ব্লক করবে।**\n- **রিপোর্ট করবে** — অ্যাপে, আর পুলিশে: ৯৯৯-এ ফোন করে বা নিকটস্থ থানায় গিয়ে। বাংলাদেশ পুলিশের সাইবার অপরাধ ইউনিট এ ধরনের ঘটনা নিয়ে কাজ করে।\n\nব্ল্যাকমেইলের দোষ ব্ল্যাকমেইলারের, কখনোই সন্তানের নয়। লজ্জা কিশোর-কিশোরীকে চুপ করিয়ে রাখে, আর এই চুপ থাকাটাই বিপজ্জনক: এমন অবস্থায় কেউ কেউ নিজের ক্ষতি করে ফেলেছে। আপনার শান্ত, আগলে রাখা প্রতিক্রিয়া একটা জীবন বাঁচাতে পারে।\n\n## প্রতারণা\n\nভুয়া পুরস্কার, খুব সস্তা ফোন, গেমের কারেন্সি, চাকরির প্রস্তাব, টাকা চাওয়া “বন্ধু”। নিয়ম হলো: পাসওয়ার্ড, পিন বা ওটিপি কাউকে দেবে না, আর পুরস্কার বা চাকরি পেতে কখনো টাকা দেবে না।\n\n## হয়রানি ও বুলিং\n\nঅপমানজনক মন্তব্য, ভুয়া প্রোফাইল, ব্যক্তিগত ছবি ছড়ানো, হুমকি, অনাকাঙ্ক্ষিত যৌন মেসেজ — সবই এর মধ্যে পড়ে। সন্তানকে বলুন রাগের মাথায় উত্তর না দিতে, প্রমাণ রেখে ব্লক ও রিপোর্ট করতে, আর আপনাকে জানাতে। হুমকি গুরুতর হলে বা যৌন ছবি জড়িত থাকলে পুলিশে যোগাযোগ করুন।\n\n## আগে থেকেই সুরক্ষা\n\n- অ্যাকাউন্ট প্রাইভেট রাখবে, শুধু বাস্তবে চেনা মানুষকে যুক্ত করবে।\n- লোকেশন শেয়ারিং বন্ধ রাখবে।\n- কাউকে কখনো অন্তরঙ্গ ছবি পাঠাবে না।\n- যে নতুন অনলাইন “বন্ধু” খুব প্রশংসা করে, দ্রুত ঘনিষ্ঠ হতে চায় বা প্রাইভেট অ্যাপে যেতে বলে, তার ব্যাপারে সাবধান থাকবে।\n- সমস্যা হলে তবেই নয়, নিয়মিত অনলাইন নিরাপত্তা নিয়ে কথা বলুন।\n\n## কখন সাহায্য নেবেন\n\nঅনলাইনের কোনো ঘটনার পর সন্তান ভীত বা গুটিয়ে থাকলে, বা নিজের ক্ষতির কথা বললে তার পাশে থাকুন, সাথে সাথে সাহায্য নিন। বিপদ থাকলে ৯৯৯-এ ফোন করুন।"}'::jsonb, '{}'::jsonb, 5, 4748, 7305, '{}'::text[], 'any', ARRAY['sextortion', 'blackmail', 'online safety', 'scams', 'cyberbullying', 'harassment', 'police', 'evidence']::text[], false, 'in_review'::lp_review_status, 8015),
  ('tn-social-media-comparison', 'article', 'scientific', 'shared', 'routine', 'consensus', '📱', '{"en":"Social media and comparison","bn":"সোশ্যাল মিডিয়া ও অন্যের সাথে তুলনা"}'::jsonb, '{"en":"Social media shows everyone else''s best moments. Help your teen see what is real, build offline confidence, and agree a family media plan.","bn":"সোশ্যাল মিডিয়ায় সবাই নিজের সেরা মুহূর্তটাই দেখায়। কোনটা আসল তা বুঝতে, বাস্তব জীবনে আত্মবিশ্বাস গড়তে আর পারিবারিক মিডিয়া পরিকল্পনা করতে সন্তানকে সাহায্য করুন।"}'::jsonb, '{"en":"Social media lets teens keep in touch, learn and share their talents. It also shows a constant stream of other people''s best moments: perfect faces, expensive phones, holidays and top results. Many teens start comparing their ordinary life with everyone else''s highlights.\n\n## How comparison can affect teens\n\n- Feeling not good-looking, rich or clever enough.\n- Worrying about likes, followers and comments.\n- Feeling left out when friends post without them.\n- Late-night scrolling that steals sleep.\n\nNot every teen is affected in the same way. Watch how your teen feels after using social media, not only how many hours they spend.\n\n## Talk about what is real\n\n- Point out that photos are chosen, edited and filtered, and that people rarely post their bad days.\n- Ask: “How do you feel after scrolling for an hour, better or worse?”\n- Discuss influencers and adverts: who is paying, and what are they selling?\n- Share your own experience of comparing yourself with others.\n\n## Make a family media plan\n\n- Agree phone-free times: meals, homework, prayer or family time, and the hour before bed.\n- Keep phones out of bedrooms at night.\n- Unfollow accounts that make them feel bad; follow ones that teach, inspire or make them laugh.\n- Turn off non-urgent notifications.\n- Check privacy settings together.\n\n## Be the example\n\nTeens notice when parents scroll at the dinner table. Put your own phone down when your teen talks to you.\n\n## Build real-life confidence\n\nHelp them find things they are good at offline: sport, art, cooking, volunteering, reading or coding. Time with friends in person protects against loneliness. Praise effort and character, not likes.\n\n## When to worry\n\nSeek help if your teen seems very low or anxious, stops eating or sleeping properly, becomes obsessed with appearance, is bullied online, or cannot cut down despite trying. Talk to a doctor or counsellor.","bn":"সোশ্যাল মিডিয়ায় কিশোর-কিশোরীরা যোগাযোগ রাখে, শেখে, নিজের প্রতিভা দেখায়। আবার সেখানে সারাক্ষণ অন্যের সেরা মুহূর্তগুলো ভেসে আসে: নিখুঁত চেহারা, দামি ফোন, বেড়ানোর ছবি, দারুণ রেজাল্ট। অনেকেই নিজের সাধারণ জীবনকে অন্যের বাছাই করা ঝলমলে মুহূর্তের সাথে তুলনা করতে শুরু করে।\n\n## তুলনা যেভাবে প্রভাব ফেলতে পারে\n\n- নিজেকে যথেষ্ট সুন্দর, ধনী বা মেধাবী মনে না হওয়া।\n- লাইক, ফলোয়ার আর কমেন্ট নিয়ে দুশ্চিন্তা।\n- বন্ধুরা তাকে ছাড়া কিছু পোস্ট করলে বাদ পড়ার কষ্ট।\n- গভীর রাত পর্যন্ত স্ক্রল করে ঘুম নষ্ট।\n\nসবার ওপর একইভাবে প্রভাব পড়ে না। শুধু কত ঘণ্টা ব্যবহার করছে তা নয়, সোশ্যাল মিডিয়া ব্যবহারের পর তার মন কেমন থাকে, সেটা খেয়াল করুন।\n\n## কোনটা আসল, তা নিয়ে কথা বলুন\n\n- বুঝিয়ে বলুন, ছবি বেছে, এডিট করে, ফিল্টার দিয়ে পোস্ট করা হয়; খারাপ দিনের ছবি কেউ দেয় না বললেই চলে।\n- জিজ্ঞেস করুন: “এক ঘণ্টা স্ক্রল করার পর তোমার কেমন লাগে — ভালো, না খারাপ?”\n- ইনফ্লুয়েন্সার আর বিজ্ঞাপন নিয়ে আলোচনা করুন: কে টাকা দিচ্ছে, আর আসলে কী বিক্রি করছে?\n- অন্যের সাথে নিজেকে তুলনা করার আপনার নিজের অভিজ্ঞতাও বলুন।\n\n## পারিবারিক মিডিয়া পরিকল্পনা\n\n- ফোন ছাড়া সময় ঠিক করুন: খাওয়া, পড়া, নামাজ বা পরিবারের সময়, আর ঘুমের আগের এক ঘণ্টা।\n- রাতে ফোন শোবার ঘরের বাইরে।\n- যে অ্যাকাউন্ট দেখলে মন খারাপ হয় সেগুলো আনফলো, আর যেগুলো শেখায়, অনুপ্রেরণা দেয় বা হাসায় সেগুলো ফলো করা।\n- অপ্রয়োজনীয় নোটিফিকেশন বন্ধ।\n- একসাথে প্রাইভেসি সেটিং দেখে নেওয়া।\n\n## নিজে উদাহরণ হোন\n\nখাবার টেবিলে বাবা-মা ফোন স্ক্রল করলে সন্তান ঠিকই খেয়াল করে। সন্তান কথা বললে নিজের ফোনটা নামিয়ে রাখুন।\n\n## বাস্তব জীবনে আত্মবিশ্বাস\n\nফোনের বাইরে সে কোন কাজে ভালো, তা খুঁজে পেতে সাহায্য করুন: খেলাধুলা, আঁকা, রান্না, স্বেচ্ছাসেবা, বই পড়া বা কোডিং। সামনাসামনি বন্ধুদের সাথে সময় কাটালে একাকিত্ব কমে। লাইক নয়, চেষ্টা আর চরিত্রের প্রশংসা করুন।\n\n## কখন চিন্তা করবেন\n\nসে খুব মনমরা বা উদ্বিগ্ন থাকলে, ঠিকমতো খাওয়া বা ঘুম বন্ধ হয়ে গেলে, চেহারা নিয়ে অতিরিক্ত মগ্ন হলে, অনলাইনে বুলিংয়ের শিকার হলে, বা চেষ্টা করেও ব্যবহার কমাতে না পারলে ডাক্তার বা কাউন্সেলরের সাথে কথা বলুন।"}'::jsonb, '{}'::jsonb, 4, 4748, 7305, '{}'::text[], 'any', ARRAY['social media', 'comparison', 'self-esteem', 'family media plan', 'screen time', 'influencers']::text[], false, 'in_review'::lp_review_status, 8016),
  ('tn-gaming-internet-addiction', 'article', 'scientific', 'shared', 'important', 'guideline', '🎮', '{"en":"Gaming and internet addiction","bn":"গেম ও ইন্টারনেট আসক্তি"}'::jsonb, '{"en":"Most gaming is harmless fun, but for some teens it takes over sleep, school and family life. How to tell the difference, set limits that work, and when to get help.","bn":"বেশিরভাগ ক্ষেত্রে গেম নিরীহ বিনোদন, কিন্তু কারও কারও ঘুম, পড়াশোনা আর পরিবারের সময় সবই দখল করে নেয়। পার্থক্য কীভাবে বুঝবেন, কোন সীমা কাজ করে, আর কখন সাহায্য নেবেন।"}'::jsonb, '{"en":"Games and the internet are part of teen life. Playing with friends can be fun, social and even educational. For a small number of teens, though, gaming or being online becomes so strong that it takes over their life. WHO recognises ''gaming disorder'' as a health condition.\n\n## Healthy use\n\nGames fit around school, sleep, meals, prayer and family time, and your teen can stop when asked, even if they grumble.\n\n## Warning signs of a problem\n\nEspecially if these go on for months:\n\n- Losing control over how long they play.\n- Gaming or scrolling coming before sleep, meals, studies and friends.\n- Carrying on despite clear harm: falling grades, missing school, fights at home.\n- Anger, restlessness or low mood when they cannot play.\n- Lying about time online, or spending money secretly on games.\n- Playing through the night.\n\n## What helps\n\n- Agree limits together and write them into a family media plan.\n- Set device-free times: before school, during homework and meals, and at least an hour before bed.\n- Keep consoles, computers and phones in shared rooms, not bedrooms.\n- Use parental controls and spending limits on app stores.\n- Check each game''s age rating, chat features and in-game purchases.\n- Offer alternatives: sport, outdoor time, clubs, a real responsibility.\n- Play a game with them now and then; you''ll understand the appeal and keep talking.\n\n## Cutting down\n\nSudden total bans often lead to big fights and secret use. Reduce step by step, explain why, and give back time as your teen sticks to the plan. Praise their effort.\n\n## Look underneath\n\nHeavy gaming can be a way to escape loneliness, bullying, anxiety, depression or attention difficulties such as ADHD. Ask gently how life is going, at school and with friends.\n\n## When to get help\n\nIf your teen cannot cut down despite trying, misses school, becomes aggressive when stopped, or seems depressed, talk to a doctor, psychiatrist or psychologist.","bn":"গেম আর ইন্টারনেট এখন কিশোর জীবনের অংশ। বন্ধুদের সাথে খেলা মজার, সামাজিক, এমনকি শিক্ষণীয়ও হতে পারে। তবে অল্প কিছু কিশোর-কিশোরীর বেলায় গেম বা অনলাইনের টান এত বেশি হয় যে পুরো জীবনটাই দখল করে নেয়। বিশ্ব স্বাস্থ্য সংস্থা (WHO) “গেমিং ডিসঅর্ডার”-কে একটি স্বাস্থ্য সমস্যা হিসেবে স্বীকৃতি দিয়েছে।\n\n## সুস্থ ব্যবহার\n\nগেম চলে পড়াশোনা, ঘুম, খাওয়া, নামাজ আর পরিবারের সময়ের ফাঁকে ফাঁকে, আর বললে সে থামতে পারে — একটু গজগজ করলেও।\n\n## সমস্যার সতর্কসংকেত\n\nবিশেষ করে যদি মাসের পর মাস চলে:\n\n- কতক্ষণ খেলবে, তার ওপর নিয়ন্ত্রণ হারানো।\n- ঘুম, খাওয়া, পড়া আর বন্ধুর চেয়ে গেম বা স্ক্রলিং আগে।\n- স্পষ্ট ক্ষতি সত্ত্বেও চালিয়ে যাওয়া: রেজাল্ট খারাপ, স্কুল কামাই, ঘরে ঝগড়া।\n- খেলতে না পারলে রাগ, অস্থিরতা বা মন খারাপ।\n- অনলাইনে কত সময় কাটায় তা নিয়ে মিথ্যা বলা, বা গোপনে গেমে টাকা খরচ।\n- সারারাত জেগে খেলা।\n\n## যা সাহায্য করে\n\n- একসাথে সীমা ঠিক করে পারিবারিক মিডিয়া পরিকল্পনায় লিখে রাখুন।\n- ডিভাইস ছাড়া সময় ঠিক করুন: স্কুলের আগে, পড়া আর খাওয়ার সময়, আর ঘুমের অন্তত এক ঘণ্টা আগে।\n- কনসোল, কম্পিউটার আর ফোন শোবার ঘরে নয়, সবার ব্যবহারের ঘরে রাখুন।\n- প্যারেন্টাল কন্ট্রোল আর অ্যাপ স্টোরে খরচের সীমা ব্যবহার করুন।\n- প্রতিটি গেমের বয়সসীমা, চ্যাট সুবিধা আর গেমের ভেতরে কেনাকাটার ব্যবস্থা দেখে নিন।\n- বিকল্প দিন: খেলাধুলা, বাইরে সময় কাটানো, ক্লাব, ঘরের কোনো সত্যিকারের দায়িত্ব।\n- মাঝে মাঝে তার সাথে একটা গেম খেলুন; আকর্ষণটা বুঝবেন, কথাও চালু থাকবে।\n\n## ধীরে ধীরে কমানো\n\nহঠাৎ পুরোপুরি নিষেধ করলে প্রায়ই বড় ঝগড়া হয় আর লুকিয়ে খেলা শুরু হয়। কারণ বুঝিয়ে ধাপে ধাপে কমান, আর পরিকল্পনা মেনে চললে কিছুটা সময় ফিরিয়ে দিন। তার চেষ্টার প্রশংসা করুন।\n\n## ভেতরের কারণ খুঁজুন\n\nঅতিরিক্ত গেম অনেক সময় একাকিত্ব, বুলিং, উদ্বেগ, বিষণ্নতা বা এডিএইচডির (ADHD) মতো মনোযোগের সমস্যা থেকে পালানোর উপায় হয়। স্কুলে আর বন্ধুদের সাথে দিন কেমন যাচ্ছে, নরমভাবে জিজ্ঞেস করুন।\n\n## কখন সাহায্য নেবেন\n\nচেষ্টা করেও কমাতে না পারলে, স্কুল কামাই করলে, থামাতে গেলে আক্রমণাত্মক হলে, বা বিষণ্ন মনে হলে ডাক্তার, মনোরোগ বিশেষজ্ঞ বা সাইকোলজিস্টের সাথে কথা বলুন।"}'::jsonb, '{}'::jsonb, 4, 4748, 7305, '{}'::text[], 'any', ARRAY['gaming', 'gaming disorder', 'internet addiction', 'screen time', 'parental controls', 'in-game purchases']::text[], false, 'in_review'::lp_review_status, 8017),
  ('tn-smoking-vaping-drugs', 'article', 'scientific', 'shared', 'important', 'consensus', '🚭', '{"en":"Smoking, vaping and drugs, including yaba","bn":"ধূমপান, ভেপ ও মাদক — ইয়াবাসহ"}'::jsonb, '{"en":"What teens are offered, why they try it, how to talk before there is a problem, the signs of drug use, and where to get help in Bangladesh.","bn":"কিশোর-কিশোরীদের কী কী সাধা হয়, কেন তারা চেখে দেখে, সমস্যার আগেই কীভাবে কথা বলবেন, মাদক নেওয়ার লক্ষণ, আর বাংলাদেশে কোথায় সাহায্য পাবেন।"}'::jsonb, '{"en":"Many teens in Bangladesh are offered cigarettes, vapes or drugs by friends, older youths or sellers near schools and markets. Talking early and calmly makes it more likely your teen will say no, and will come to you if they slip.\n\n## What they are\n\n- **Cigarettes and other tobacco**, such as bidi, jorda and gul, contain nicotine, which is highly addictive, especially for a developing brain. Tobacco damages the lungs and heart and causes cancer.\n- **Vapes (e-cigarettes)** are often sold as harmless and fruity, but most contain nicotine and other harmful chemicals, and they can lead teens into smoking.\n- **Yaba** tablets contain methamphetamine and caffeine. Yaba is highly addictive and can cause sleeplessness, aggression, paranoia, heart problems and serious mental illness. Carrying or selling it is a serious crime in Bangladesh.\n- **Other substances** some young people use include cannabis (ganja), alcohol, codeine cough syrups such as phensedyl, sleeping pills and glue sniffing.\n\n## Why teens try them\n\nCuriosity, wanting to fit in, stress from exams or family problems, boredom, or wanting to stay awake to study. Some are told that yaba helps them study or lose weight. This is false and dangerous.\n\n## How to talk\n\n- Start before there is a problem, at a calm moment, for example after a news story.\n- Ask what they know and what they have seen at school.\n- Share clear facts and your family''s values without exaggerating.\n- Practise ways to say no: “No thanks, I''ve got practice tomorrow,” or simply “No.”\n- Tell them they can always call you to be picked up, with no questions in the moment.\n- If you smoke, think about quitting; your example matters.\n\n## Signs of possible drug use\n\n- Sudden changes in friends, mood, sleep or appetite.\n- Red eyes, weight loss, staying awake for nights then sleeping for long periods.\n- Money or things missing from home, or unexplained money.\n- Falling grades, skipping school, secrecy, aggression.\n- Smell of smoke, lighters, foil, pills or small plastic packets.\n\nThese signs can have other causes, so talk before you accuse.\n\n## Where to get help\n\nTalk to your doctor or a psychiatrist. Medical college hospitals have psychiatry departments, and the Department of Narcotics Control runs government treatment centres. Avoid unregistered ''rehab'' centres that use chains, beatings or locking people up. For an overdose, fits, chest pain, severe confusion or violent behaviour, call 999 or go to hospital now.","bn":"বাংলাদেশে অনেক কিশোর-কিশোরীকে বন্ধু, বড় ভাই-ব্রাদার বা স্কুল-বাজারের আশপাশের বিক্রেতারা সিগারেট, ভেপ বা মাদক সাধে। আগেভাগে শান্তভাবে কথা বললে সন্তান “না” বলতে পারবে, আর পা পিছলালেও আপনার কাছেই আসবে — এমন সম্ভাবনা বাড়ে।\n\n## এগুলো কী\n\n- **সিগারেট ও অন্যান্য তামাক** — বিড়ি, জর্দা, গুল — এগুলোতে নিকোটিন থাকে, যা প্রচণ্ড আসক্তিকর, বিশেষ করে বেড়ে ওঠা মস্তিষ্কের জন্য। তামাক ফুসফুস আর হৃৎপিণ্ডের ক্ষতি করে, ক্যানসার ঘটায়।\n- **ভেপ (ই-সিগারেট)** প্রায়ই নিরীহ আর ফলের স্বাদের বলে বিক্রি হয়, কিন্তু বেশিরভাগেই নিকোটিন ও অন্যান্য ক্ষতিকর রাসায়নিক থাকে, আর এটা থেকে সিগারেটে আসক্তিও হতে পারে।\n- **ইয়াবা** ট্যাবলেটে থাকে মেথঅ্যামফিটামিন আর ক্যাফেইন। ইয়াবা মারাত্মক আসক্তিকর; এতে ঘুম না আসা, আক্রমণাত্মক আচরণ, সন্দেহবাতিক, হৃদরোগ আর গুরুতর মানসিক রোগ হতে পারে। বাংলাদেশে ইয়াবা বহন বা বিক্রি গুরুতর অপরাধ।\n- **অন্যান্য মাদক** যা কিছু তরুণ ব্যবহার করে: গাঁজা, মদ, ফেনসিডিলের মতো কোডিনযুক্ত কাশির সিরাপ, ঘুমের ওষুধ, আর গ্লু বা আঠার নেশা।\n\n## কেন চেখে দেখে\n\nকৌতূহল, দলে টিকে থাকার ইচ্ছা, পরীক্ষা বা পারিবারিক সমস্যার চাপ, একঘেয়েমি, বা রাত জেগে পড়ার ইচ্ছা। কাউকে বলা হয় ইয়াবা খেলে পড়া মনে থাকে বা ওজন কমে — এটা মিথ্যা এবং বিপজ্জনক।\n\n## কীভাবে কথা বলবেন\n\n- সমস্যা হওয়ার আগেই, শান্ত কোনো মুহূর্তে শুরু করুন — যেমন কোনো খবর দেখার পর।\n- জিজ্ঞেস করুন সে কী জানে, স্কুলে কী দেখেছে।\n- বাড়িয়ে না বলে পরিষ্কার তথ্য আর পরিবারের মূল্যবোধ জানান।\n- “না” বলার কৌশল অনুশীলন করুন: “না রে, কাল প্র্যাকটিস আছে,” বা শুধু “না।”\n- বলে রাখুন, যেকোনো সময় ফোন দিলে আপনি গিয়ে নিয়ে আসবেন, তখনই কোনো প্রশ্ন করবেন না।\n- আপনি নিজে ধূমপান করলে ছাড়ার কথা ভাবুন; আপনার উদাহরণ গুরুত্বপূর্ণ।\n\n## মাদক নেওয়ার সম্ভাব্য লক্ষণ\n\n- হঠাৎ বন্ধু, মেজাজ, ঘুম বা খিদেতে পরিবর্তন।\n- চোখ লাল, ওজন কমে যাওয়া, কয়েক রাত জেগে থেকে তারপর লম্বা ঘুম।\n- ঘর থেকে টাকা বা জিনিস হারানো, বা অজানা উৎসের টাকা।\n- রেজাল্ট খারাপ, স্কুল ফাঁকি, লুকোছাপা, আক্রমণাত্মক আচরণ।\n- ধোঁয়ার গন্ধ, লাইটার, ফয়েল, ট্যাবলেট বা ছোট প্লাস্টিকের প্যাকেট।\n\nএসব লক্ষণের অন্য কারণও থাকতে পারে, তাই অভিযোগ করার আগে কথা বলুন।\n\n## কোথায় সাহায্য পাবেন\n\nডাক্তার বা মনোরোগ বিশেষজ্ঞের সাথে কথা বলুন। মেডিকেল কলেজ হাসপাতালগুলোতে মনোরোগ বিভাগ আছে, আর মাদকদ্রব্য নিয়ন্ত্রণ অধিদপ্তর সরকারি চিকিৎসাকেন্দ্র পরিচালনা করে। যেসব অনিবন্ধিত “রিহ্যাব” শিকল, মারধর বা আটকে রাখার পদ্ধতি ব্যবহার করে, সেগুলো এড়িয়ে চলুন। মাত্রাতিরিক্ত মাদক, খিঁচুনি, বুকে ব্যথা, তীব্র বিভ্রান্তি বা সহিংস আচরণ হলে এখনই ৯৯৯-এ ফোন করুন বা হাসপাতালে যান।"}'::jsonb, '{}'::jsonb, 5, 4748, 7305, '{}'::text[], 'any', ARRAY['smoking', 'vaping', 'e-cigarette', 'drugs', 'yaba', 'nicotine', 'addiction', 'peer pressure']::text[], false, 'in_review'::lp_review_status, 8018),
  ('tn-road-safety', 'article', 'scientific', 'shared', 'important', 'guideline', '🪖', '{"en":"Road safety: helmets, no riding without a licence, and seatbelts","bn":"সড়ক নিরাপত্তা: হেলমেট, লাইসেন্স ছাড়া বাইক নয়, সিটবেল্ট"}'::jsonb, '{"en":"Road crashes are a leading cause of death and injury among young people. Clear family rules on motorbikes, helmets, licences and seatbelts save lives.","bn":"তরুণদের মৃত্যু ও আঘাতের অন্যতম প্রধান কারণ সড়ক দুর্ঘটনা। মোটরবাইক, হেলমেট, লাইসেন্স আর সিটবেল্ট নিয়ে পরিবারের পরিষ্কার নিয়ম জীবন বাঁচায়।"}'::jsonb, '{"en":"Road crashes are one of the leading causes of death and serious injury among young people worldwide. Teens are at higher risk because they are new to the road, take more risks, and are easily distracted by phones and friends.\n\n## Motorbikes\n\n- **No riding without a licence.** In Bangladesh, a driving licence, including for a motorbike, requires the rider to be at least 18 and to pass the test. Do not hand a motorbike to an under-age teen, however much they ask.\n- **A helmet on every ride, for rider and passenger.** A proper helmet, correctly fastened, greatly reduces the risk of serious head injury and death. Choose one that fits snugly and is made for motorbikes, not a cap or a thin plastic one. Replace a helmet after a crash.\n- **No more than two people on a bike.**\n- **No phone use, racing or stunts while riding.**\n- On ride-share bikes, your teen should always wear the helmet offered, or carry their own.\n\n## In cars, buses and CNGs\n\n- Wear a seatbelt in every seat, front and back, on every trip.\n- Never ride on a bus roof or hang from the door.\n- Choose drivers who are rested, sober and careful; your teen has the right to refuse a ride with an unsafe driver.\n\n## Walking and cycling\n\n- Use footbridges and zebra crossings; look both ways, and never cross while using a phone or wearing earphones.\n- On a bicycle, wear a helmet, use lights or reflective strips at night, and keep to the left.\n\n## Your role as a parent\n\n- Be the example: wear your helmet and seatbelt every time, and never use your phone while driving.\n- Make a family rule: “No helmet, no ride.”\n- When your teen is old enough, use a proper driving school and practise with them.\n- Agree that they will call you rather than ride with a driver who is drunk, on drugs or racing.\n\n## After a crash\n\nCall 999 for serious injuries. Do not move someone with a possible neck or back injury unless they are in danger where they are. Any head injury with vomiting, confusion, drowsiness or a fit needs hospital care now.","bn":"বিশ্বজুড়ে তরুণদের মৃত্যু আর গুরুতর আঘাতের অন্যতম প্রধান কারণ সড়ক দুর্ঘটনা। কিশোর-কিশোরীদের ঝুঁকি বেশি, কারণ রাস্তায় তারা নতুন, ঝুঁকি বেশি নেয়, আর ফোন ও বন্ধুদের কারণে সহজে মনোযোগ হারায়।\n\n## মোটরবাইক\n\n- **লাইসেন্স ছাড়া বাইক নয়।** বাংলাদেশে মোটরবাইকসহ যেকোনো ড্রাইভিং লাইসেন্স পেতে বয়স কমপক্ষে ১৮ হতে হয় এবং পরীক্ষায় পাস করতে হয়। সন্তান যত জেদই করুক, অপ্রাপ্তবয়স্কের হাতে বাইক তুলে দেবেন না।\n- **প্রতিবার হেলমেট — চালক ও আরোহী দুজনেরই।** মানসম্মত, ঠিকমতো বেল্ট আটকানো হেলমেট মাথার গুরুতর আঘাত আর মৃত্যুর ঝুঁকি অনেক কমায়। মাথায় ঠিকমতো বসে এমন মোটরবাইকের হেলমেট বেছে নিন — টুপি বা পাতলা প্লাস্টিকেরটা নয়। দুর্ঘটনার পর হেলমেট বদলে ফেলুন।\n- **এক বাইকে দুজনের বেশি নয়।**\n- **চালানোর সময় ফোন, রেস বা স্টান্ট নয়।**\n- রাইড শেয়ারের বাইকে উঠলে দেওয়া হেলমেট অবশ্যই পরবে, বা নিজেরটা সাথে রাখবে।\n\n## গাড়ি, বাস ও সিএনজিতে\n\n- সামনে-পেছনে যেকোনো সিটে, প্রতিটি যাত্রায় সিটবেল্ট বাঁধবে।\n- কখনো বাসের ছাদে চড়বে না বা দরজায় ঝুলবে না।\n- বিশ্রাম নেওয়া, নেশামুক্ত ও সাবধানী চালক বেছে নিন; অনিরাপদ চালকের গাড়িতে উঠতে অস্বীকার করার অধিকার সন্তানের আছে।\n\n## হাঁটা ও সাইকেল\n\n- ফুটওভারব্রিজ আর জেব্রা ক্রসিং ব্যবহার করবে; দুই দিক দেখবে, আর ফোন হাতে বা কানে ইয়ারফোন নিয়ে কখনো রাস্তা পার হবে না।\n- সাইকেলে হেলমেট পরবে, রাতে লাইট বা রিফ্লেক্টর লাগাবে, আর বাঁ দিক দিয়ে চলবে।\n\n## বাবা-মা হিসেবে আপনার ভূমিকা\n\n- নিজে উদাহরণ হোন: প্রতিবার হেলমেট আর সিটবেল্ট, আর গাড়ি চালানোর সময় কখনো ফোন নয়।\n- পরিবারের নিয়ম করুন: “হেলমেট নেই তো বাইকে চড়া নেই।”\n- বয়স হলে সঠিক ড্রাইভিং স্কুলে শেখান, নিজেও সাথে অনুশীলন করান।\n- কথা দিন-নিন: নেশাগ্রস্ত বা রেস করা চালকের সাথে না গিয়ে সে আপনাকে ফোন দেবে।\n\n## দুর্ঘটনার পর\n\nগুরুতর আঘাতে ৯৯৯-এ ফোন করুন। ঘাড় বা মেরুদণ্ডে আঘাতের সন্দেহ থাকলে, জায়গাটা বিপজ্জনক না হলে তাকে নাড়াবেন না। মাথায় আঘাতের পর বমি, বিভ্রান্তি, ঝিমুনি বা খিঁচুনি হলে এখনই হাসপাতালে নিন।"}'::jsonb, '{}'::jsonb, 4, 4748, 7305, '{}'::text[], 'any', ARRAY['road safety', 'helmet', 'motorbike', 'driving licence', 'seatbelt', 'pedestrian', 'bicycle']::text[], false, 'in_review'::lp_review_status, 8019),
  ('tn-teen-sleep', 'article', 'scientific', 'shared', 'routine', 'guideline', '🌙', '{"en":"Sleep for teens: why 8–10 hours matters","bn":"কিশোর বয়সের ঘুম: কেন ৮–১০ ঘণ্টা জরুরি"}'::jsonb, '{"en":"Teens need 8–10 hours of sleep, yet many get far less. Why sleep matters for learning, mood and safety, and a simple plan to get more of it.","bn":"কিশোর-কিশোরীদের ৮–১০ ঘণ্টা ঘুম দরকার, অথচ অনেকে পায় তার চেয়ে অনেক কম। পড়া, মেজাজ আর নিরাপত্তার জন্য ঘুম কেন জরুরি, আর বেশি ঘুমানোর সহজ পরিকল্পনা।"}'::jsonb, '{"en":"Teenagers need about 8 to 10 hours of sleep a night, more than most adults. Yet many get far less, because of early school or coaching, homework, phones, and a body clock that shifts later during puberty.\n\n## Why sleep matters\n\n- **Learning:** the brain stores what was studied during sleep.\n- **Mood:** lack of sleep makes teens more irritable, anxious and low.\n- **Growth and health:** growth hormone and the immune system do much of their work during sleep.\n- **Safety:** sleepy teens have more accidents, including on the road.\n- **Weight:** too little sleep is linked with unhealthy weight gain.\n\n## Signs your teen is not sleeping enough\n\n- Hard to wake, or falling asleep in class or while studying.\n- Sleeping very late on holidays to ''catch up''.\n- Irritable, low or unable to concentrate.\n- Needing lots of tea, coffee or energy drinks.\n\n## A plan for better sleep\n\n- Keep regular sleep and wake times, including on Fridays and holidays, within about an hour.\n- Turn off phones, laptops and TV at least an hour before bed, and charge them outside the bedroom.\n- Avoid caffeine (tea, coffee, cola, energy drinks) in the afternoon and evening.\n- Get daylight and physical activity during the day; teens should aim for about an hour of activity daily.\n- A short nap of 20–30 minutes after school can help, but long or late naps make night sleep harder.\n- Keep the bedroom dark, quiet and comfortable, with a fan or mosquito net as needed.\n- Follow a calm routine before bed: a bath, wudu and prayer for families who pray, light reading or quiet talk.\n\n## During exams\n\nStudying all night harms memory and exam performance. Plan study early and protect sleep, especially the night before an exam.\n\n## The parents'' part\n\nAgree a phone-off time together and keep it yourselves too. Where you can, avoid very early and very late coaching on the same day.\n\n## When to see a doctor\n\nLoud snoring with pauses in breathing, trouble sleeping most nights for weeks, sleeping much more than usual, or low mood together with sleep changes.","bn":"কিশোর-কিশোরীদের রাতে প্রায় ৮ থেকে ১০ ঘণ্টা ঘুম দরকার — বেশিরভাগ বড়দের চেয়েও বেশি। অথচ সকালের স্কুল বা কোচিং, বাড়ির কাজ, ফোন, আর বয়ঃসন্ধিতে পিছিয়ে যাওয়া শরীরের ঘড়ির কারণে অনেকেই এর চেয়ে অনেক কম ঘুমায়।\n\n## ঘুম কেন জরুরি\n\n- **পড়াশোনা:** যা পড়া হয়েছে, ঘুমের মধ্যে মস্তিষ্ক তা গেঁথে রাখে।\n- **মেজাজ:** ঘুম কম হলে খিটখিটে ভাব, উদ্বেগ আর মন খারাপ বাড়ে।\n- **বৃদ্ধি ও স্বাস্থ্য:** গ্রোথ হরমোন আর রোগ প্রতিরোধ ব্যবস্থার অনেক কাজ চলে ঘুমের সময়।\n- **নিরাপত্তা:** ঘুমকাতুরে কিশোর-কিশোরীর দুর্ঘটনা বেশি হয়, রাস্তাতেও।\n- **ওজন:** কম ঘুমের সাথে অস্বাস্থ্যকর ওজন বাড়ার সম্পর্ক আছে।\n\n## যথেষ্ট ঘুম না হওয়ার লক্ষণ\n\n- সকালে উঠতে খুব কষ্ট, বা ক্লাসে বা পড়তে বসে ঘুমিয়ে পড়া।\n- ছুটির দিনে ঘুম “পুষিয়ে নিতে” অনেক বেলা পর্যন্ত ঘুমানো।\n- খিটখিটে, মনমরা, মনোযোগ দিতে না পারা।\n- অনেক চা, কফি বা এনার্জি ড্রিংক লাগা।\n\n## ভালো ঘুমের পরিকল্পনা\n\n- ঘুমানো আর ওঠার সময় নিয়মিত রাখুন — শুক্রবার আর ছুটির দিনেও, মোটামুটি এক ঘণ্টার এদিক-ওদিক।\n- ঘুমের অন্তত এক ঘণ্টা আগে ফোন, ল্যাপটপ আর টিভি বন্ধ; চার্জ হবে শোবার ঘরের বাইরে।\n- বিকেল আর সন্ধ্যার পর ক্যাফেইন — চা, কফি, কোলা, এনার্জি ড্রিংক — এড়িয়ে চলুন।\n- দিনে রোদ আর শারীরিক কর্মকাণ্ড; কিশোর বয়সে প্রতিদিন প্রায় এক ঘণ্টা সক্রিয় থাকার লক্ষ্য রাখুন।\n- স্কুলের পর ২০–৩০ মিনিটের ছোট ঘুম কাজে দিতে পারে, কিন্তু লম্বা বা দেরিতে দিনের ঘুম রাতের ঘুম নষ্ট করে।\n- শোবার ঘর অন্ধকার, শান্ত আর আরামদায়ক রাখুন, দরকারমতো ফ্যান বা মশারি।\n- ঘুমের আগে শান্ত রুটিন: গোসল, যারা নামাজ পড়েন তাদের জন্য অজু ও নামাজ, হালকা বই পড়া বা নিচু স্বরে গল্প।\n\n## পরীক্ষার সময়\n\nসারারাত জেগে পড়লে স্মৃতিশক্তি আর পরীক্ষার পারফরম্যান্স দুটোই কমে। আগে থেকে পড়ার পরিকল্পনা করুন, আর ঘুম রক্ষা করুন — বিশেষ করে পরীক্ষার আগের রাতে।\n\n## বাবা-মায়ের ভূমিকা\n\nফোন বন্ধের সময় একসাথে ঠিক করুন, আর নিজেরাও মানুন। সম্ভব হলে একই দিনে খুব ভোরে আর খুব রাতে কোচিং এড়িয়ে চলুন।\n\n## কখন ডাক্তার দেখাবেন\n\nজোরে নাক ডাকা আর ঘুমের মধ্যে শ্বাস থেমে থেমে যাওয়া, কয়েক সপ্তাহ ধরে বেশিরভাগ রাতে ঘুম না আসা, স্বাভাবিকের চেয়ে অনেক বেশি ঘুমানো, বা ঘুমের পরিবর্তনের সাথে মন খারাপ থাকলে।"}'::jsonb, '{}'::jsonb, 4, 4748, 7305, '{}'::text[], 'any', ARRAY['sleep', 'teen sleep', 'bedtime', 'phones', 'caffeine', 'body clock', 'naps']::text[], false, 'in_review'::lp_review_status, 8020),
  ('tn-hpv-vaccine', 'article', 'scientific', 'shared', 'important', 'guideline', '💉', '{"en":"The HPV vaccine for girls","bn":"মেয়েদের জন্য এইচপিভি টিকা"}'::jsonb, '{"en":"The HPV vaccine protects against the virus that causes most cervical cancer. Bangladesh gives it free to girls in the eligible age group through the national programme (EPI).","bn":"এইচপিভি টিকা জরায়ুমুখ ক্যানসারের প্রধান কারণ ভাইরাসটি থেকে সুরক্ষা দেয়। জাতীয় টিকাদান কর্মসূচির (ইপিআই) মাধ্যমে নির্ধারিত বয়সের মেয়েদের বাংলাদেশে বিনামূল্যে এই টিকা দেওয়া হয়।"}'::jsonb, '{"en":"The HPV vaccine protects girls against human papillomavirus (HPV), the main cause of cervical cancer. Cervical cancer is one of the common cancers in women in Bangladesh, and much of it can be prevented.\n\n## What is HPV?\n\nHPV is a very common virus. Most infections clear by themselves, but some types can stay and, over many years, cause changes in the cervix (the neck of the womb) that can turn into cancer. The vaccine works best when given before any exposure to the virus, which is why it is given to young girls.\n\n## The vaccine in Bangladesh\n\nBangladesh has added the HPV vaccine to its national immunisation programme (EPI) and gives it free to girls in the eligible age group, through schools and EPI centres, in national campaigns. WHO recommends the vaccine mainly for girls aged 9 to 14. The eligible ages, the number of doses and how to register are set by the national programme, so check with your daughter''s school, the nearest EPI centre, community clinic or Upazila Health Complex. If your daughter missed the campaign, ask whether she can still receive it.\n\n## Is it safe?\n\nThe HPV vaccine has been given to many millions of girls worldwide and is closely monitored for safety. Common side effects are mild: a sore arm, mild fever, headache or tiredness for a day or two. Some teens feel faint after any injection, so she should sit down for about 15 minutes afterwards.\n\nThe vaccine does not harm fertility, periods or a girl''s future ability to have children. It simply protects against a cancer.\n\n## Good to know\n\n- Keep the vaccination card or certificate safe.\n- Tell the vaccinator if your daughter has ever had a serious allergic reaction to a vaccine.\n- The vaccine does not protect against every type of HPV, so as an adult she should still have cervical cancer screening as her doctor advises.\n\n## When to get help\n\nAfter any vaccine, get help immediately for swelling of the face or lips, difficulty breathing or a widespread rash: call 999 or go to hospital. See a doctor for a high fever or any reaction that worries you.","bn":"এইচপিভি টিকা মেয়েদের হিউম্যান প্যাপিলোমা ভাইরাস (HPV) থেকে সুরক্ষা দেয়, যা জরায়ুমুখ ক্যানসারের (cervical cancer) প্রধান কারণ। বাংলাদেশে নারীদের মধ্যে জরায়ুমুখ ক্যানসার একটি সাধারণ ক্যানসার, আর এর বড় অংশই প্রতিরোধ করা সম্ভব।\n\n## এইচপিভি কী\n\nএইচপিভি খুব সাধারণ একটি ভাইরাস। বেশিরভাগ সংক্রমণ নিজে থেকেই সেরে যায়, কিন্তু কিছু ধরন শরীরে থেকে যায় এবং অনেক বছর ধরে জরায়ুমুখে এমন পরিবর্তন ঘটায় যা ক্যানসারে রূপ নিতে পারে। ভাইরাসের সংস্পর্শে আসার আগে দিলে টিকা সবচেয়ে ভালো কাজ করে — তাই অল্প বয়সী মেয়েদের এটা দেওয়া হয়।\n\n## বাংলাদেশে এই টিকা\n\nবাংলাদেশ জাতীয় টিকাদান কর্মসূচিতে (ইপিআই) এইচপিভি টিকা যুক্ত করেছে, এবং জাতীয় ক্যাম্পেইনের মাধ্যমে স্কুল ও ইপিআই কেন্দ্রে নির্ধারিত বয়সের মেয়েদের বিনামূল্যে দিচ্ছে। বিশ্ব স্বাস্থ্য সংস্থা মূলত ৯ থেকে ১৪ বছরের মেয়েদের জন্য এই টিকার সুপারিশ করে। কোন বয়সের মেয়েরা পাবে, কয় ডোজ, আর কীভাবে নিবন্ধন করতে হবে — তা জাতীয় কর্মসূচি ঠিক করে; তাই মেয়ের স্কুল, নিকটস্থ ইপিআই কেন্দ্র, কমিউনিটি ক্লিনিক বা উপজেলা স্বাস্থ্য কমপ্লেক্সে জেনে নিন। মেয়ে ক্যাম্পেইনে বাদ পড়ে থাকলে এখনও নিতে পারবে কিনা জিজ্ঞেস করুন।\n\n## টিকাটি কি নিরাপদ?\n\nবিশ্বজুড়ে কোটি কোটি মেয়েকে এইচপিভি টিকা দেওয়া হয়েছে, আর এর নিরাপত্তা নিয়মিত নজরদারিতে থাকে। সাধারণ পার্শ্বপ্রতিক্রিয়া হালকা: এক-দুই দিন হাতে ব্যথা, হালকা জ্বর, মাথাব্যথা বা ক্লান্তি। যেকোনো ইনজেকশনের পর কারও কারও মাথা ঘোরে, তাই টিকার পর প্রায় ১৫ মিনিট বসে থাকা ভালো।\n\nএই টিকা প্রজনন ক্ষমতা, মাসিক বা ভবিষ্যতে সন্তান ধারণের কোনো ক্ষতি করে না। এটা শুধু একটি ক্যানসার থেকে সুরক্ষা দেয়।\n\n## জেনে রাখুন\n\n- টিকা কার্ড বা সনদ যত্ন করে রাখুন।\n- আগে কোনো টিকায় মারাত্মক অ্যালার্জি হয়ে থাকলে টিকাদানকারীকে জানান।\n- এই টিকা সব ধরনের এইচপিভি থেকে সুরক্ষা দেয় না, তাই বড় হয়ে ডাক্তারের পরামর্শমতো জরায়ুমুখ ক্যানসারের স্ক্রিনিং করাতে হবে।\n\n## কখন সাহায্য নেবেন\n\nযেকোনো টিকার পর মুখ বা ঠোঁট ফুলে গেলে, শ্বাসকষ্ট হলে বা সারা শরীরে র‍্যাশ উঠলে সাথে সাথে ৯৯৯-এ ফোন করুন বা হাসপাতালে যান। বেশি জ্বর বা দুশ্চিন্তার মতো কোনো প্রতিক্রিয়া হলে ডাক্তার দেখান।"}'::jsonb, '{}'::jsonb, 3, 4748, 5844, '{}'::text[], 'female', ARRAY['hpv', 'hpv vaccine', 'cervical cancer', 'epi', 'vaccination', 'girls']::text[], false, 'in_review'::lp_review_status, 8021),
  ('tn-father-and-teen', 'article', 'general', 'father', 'routine', 'consensus', '👨', '{"en":"The father''s role with teenagers","bn":"কিশোর সন্তানের জীবনে বাবার ভূমিকা"}'::jsonb, '{"en":"Many fathers step back in the teen years, just when they are needed most. Concrete ways to stay close to sons and daughters, even when you work far away.","bn":"অনেক বাবা কৈশোরে সরে যান — ঠিক যখন তাঁদের সবচেয়ে বেশি দরকার। দূরে কাজ করলেও ছেলে-মেয়ের কাছাকাছি থাকার বাস্তব কিছু উপায়।"}'::jsonb, '{"en":"Fathers matter as much in the teen years as in early childhood. A warm, involved father, or a father figure such as an uncle or grandfather, gives a teen confidence and another safe adult to turn to. Yet many fathers in Bangladesh step back at this age, busy with work, assuming the mother handles ''family matters''.\n\n## What teens need from their father\n\n- **Time:** a regular walk, tea at a stall, a game of cricket or a ride to coaching. Side-by-side moments make talking easier.\n- **Listening:** let them finish before you advise. Ask about their friends, dreams and worries.\n- **Calm authority:** clear rules, explained, with fair consequences and no hitting or shouting.\n- **Respect:** knock before entering, don''t mock them in front of others, and apologise when you are wrong.\n- **Example:** how you treat their mother, manage anger, use your phone, drive and handle money teaches more than any lecture.\n\n## With daughters\n\nA father''s respect shapes how a daughter expects to be treated by others. Praise her mind, skills and character, not only her looks. Support her education and ambitions. Know the basics of puberty and periods so she is never embarrassed to ask you for pads or medicine.\n\n## With sons\n\nShow that real strength includes kindness, self-control and helping at home. Talk openly about puberty, anger, respect for girls and consent, and the dangers of drugs, betting and reckless riding. Teach practical skills: fixing things, handling money, cooking.\n\n## When you live away\n\nMany Bangladeshi fathers work abroad or in another city. Keep a fixed weekly video call, send short messages, ask specific questions and follow up next time. Agree decisions with the mother so you stand together, and plan one-to-one time when you are home.\n\n## Jobs a father can own\n\n- Teach one life skill a month: banking, paying bills, a simple repair.\n- Be the one who checks the helmet and the ride home.\n- Go to parent–teacher meetings.\n- Take charge of exam-day transport.\n\nIf you struggle with anger, stress, smoking or other addictions yourself, getting help is one of the best gifts you can give your teen.","bn":"শৈশবের মতো কৈশোরেও বাবা সমান গুরুত্বপূর্ণ। স্নেহশীল, পাশে থাকা বাবা — কিংবা চাচা, মামা বা দাদা-নানার মতো বাবার জায়গায় থাকা কেউ — সন্তানকে আত্মবিশ্বাস দেন, আর ভরসা করার মতো আরেকজন মানুষ দেন। তবু বাংলাদেশে অনেক বাবা এই বয়সে কাজের চাপে সরে যান, ভাবেন “সংসারের ব্যাপার” মা-ই সামলাবেন।\n\n## বাবার কাছে কিশোর সন্তান যা চায়\n\n- **সময়:** নিয়মিত একসাথে হাঁটা, টং দোকানে চা, ক্রিকেট খেলা বা কোচিংয়ে পৌঁছে দেওয়া। পাশাপাশি থাকলে কথা বলা সহজ হয়।\n- **শোনা:** পরামর্শ দেওয়ার আগে তাকে কথা শেষ করতে দিন। বন্ধু, স্বপ্ন আর দুশ্চিন্তার কথা জিজ্ঞেস করুন।\n- **শান্ত কর্তৃত্ব:** বুঝিয়ে বলা পরিষ্কার নিয়ম, ন্যায্য পরিণাম — মারধর বা চিৎকার ছাড়া।\n- **সম্মান:** ঘরে ঢোকার আগে টোকা দিন, অন্যের সামনে ঠাট্টা করবেন না, ভুল হলে দুঃখ প্রকাশ করুন।\n- **উদাহরণ:** মায়ের সাথে আপনার আচরণ, রাগ সামলানো, ফোন ব্যবহার, গাড়ি চালানো, টাকা সামলানো — যেকোনো উপদেশের চেয়ে এগুলো বেশি শেখায়।\n\n## মেয়ের সাথে\n\nবাবার সম্মান থেকেই মেয়ে শেখে অন্যদের কাছ থেকে কেমন আচরণ পাওয়ার যোগ্য সে। শুধু চেহারা নয়, তার বুদ্ধি, দক্ষতা আর চরিত্রের প্রশংসা করুন। তার পড়াশোনা আর স্বপ্নের পাশে থাকুন। বয়ঃসন্ধি আর মাসিকের মূল কথাগুলো জেনে রাখুন, যেন প্যাড বা ওষুধ চাইতে সে কখনো আপনার কাছে লজ্জা না পায়।\n\n## ছেলের সাথে\n\nদেখিয়ে দিন, আসল শক্তির মধ্যে দয়া, আত্মনিয়ন্ত্রণ আর ঘরের কাজে হাত লাগানোও আছে। বয়ঃসন্ধি, রাগ, মেয়েদের প্রতি সম্মান আর সম্মতি নিয়ে, এবং মাদক, বাজি আর বেপরোয়া বাইক চালানোর বিপদ নিয়ে খোলাখুলি কথা বলুন। হাতে-কলমে দক্ষতা শেখান: টুকটাক মেরামত, টাকা সামলানো, রান্না।\n\n## দূরে থাকলে\n\nবাংলাদেশের অনেক বাবা বিদেশে বা অন্য শহরে কাজ করেন। সপ্তাহে একটা নির্দিষ্ট সময়ে ভিডিও কল করুন, ছোট ছোট মেসেজ দিন, নির্দিষ্ট করে প্রশ্ন করুন আর পরের বার খোঁজ নিন। সিদ্ধান্তগুলো মায়ের সাথে মিলিয়ে নিন, যেন দুজনে এক কথা বলেন; আর বাড়ি এলে সন্তানের সাথে একান্ত সময় রাখুন।\n\n## যে দায়িত্বগুলো বাবা নিতে পারেন\n\n- প্রতি মাসে একটা জীবন-দক্ষতা শেখানো: ব্যাংকের কাজ, বিল দেওয়া, ছোটখাটো মেরামত।\n- হেলমেট আর বাড়ি ফেরার ব্যবস্থা দেখার দায়িত্ব নেওয়া।\n- অভিভাবক-শিক্ষক সভায় যাওয়া।\n- পরীক্ষার দিনের যাতায়াতের দায়িত্ব নেওয়া।\n\nরাগ, মানসিক চাপ, ধূমপান বা অন্য কোনো আসক্তির সাথে নিজে লড়াই করলে সাহায্য নেওয়াই হতে পারে সন্তানের জন্য আপনার সবচেয়ে বড় উপহার।"}'::jsonb, '{}'::jsonb, 4, 4748, 7305, '{}'::text[], 'any', ARRAY['father', 'fatherhood', 'teen', 'daughters', 'sons', 'role model', 'father abroad']::text[], false, 'in_review'::lp_review_status, 8022),
  ('tn-teen-exam-stress-guide', 'article', 'general', 'child', 'routine', 'consensus', '🎯', '{"en":"For you: managing exam stress","bn":"তোমার জন্য: পরীক্ষার চাপ সামলানো"}'::jsonb, '{"en":"Feeling nervous before exams is normal. Simple ways to study well, look after your body, calm worry and stay steady in the exam hall.","bn":"পরীক্ষার আগে ভয় লাগা স্বাভাবিক। ভালোভাবে পড়া, শরীরের যত্ন নেওয়া, দুশ্চিন্তা শান্ত করা আর পরীক্ষার হলে স্থির থাকার সহজ কিছু উপায়।"}'::jsonb, '{"en":"Exams like SSC and HSC can feel huge. Feeling nervous is normal; it means you care. Here is how to stop stress from taking over.\n\n## Before the exam\n\n- Make a simple timetable: what to study each day, with breaks, meals, prayer or quiet time, and sleep built in.\n- Study in short blocks of 25–50 minutes, then take a 5–10 minute break.\n- Practise past papers with a timer. The real exam will feel more familiar.\n- Put your phone in another room while you study.\n- Ask teachers or friends about anything you don''t understand, early, not the night before.\n\n## Look after your body\n\n- Sleep 8–10 hours. Your brain stores what you learnt while you sleep; all-nighters make you forget.\n- Eat breakfast and regular meals, and drink water.\n- Move every day: a walk, football, skipping. It clears your head.\n- Go easy on tea, coffee and energy drinks, especially at night.\n\n## When worry takes over\n\nTry this: breathe in slowly while counting to 4, hold for 4, and breathe out for 6. Repeat five times. Write your worries on paper, then write one small thing you can do about each. Talk to someone you trust: a parent, an older brother or sister, a teacher or a friend.\n\n## In the exam hall\n\n- Read all the questions first, and start with the ones you know.\n- Watch the time and leave a few minutes to check.\n- If your mind goes blank, put your pen down, breathe slowly, and move to another question. It often comes back.\n\n## Remember\n\nYour worth is not a GPA. One exam is one step, not your whole life. People who struggle in exams can still build good work and good lives.\n\n## Get help if\n\nYou can''t sleep for many nights, stop eating, feel hopeless, or have thoughts of hurting yourself. Tell a parent or a trusted adult today. If you feel unsafe right now, call 999 or go to the nearest hospital.","bn":"এসএসসি-এইচএসসির মতো পরীক্ষা অনেক বড় মনে হতে পারে। ভয় লাগা স্বাভাবিক — এর মানে তুমি বিষয়টাকে গুরুত্ব দিচ্ছ। চাপ যেন তোমাকে কাবু না করে, তার কিছু উপায়।\n\n## পরীক্ষার আগে\n\n- সহজ একটা রুটিন বানাও: কোন দিন কী পড়বে, তার সাথে বিরতি, খাওয়া, নামাজ বা নিরিবিলি সময় আর ঘুমও রাখো।\n- ২৫–৫০ মিনিট করে পড়ো, তারপর ৫–১০ মিনিটের বিরতি নাও।\n- ঘড়ি ধরে আগের বছরের প্রশ্ন সমাধান করো। তাহলে আসল পরীক্ষা চেনা চেনা লাগবে।\n- পড়ার সময় ফোন অন্য ঘরে রেখে দাও।\n- যা বুঝতে পারছ না, তা শিক্ষক বা বন্ধুদের আগেভাগেই জিজ্ঞেস করো — আগের রাতে নয়।\n\n## শরীরের যত্ন\n\n- ৮–১০ ঘণ্টা ঘুমাও। ঘুমের মধ্যেই মস্তিষ্ক পড়াগুলো গেঁথে রাখে; সারারাত জাগলে ভুলে যাওয়ার সম্ভাবনা বাড়ে।\n- সকালের নাশতা আর সময়মতো খাবার খাও, পানি খাও।\n- প্রতিদিন একটু নড়াচড়া করো: হাঁটা, ফুটবল, দড়িলাফ। মাথা পরিষ্কার হয়।\n- চা, কফি আর এনার্জি ড্রিংক কম খাও, বিশেষ করে রাতে।\n\n## দুশ্চিন্তা যখন চেপে ধরে\n\nএটা করে দেখো: মনে মনে ৪ গুনে ধীরে শ্বাস নাও, ৪ গুনে ধরে রাখো, ৬ গুনে ছাড়ো। পাঁচবার করো। দুশ্চিন্তাগুলো কাগজে লেখো, তারপর প্রতিটার পাশে লেখো এ নিয়ে ছোট কী একটা করতে পারো। ভরসার কারও সাথে কথা বলো: বাবা-মা, বড় ভাই বা বোন, শিক্ষক বা বন্ধু।\n\n## পরীক্ষার হলে\n\n- আগে সব প্রশ্ন পড়ে নাও, যেগুলো পারো সেগুলো দিয়ে শুরু করো।\n- সময়ের দিকে খেয়াল রাখো, শেষে মিলিয়ে দেখার জন্য কয়েক মিনিট রাখো।\n- হঠাৎ সব ভুলে গেলে কলম নামিয়ে ধীরে শ্বাস নাও, অন্য প্রশ্নে চলে যাও। প্রায়ই পরে মনে পড়ে যায়।\n\n## মনে রেখো\n\nজিপিএ দিয়ে তোমার মূল্য মাপা যায় না। একটা পরীক্ষা জীবনের একটা ধাপ মাত্র, পুরো জীবন নয়। পরীক্ষায় হোঁচট খেয়েও মানুষ ভালো কাজ আর সুন্দর জীবন গড়ে তোলে।\n\n## সাহায্য নাও যদি\n\nঅনেক রাত ঘুম না আসে, খাওয়া বন্ধ হয়ে যায়, সব আশাহীন লাগে, বা নিজের ক্ষতি করার চিন্তা আসে। আজই বাবা-মা বা ভরসার কোনো বড়কে বলো। এই মুহূর্তে নিজেকে অনিরাপদ মনে হলে ৯৯৯-এ ফোন করো বা নিকটস্থ হাসপাতালে যাও।"}'::jsonb, '{}'::jsonb, 3, 4748, 7305, '{}'::text[], 'any', ARRAY['exam stress', 'study tips', 'ssc', 'hsc', 'breathing', 'for teens']::text[], false, 'in_review'::lp_review_status, 8023),
  ('tn-teen-photo-threats-guide', 'article', 'general', 'child', 'important', 'consensus', '🚫', '{"en":"For you: what to do if someone threatens to share your photos","bn":"তোমার জন্য: কেউ তোমার ছবি ছড়িয়ে দেওয়ার হুমকি দিলে কী করবে"}'::jsonb, '{"en":"It is not your fault, and it can be stopped. Don''t pay, don''t send more, save evidence, tell a trusted adult today, and report it.","bn":"এটা তোমার দোষ নয়, আর এটা থামানো যায়। টাকা দেবে না, আর কিছু পাঠাবে না, প্রমাণ রাখবে, আজই ভরসার কোনো বড়কে বলবে, আর রিপোর্ট করবে।"}'::jsonb, '{"en":"If someone is threatening to share your photos or videos, real or fake, this guide is for you. You are not alone, and this can be stopped.\n\n## First: this is not your fault\n\nThe person threatening you is committing a crime. Even if you sent a photo, trusted the wrong person or made a mistake, you deserve help, not blame.\n\n## Do this now\n\n1. **Don''t pay, and don''t send anything more.** Paying almost never ends it; they usually ask for more.\n2. **Stop replying.** You don''t have to explain or argue.\n3. **Save evidence.** Screenshot the messages, the profile, the username, phone numbers and any payment details. Don''t delete the chat yet.\n4. **Tell an adult you trust today:** a parent, an older sibling, an aunt or uncle, or a teacher. You can simply say: “Someone is threatening me online and I need help.”\n5. **Block and report** the account on the app after you have saved the evidence.\n6. **Report it to the police** with your adult: call 999 or go to the local police station. The police have cyber crime units that handle these cases.\n\n## If something has already been shared\n\nReport every post to the platform; most apps remove intimate images when they are reported. Ask friends not to share it and to report it too. Keep your evidence for the police.\n\n## Look after yourself\n\nIt is normal to feel scared, ashamed or panicky. These feelings will ease. Stay close to people who care about you, and don''t stay alone with these thoughts.\n\nIf you feel like hurting yourself, tell someone right now, call 999 or go to the nearest hospital. Your life matters far more than any photo.\n\n## Staying safer online\n\n- Never send intimate photos to anyone, even someone you trust.\n- Keep your accounts private and accept only people you know in real life.\n- Be careful with new online ''friends'' who move fast, flatter you or ask you to switch to a private app.\n- Cover or close your camera when you are not using it.","bn":"কেউ যদি তোমার ছবি বা ভিডিও — আসল হোক বা নকল — ছড়িয়ে দেওয়ার হুমকি দেয়, এই গাইড তোমার জন্য। তুমি একা নও, আর এটা থামানো যায়।\n\n## প্রথম কথা: এটা তোমার দোষ নয়\n\nযে হুমকি দিচ্ছে, সে অপরাধ করছে। তুমি ছবি পাঠিয়ে থাকলেও, ভুল মানুষকে বিশ্বাস করে থাকলেও বা কোনো ভুল করে থাকলেও — তোমার প্রাপ্য সাহায্য, দোষারোপ নয়।\n\n## এখনই যা করবে\n\n১. **টাকা দেবে না, আর কিছু পাঠাবে না।** টাকা দিলে প্রায় কখনোই থামে না; সাধারণত আরও চায়।\n২. **উত্তর দেওয়া বন্ধ করো।** ব্যাখ্যা দেওয়া বা তর্ক করার দরকার নেই।\n৩. **প্রমাণ রাখো।** মেসেজ, প্রোফাইল, ইউজারনেম, ফোন নম্বর আর টাকা চাওয়ার স্ক্রিনশট নাও। এখনই চ্যাট মুছবে না।\n৪. **আজই ভরসার কোনো বড়কে বলো:** বাবা-মা, বড় ভাই বা বোন, খালা, মামা, চাচা বা শিক্ষক। শুধু এটুকু বললেই হবে: “অনলাইনে একজন আমাকে হুমকি দিচ্ছে, আমার সাহায্য দরকার।”\n৫. **প্রমাণ রাখার পর** অ্যাপে অ্যাকাউন্টটা **ব্লক ও রিপোর্ট করো**।\n৬. **বড় কাউকে সাথে নিয়ে পুলিশে জানাও:** ৯৯৯-এ ফোন করো বা নিকটস্থ থানায় যাও। পুলিশের সাইবার অপরাধ ইউনিট এ ধরনের ঘটনা দেখে।\n\n## যদি কিছু ছড়িয়ে গিয়ে থাকে\n\nপ্রতিটি পোস্ট প্ল্যাটফর্মে রিপোর্ট করো; রিপোর্ট পেলে বেশিরভাগ অ্যাপ অন্তরঙ্গ ছবি সরিয়ে দেয়। বন্ধুদের বলো শেয়ার না করতে, বরং রিপোর্ট করতে। পুলিশের জন্য প্রমাণ রেখে দাও।\n\n## নিজের যত্ন নাও\n\nভয়, লজ্জা বা আতঙ্ক লাগা স্বাভাবিক। এই অনুভূতিগুলো কমে আসবে। যারা তোমাকে ভালোবাসে তাদের কাছাকাছি থাকো; এসব চিন্তা নিয়ে একা থেকো না।\n\nনিজের ক্ষতি করতে ইচ্ছে হলে এখনই কাউকে বলো, ৯৯৯-এ ফোন করো বা নিকটস্থ হাসপাতালে যাও। যেকোনো ছবির চেয়ে তোমার জীবন অনেক অনেক বেশি মূল্যবান।\n\n## অনলাইনে আরও নিরাপদ থাকতে\n\n- কাউকে কখনো অন্তরঙ্গ ছবি পাঠাবে না, যাকে বিশ্বাস করো তাকেও না।\n- অ্যাকাউন্ট প্রাইভেট রাখো, শুধু বাস্তবে চেনা মানুষকে যুক্ত করো।\n- যে নতুন অনলাইন “বন্ধু” খুব তাড়াতাড়ি ঘনিষ্ঠ হতে চায়, খুব প্রশংসা করে বা প্রাইভেট অ্যাপে যেতে বলে, তার ব্যাপারে সাবধান থাকো।\n- ক্যামেরা ব্যবহার না করলে ঢেকে বা বন্ধ রাখো।"}'::jsonb, '{}'::jsonb, 3, 4748, 7305, '{}'::text[], 'any', ARRAY['sextortion', 'blackmail', 'photos', 'threats', 'online safety', 'for teens', 'police']::text[], false, 'in_review'::lp_review_status, 8024),
  ('tn-teen-period-self-care', 'article', 'scientific', 'child', 'routine', 'guideline', '🌷', '{"en":"For you: taking care of yourself during your period","bn":"তোমার জন্য: মাসিকের সময় নিজের যত্ন"}'::jsonb, '{"en":"Periods are a normal, healthy part of growing up. How to be prepared, stay clean, ease pain, eat well, and know when to tell a parent or doctor.","bn":"মাসিক বড় হওয়ার স্বাভাবিক, সুস্থ একটা অংশ। কীভাবে প্রস্তুত থাকবে, পরিচ্ছন্ন থাকবে, ব্যথা কমাবে, ভালো খাবে — আর কখন বাবা-মা বা ডাক্তারকে জানাবে।"}'::jsonb, '{"en":"Periods are a normal, healthy part of growing up. Here is how to look after yourself each month.\n\n## Be prepared\n\n- Keep a small pouch in your school bag with two pads or clean cloths, spare underwear and a paper bag for wrapping used pads.\n- Mark your period on a calendar or app so you know roughly when the next one is due. In the first couple of years, irregular periods are common.\n\n## Staying clean\n\n- Change your pad every 4–6 hours, or sooner if bleeding is heavy.\n- If you use cloth, wash it with soap and clean water, dry it in the sun, and keep it in a clean, dry place. Never use a damp cloth.\n- Wash your hands before and after changing.\n- Bathe as usual and wash the outer area with plain water. You don''t need perfumed soaps or powders there.\n- Wrap used pads and put them in a bin, not the toilet.\n\n## Easing pain\n\n- A hot-water bottle on your lower tummy or back.\n- Gentle walking or stretching.\n- Warm drinks and rest.\n- If the pain is strong, ask a parent about a simple painkiller such as paracetamol, taken as a doctor or pharmacist advises.\n\n## Food and energy\n\nYou lose some iron each month. Eat iron-rich foods like eggs, fish, meat, dal and green leafy vegetables, with fruit such as guava or lemon. If your school or health worker gives you an iron–folic acid tablet, take it as they advise. Drink plenty of water.\n\n## Feelings\n\nSome girls feel moody, tired or tearful before or during their period. Rest, keep moving, and talk to someone you trust.\n\n## Tell a parent or doctor if\n\n- Your period lasts more than 7 days.\n- You soak a pad every 1–2 hours.\n- Pain stops you going to school even after a painkiller.\n- You feel dizzy, faint, very tired or breathless.\n- You notice itching, a bad smell or unusual discharge.\n\n## You can still\n\nGo to school, play, study and eat normally. A period is nothing to be ashamed of.","bn":"মাসিক বড় হওয়ার স্বাভাবিক আর সুস্থ একটা অংশ। প্রতি মাসে কীভাবে নিজের যত্ন নেবে, তা জেনে নাও।\n\n## প্রস্তুত থাকো\n\n- স্কুলব্যাগে ছোট একটা থলেতে দুটো প্যাড বা পরিষ্কার কাপড়, একটা বাড়তি অন্তর্বাস আর ব্যবহৃত প্যাড মোড়ানোর জন্য একটা কাগজের ব্যাগ রাখো।\n- ক্যালেন্ডারে বা অ্যাপে মাসিকের তারিখ লিখে রাখো, তাহলে মোটামুটি বুঝবে পরেরটা কবে আসতে পারে। প্রথম দুই-এক বছর মাসিক অনিয়মিত হওয়া খুব সাধারণ।\n\n## পরিচ্ছন্ন থাকা\n\n- প্রতি ৪–৬ ঘণ্টায় প্যাড বদলাও, রক্তপাত বেশি হলে আরও আগে।\n- কাপড় ব্যবহার করলে সাবান আর পরিষ্কার পানিতে ধুয়ে রোদে শুকাও, তারপর পরিষ্কার, শুকনো জায়গায় রাখো। কখনো স্যাঁতসেঁতে কাপড় ব্যবহার করবে না।\n- প্যাড বা কাপড় বদলানোর আগে ও পরে হাত ধোও।\n- স্বাভাবিকভাবে গোসল করো, বাইরের অংশ শুধু পানি দিয়ে ধোও। সেখানে সুগন্ধি সাবান বা পাউডারের দরকার নেই।\n- ব্যবহৃত প্যাড মুড়ে ডাস্টবিনে ফেলো, কমোডে নয়।\n\n## ব্যথা কমাতে\n\n- তলপেটে বা কোমরে গরম পানির ব্যাগ।\n- হালকা হাঁটা বা স্ট্রেচিং।\n- গরম পানীয় আর বিশ্রাম।\n- ব্যথা বেশি হলে প্যারাসিটামলের মতো সাধারণ ব্যথার ওষুধের কথা বাবা-মাকে জিজ্ঞেস করো, আর ডাক্তার বা ফার্মাসিস্টের পরামর্শমতো খাও।\n\n## খাবার ও শক্তি\n\nপ্রতি মাসে শরীর থেকে কিছু আয়রন বেরিয়ে যায়। ডিম, মাছ, মাংস, ডাল আর সবুজ শাক খাও, সাথে পেয়ারা বা লেবুর মতো ফল। স্কুল বা স্বাস্থ্যকর্মী আয়রন–ফলিক অ্যাসিড ট্যাবলেট দিলে তাঁদের পরামর্শমতো খাও। প্রচুর পানি খাও।\n\n## মন\n\nমাসিকের আগে বা সময়ে কারও কারও মেজাজ খারাপ লাগে, ক্লান্ত লাগে বা কান্না পায়। বিশ্রাম নাও, একটু নড়াচড়া করো, আর ভরসার কারও সাথে কথা বলো।\n\n## বাবা-মা বা ডাক্তারকে জানাবে যদি\n\n- মাসিক ৭ দিনের বেশি চলে।\n- প্রতি ১–২ ঘণ্টায় প্যাড ভিজে যায়।\n- ব্যথার ওষুধ খেয়েও ব্যথার জন্য স্কুলে যেতে না পারো।\n- মাথা ঘোরে, অজ্ঞান হওয়ার মতো লাগে, খুব ক্লান্ত লাগে বা শ্বাসকষ্ট হয়।\n- চুলকানি, দুর্গন্ধ বা অস্বাভাবিক স্রাব হয়।\n\n## তুমি সবই পারবে\n\nস্কুলে যাওয়া, খেলা, পড়া, স্বাভাবিক খাওয়া — সব। মাসিকে লজ্জার কিছু নেই।"}'::jsonb, '{}'::jsonb, 3, 4748, 7305, '{}'::text[], 'female', ARRAY['periods', 'menstruation', 'pads', 'period pain', 'self-care', 'iron', 'for teens']::text[], false, 'in_review'::lp_review_status, 8025),
  ('tn-teen-wont-talk', 'scenario', 'general', 'shared', 'routine', 'consensus', '🤐', '{"en":"My teen won''t talk to me","bn":"আমার কিশোর সন্তান আমার সাথে কথা বলে না"}'::jsonb, '{"en":"One-word answers and a closed door are common in the teen years. How to reopen the conversation, and when silence is a warning sign.","bn":"এক শব্দে উত্তর আর বন্ধ দরজা কৈশোরে খুব সাধারণ। আবার কীভাবে কথা শুরু করবেন, আর কখন এই নীরবতা সতর্কসংকেত।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Your teen answers in one word, stays in their room and seems to keep everything to themselves.","bn":"সন্তান এক শব্দে উত্তর দেয়, নিজের ঘরেই থাকে, আর মনে হয় সবকিছু নিজের মধ্যে চেপে রাখছে।"},"why":{"en":"Teens naturally pull back a little to build their own identity. They also go quiet if past talks turned into lectures, criticism or punishment, or if something worrying is going on: bullying, a relationship, a mistake or low mood.","bn":"নিজের পরিচয় গড়তে কিশোর-কিশোরীরা স্বাভাবিকভাবেই একটু সরে যায়। আগের কথাবার্তা উপদেশ, সমালোচনা বা শাস্তিতে গড়ালেও তারা চুপ হয়ে যায় — কিংবা যদি দুশ্চিন্তার কিছু ঘটে: বুলিং, কোনো সম্পর্ক, কোনো ভুল বা মন খারাপ।"},"normal":{"en":"Wanting more privacy and talking more to friends is normal. It is less normal if your teen also stops eating, sleeping or enjoying things, or seems sad or frightened for weeks.","bn":"বেশি একান্ত সময় চাওয়া আর বন্ধুদের সাথে বেশি কথা বলা স্বাভাবিক। কিন্তু সাথে যদি খাওয়া, ঘুম বা আনন্দ কমে যায়, কিংবা কয়েক সপ্তাহ ধরে বিষণ্ন বা ভীত দেখায়, তাহলে তা স্বাভাবিক নয়।"},"do_now":{"en":["Stay calm and don''t force a big talk today","Spend time near them without demands: tea, a drive, a walk","Say once, warmly: “I''m here whenever you want to talk.”"],"bn":["শান্ত থাকুন, আজই বড় আলোচনা চাপিয়ে দেবেন না","কোনো দাবি ছাড়া কাছাকাছি সময় কাটান: চা, গাড়িতে ঘোরা, হাঁটা","একবার, আন্তরিকভাবে বলুন: “যখন ইচ্ছে কথা বলতে চাইলে আমি আছি।”"]},"steps":{"en":["Look for side-by-side moments: in the car or rickshaw, cooking, an evening walk","Ask open questions about their interests, not only studies","Listen far more than you speak, and say back what you heard","Show interest in their music, games or friends","Set a weekly one-to-one time with each parent","Thank them when they share, even small things","If they find one parent easier to talk to, let that parent lead for now"],"bn":["পাশাপাশি থাকার মুহূর্ত খুঁজুন: গাড়ি বা রিকশায়, রান্নার সময়, সন্ধ্যার হাঁটায়","শুধু পড়াশোনা নয়, তার পছন্দের বিষয় নিয়ে খোলা প্রশ্ন করুন","বলার চেয়ে অনেক বেশি শুনুন, আর যা শুনলেন তা ফিরিয়ে বলুন","তার গান, গেম বা বন্ধুদের ব্যাপারে আগ্রহ দেখান","বাবা-মা দুজনেই সপ্তাহে একবার আলাদা করে একান্ত সময় দিন","ছোট কিছু বললেও ধন্যবাদ দিন","কারও সাথে সে সহজে কথা বললে আপাতত তিনিই এগিয়ে থাকুন"]},"avoid":{"en":["Lecturing, comparing or bringing up old mistakes","Secretly reading their phone or diary as a first step","Mocking their feelings or sharing their secrets with relatives","Punishing them for being honest"],"bn":["উপদেশ, তুলনা বা পুরোনো ভুল টেনে আনা","প্রথম পদক্ষেপ হিসেবেই গোপনে ফোন বা ডায়েরি পড়া","অনুভূতি নিয়ে ঠাট্টা, বা তার গোপন কথা আত্মীয়দের বলা","সত্যি বলার জন্য শাস্তি দেওয়া"]},"example":{"en":"Rafiq''s 15-year-old son answered every question with “fine”. Rafiq started driving him to coaching and stopped asking about marks in the car. After two weeks his son began talking about a teacher who had embarrassed him in class. Rafiq just listened and said, “That must have felt bad. Thanks for telling me.”","bn":"রফিকের ১৫ বছরের ছেলে সব প্রশ্নের উত্তরে বলত “ঠিক আছে”। রফিক তাকে কোচিংয়ে পৌঁছে দিতে শুরু করলেন, আর পথে নম্বর নিয়ে প্রশ্ন করা বন্ধ করলেন। দুই সপ্তাহ পর ছেলে নিজেই এক শিক্ষকের কথা বলল, যিনি ক্লাসে তাকে অপমান করেছিলেন। রফিক শুধু শুনলেন, তারপর বললেন, “নিশ্চয়ই খুব খারাপ লেগেছে। আমাকে বলার জন্য ধন্যবাদ।”"},"seek_help":{"en":["Silence lasts for weeks together with low mood, poor sleep or poor appetite","Grades fall sharply or they refuse school","You suspect bullying, abuse or blackmail","Talk to a school counsellor, doctor or psychologist"],"bn":["কয়েক সপ্তাহ ধরে নীরবতার সাথে মন খারাপ, ঘুম বা খিদে কম","রেজাল্ট হঠাৎ অনেক খারাপ, বা স্কুলে যেতে চায় না","বুলিং, নির্যাতন বা ব্ল্যাকমেইলের সন্দেহ","স্কুলের কাউন্সেলর, ডাক্তার বা সাইকোলজিস্টের সাথে কথা বলুন"]},"warning_signs":{"en":["Talk of death, hopelessness or being a burden: stay with them and get help today","Signs of self-harm such as hidden cuts or burns","Sudden fear of a place or a particular person"],"bn":["মৃত্যু, আশাহীনতা বা বোঝা হওয়ার কথা: পাশে থাকুন, আজই সাহায্য নিন","নিজের ক্ষতির লক্ষণ, যেমন লুকানো কাটা বা পোড়া দাগ","হঠাৎ কোনো জায়গা বা নির্দিষ্ট কাউকে ভয় পাওয়া"]}}'::jsonb, 3, 4748, 7305, '{}'::text[], 'any', ARRAY['withdrawn', 'silent', 'communication', 'teen', 'won''t talk']::text[], false, 'in_review'::lp_review_status, 8026),
  ('tn-found-vape-cigarettes', 'scenario', 'scientific', 'shared', 'important', 'consensus', '🚬', '{"en":"I found a vape or cigarettes","bn":"সন্তানের কাছে ভেপ বা সিগারেট পেয়েছি"}'::jsonb, '{"en":"Finding a vape or cigarettes is a moment to act calmly and clearly, not to explode. How to talk, set limits and help your teen say no.","bn":"ভেপ বা সিগারেট পাওয়ার পর রেগে ফেটে পড়া নয়, শান্তভাবে পরিষ্কার ব্যবস্থা নেওয়ার সময়। কীভাবে কথা বলবেন, সীমা ঠিক করবেন, আর সন্তানকে “না” বলতে সাহায্য করবেন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"You found a vape, cigarettes or a lighter in your teen''s bag, room or pocket.","bn":"সন্তানের ব্যাগ, ঘর বা পকেটে ভেপ, সিগারেট বা লাইটার পেয়েছেন।"},"why":{"en":"Teens try smoking or vaping out of curiosity, to fit in, to cope with stress, or because vapes are marketed as harmless. Nicotine is highly addictive for a developing brain.","bn":"কৌতূহল, দলে মিশে যাওয়ার ইচ্ছা, চাপ সামলানো, বা ভেপকে নিরীহ বলে প্রচারের কারণে কিশোর-কিশোরীরা ধূমপান বা ভেপ চেখে দেখে। বেড়ে ওঠা মস্তিষ্কের জন্য নিকোটিন প্রচণ্ড আসক্তিকর।"},"normal":{"en":"Many teens are offered tobacco or vapes, and trying once does not mean addiction. But it is a moment to act, calmly and clearly.","bn":"অনেক কিশোর-কিশোরীকেই তামাক বা ভেপ সাধা হয়, আর একবার চেখে দেখা মানেই আসক্তি নয়। তবে এটা শান্তভাবে, পরিষ্কারভাবে ব্যবস্থা নেওয়ার সময়।"},"do_now":{"en":["Take a breath and wait until you are calm before talking","Talk in private, not in front of siblings or relatives","Start with a question: “I found this. Can you tell me about it?”"],"bn":["গভীর শ্বাস নিন, শান্ত হওয়ার পর কথা বলুন","ভাইবোন বা আত্মীয়দের সামনে নয়, একান্তে কথা বলুন","প্রশ্ন দিয়ে শুরু করুন: “এটা পেলাম। আমাকে একটু বলবে?”"]},"steps":{"en":["Listen to their side: whose is it, how often, and why","Share clear facts: nicotine addiction, harm to lungs and heart, and that vapes are not safe","Explain your family rule and the reason for it","Agree a consequence linked to the rule, such as less unsupervised time for a while","Help them plan how to say no to friends","If they want to stop but find it hard, see a doctor together for support","If you smoke, consider quitting together; your example matters"],"bn":["তার কথা শুনুন: কার জিনিস, কত ঘন ঘন, কেন","পরিষ্কার তথ্য দিন: নিকোটিনের আসক্তি, ফুসফুস ও হৃৎপিণ্ডের ক্ষতি, আর ভেপও নিরাপদ নয়","পরিবারের নিয়ম আর তার কারণ বুঝিয়ে বলুন","নিয়মের সাথে মিল রেখে পরিণাম ঠিক করুন, যেমন কিছুদিন একা বাইরে থাকার সময় কমানো","বন্ধুদের কীভাবে “না” বলবে, তা একসাথে ঠিক করুন","ছাড়তে চাইলেও কষ্ট হলে একসাথে ডাক্তারের সাহায্য নিন","আপনি ধূমপান করলে একসাথে ছাড়ার কথা ভাবুন; আপনার উদাহরণ গুরুত্বপূর্ণ"]},"avoid":{"en":["Beating, shaming or name-calling","Threats you will not carry out","Telling the whole family","Ignoring it and hoping it stops"],"bn":["মারধর, লজ্জা দেওয়া বা গালাগাল","এমন হুমকি, যা আপনি করবেন না","পুরো পরিবারকে জানিয়ে দেওয়া","এড়িয়ে গিয়ে আশা করা যে নিজেই থেমে যাবে"]},"example":{"en":"Nusrat found a vape in her 14-year-old daughter''s school bag. She waited until evening and said, “I found this and I''m worried, not angry. Help me understand.” Her daughter said a friend had given it to her. They agreed she would give it back, and practised what to say next time.","bn":"নুসরাত তাঁর ১৪ বছরের মেয়ের স্কুলব্যাগে একটা ভেপ পেলেন। সন্ধ্যা পর্যন্ত অপেক্ষা করে বললেন, “এটা পেয়েছি। আমি রাগ করিনি, চিন্তিত। আমাকে একটু বুঝিয়ে বলো।” মেয়ে জানাল, এক বন্ধু দিয়েছে। ঠিক হলো সে ওটা ফেরত দেবে, আর পরের বার কী বলবে তা দুজনে মিলে অনুশীলন করল।"},"seek_help":{"en":["They smoke or vape every day and cannot stop","You find signs of other drugs: pills, foil, powder or yaba tablets","Mood, sleep or school performance changes sharply","See a doctor or psychiatrist"],"bn":["প্রতিদিন ধূমপান বা ভেপ করে, থামতে পারছে না","অন্য মাদকের চিহ্ন পেয়েছেন: ট্যাবলেট, ফয়েল, পাউডার বা ইয়াবা","মেজাজ, ঘুম বা পড়াশোনায় হঠাৎ বড় পরিবর্তন","ডাক্তার বা মনোরোগ বিশেষজ্ঞ দেখান"]},"warning_signs":{"en":["Chest pain, trouble breathing or fainting after vaping or drug use: go to hospital now","Very agitated, confused or paranoid behaviour: call 999"],"bn":["ভেপ বা মাদক নেওয়ার পর বুকে ব্যথা, শ্বাসকষ্ট বা অজ্ঞান হওয়া: এখনই হাসপাতালে যান","খুব অস্থির, বিভ্রান্ত বা সন্দেহবাতিক আচরণ: ৯৯৯-এ ফোন করুন"]}}'::jsonb, 3, 4748, 7305, '{}'::text[], 'any', ARRAY['vape', 'cigarettes', 'smoking', 'nicotine', 'found', 'drugs']::text[], false, 'in_review'::lp_review_status, 8027),
  ('tn-failed-exam', 'scenario', 'general', 'shared', 'important', 'consensus', '📉', '{"en":"My teen failed an exam","bn":"সন্তান পরীক্ষায় ফেল করেছে"}'::jsonb, '{"en":"A bad result hurts, but one exam does not decide a life. How to support your teen first, then find out what went wrong and plan the next step.","bn":"খারাপ ফল কষ্ট দেয়, কিন্তু একটা পরীক্ষা জীবন ঠিক করে না। আগে সন্তানের পাশে দাঁড়ান, তারপর কোথায় ভুল হলো খুঁজে পরের ধাপ ঠিক করুন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Your teen failed an exam, or got much lower marks or a lower GPA than hoped.","bn":"সন্তান পরীক্ষায় ফেল করেছে, বা আশার চেয়ে অনেক কম নম্বর বা জিপিএ পেয়েছে।"},"why":{"en":"Many things can lie behind a poor result: weak foundations in a subject, poor sleep, stress, illness, a learning or eyesight difficulty, long coaching hours without real understanding, or problems at home or with friends.","bn":"খারাপ ফলের পেছনে অনেক কারণ থাকতে পারে: কোনো বিষয়ে ভিত দুর্বল, ঘুম কম, মানসিক চাপ, অসুস্থতা, শেখা বা চোখের সমস্যা, না বুঝে লম্বা সময় কোচিং, কিংবা বাসায় বা বন্ধুদের সাথে সমস্যা।"},"normal":{"en":"Disappointment, tears, anger or shame for a few days are normal. Most teens recover with support.","bn":"কয়েক দিন হতাশা, কান্না, রাগ বা লজ্জা স্বাভাবিক। পাশে থাকলে বেশিরভাগ কিশোর-কিশোরী সামলে ওঠে।"},"do_now":{"en":["Stay calm; sit with them or give a hug","Say: “We love you. We''ll work this out together.”","Keep a closer eye for the first few days, especially if they seem very low"],"bn":["শান্ত থাকুন; পাশে বসুন বা জড়িয়ে ধরুন","বলুন: “আমরা তোমাকে ভালোবাসি। একসাথে এর সমাধান করব।”","প্রথম কয়েক দিন একটু বেশি খেয়াল রাখুন, বিশেষ করে খুব ভেঙে পড়লে"]},"steps":{"en":["Allow a day or two before making plans","Look at the results together: which subjects, and why","Ask the teacher''s view, and check for learning or eyesight problems","Decide next steps: a result review if a mark looks wrong, sitting again, extra help, or a different path","Make a realistic study plan that protects sleep and breaks","Praise effort and small improvements","Protect them from relatives'' and neighbours'' comments"],"bn":["পরিকল্পনার আগে এক-দুই দিন সময় দিন","একসাথে ফল দেখুন: কোন কোন বিষয়, আর কেন","শিক্ষকের মতামত নিন, শেখা বা চোখের সমস্যা আছে কিনা দেখান","পরের ধাপ ঠিক করুন: নম্বরে ভুল মনে হলে ফল পুনর্নিরীক্ষণ, আবার পরীক্ষা, বাড়তি সাহায্য, বা অন্য পথ","ঘুম আর বিরতি রেখে বাস্তবসম্মত পড়ার পরিকল্পনা করুন","চেষ্টা আর ছোট উন্নতির প্রশংসা করুন","আত্মীয়-প্রতিবেশীর মন্তব্য থেকে তাকে আড়াল করুন"]},"avoid":{"en":["Shouting, beating or calling them a failure","Comparing with siblings or cousins","Taking away all fun and friends as punishment","Discussing the result in front of guests"],"bn":["চিৎকার, মারধর, বা “ব্যর্থ” বলা","ভাইবোন বা কাজিনের সাথে তুলনা","শাস্তি হিসেবে সব আনন্দ আর বন্ধু বন্ধ করে দেওয়া","অতিথিদের সামনে ফল নিয়ে আলোচনা"]},"example":{"en":"When Tania failed maths in her test exam, her father found her crying. He said, “This is hard, but it''s not the end. Let''s find out where it went wrong.” They discovered she had missed basic chapters from class 8, and arranged weekly help with a teacher.","bn":"টেস্ট পরীক্ষায় গণিতে ফেল করার পর তানিয়ার বাবা তাকে কাঁদতে দেখলেন। বললেন, “কষ্ট হচ্ছে বুঝি, কিন্তু এটা শেষ না। চলো দেখি কোথায় সমস্যা হলো।” দেখা গেল অষ্টম শ্রেণির কিছু মৌলিক অধ্যায় তার বোঝা হয়নি। তাঁরা একজন শিক্ষকের কাছে সপ্তাহে একদিন সাহায্যের ব্যবস্থা করলেন।"},"seek_help":{"en":["Sadness, crying or withdrawal lasting more than two weeks","Repeated failure despite real effort: ask about a learning assessment","Talk to a school counsellor, doctor or psychologist"],"bn":["দুই সপ্তাহের বেশি মন খারাপ, কান্না বা গুটিয়ে থাকা","সত্যিকারের চেষ্টার পরও বারবার ফেল: শেখার সমস্যা আছে কিনা পরীক্ষা করান","স্কুলের কাউন্সেলর, ডাক্তার বা সাইকোলজিস্টের সাথে কথা বলুন"]},"warning_signs":{"en":["Saying life is over, they are worthless, or they would rather die","Giving away belongings or saying goodbye","Any self-harm: stay with them and call 999 or go to hospital"],"bn":["জীবন শেষ, সে মূল্যহীন, বা মরে যাওয়াই ভালো — এমন কথা বলা","জিনিসপত্র দিয়ে দেওয়া বা বিদায় নেওয়ার মতো কথা","নিজের যেকোনো ক্ষতি: পাশে থাকুন, ৯৯৯-এ ফোন করুন বা হাসপাতালে যান"]}}'::jsonb, 3, 4748, 7305, '{}'::text[], 'any', ARRAY['failed exam', 'results', 'gpa', 'ssc', 'hsc', 'disappointment']::text[], false, 'in_review'::lp_review_status, 8028),
  ('tn-wants-to-stay-out-late', 'scenario', 'general', 'shared', 'routine', 'consensus', '🌃', '{"en":"My teen wants to stay out late","bn":"সন্তান রাত করে বাইরে থাকতে চায়"}'::jsonb, '{"en":"Saying yes to everything risks safety; saying no to everything leads to secret outings. How to agree a time, a check-in and a safe way home.","bn":"সবকিছুতে হ্যাঁ বললে নিরাপত্তা ঝুঁকিতে পড়ে; সবকিছুতে না বললে শুরু হয় লুকিয়ে বের হওয়া। কীভাবে সময়, খোঁজ দেওয়ার নিয়ম আর নিরাপদে ফেরার ব্যবস্থা ঠিক করবেন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Your teen wants to stay out later with friends: a party, a match, late tuition or just hanging out.","bn":"সন্তান বন্ধুদের সাথে রাত করে বাইরে থাকতে চায়: কোনো অনুষ্ঠান, খেলা, দেরির টিউশন, বা শুধু আড্ডা।"},"why":{"en":"Teens want independence and time with friends. Saying yes to everything risks their safety; saying no to everything often leads to secret outings and lies.","bn":"কিশোর-কিশোরীরা স্বাধীনতা আর বন্ধুদের সাথে সময় চায়। সবকিছুতে হ্যাঁ বললে নিরাপত্তার ঝুঁকি; সবকিছুতে না বললে প্রায়ই লুকিয়ে বের হওয়া আর মিথ্যা বলা শুরু হয়।"},"normal":{"en":"Asking for more freedom is a normal part of growing up, and so is arguing about it.","bn":"আরও স্বাধীনতা চাওয়া বড় হওয়ার স্বাভাবিক অংশ, এ নিয়ে তর্ক করাও।"},"do_now":{"en":["Listen to the whole request before answering","Ask: where, with whom, how will you get there and back, and until what time?","Say you need time to think if you do"],"bn":["উত্তর দেওয়ার আগে পুরো কথাটা শুনুন","জিজ্ঞেস করুন: কোথায়, কার সাথে, কীভাবে যাবে-আসবে, কয়টা পর্যন্ত?","ভাবার সময় লাগলে সেটাই বলুন"]},"steps":{"en":["Agree a time based on age, transport and safety, not on what others are allowed","Know which adults are in charge, and keep a friend''s contact number","Agree a check-in call or message","Offer a pick-up, and a no-questions pick-up if they ever feel unsafe","Agree a fair consequence for coming back late without calling","Give more freedom as they show responsibility","Make sure both parents agree before answering"],"bn":["অন্যরা কী অনুমতি পায় তা নয়, বয়স, যানবাহন আর নিরাপত্তা দেখে সময় ঠিক করুন","সেখানে কোন বড়রা দায়িত্বে আছেন জানুন, একজন বন্ধুর ফোন নম্বর রাখুন","মাঝে একবার ফোন বা মেসেজে খোঁজ দেওয়ার নিয়ম করুন","নিয়ে আসার প্রস্তাব দিন — আর কখনো অনিরাপদ লাগলে কোনো প্রশ্ন ছাড়াই নিয়ে আসার প্রতিশ্রুতি","না জানিয়ে দেরি করলে কী হবে, তা ন্যায্যভাবে আগেই ঠিক করুন","দায়িত্বশীলতা দেখালে স্বাধীনতা বাড়ান","উত্তর দেওয়ার আগে বাবা-মা দুজনে একমত হন"]},"avoid":{"en":["Saying no without explaining why","Giving different answers from each parent","Different rules for sons and daughters without a clear safety reason","Harsh punishment that teaches them to hide plans next time"],"bn":["কারণ না বলে “না” বলা","বাবা আর মায়ের আলাদা আলাদা উত্তর","স্পষ্ট নিরাপত্তার কারণ ছাড়া ছেলে আর মেয়ের জন্য ভিন্ন নিয়ম","এমন কড়া শাস্তি, যাতে পরের বার সে প্ল্যান লুকোতে শেখে"]},"example":{"en":"Arif, 16, wanted to watch a late cricket match at a friend''s house. His mother asked who would be there and how he would get home. They agreed he would be back by 11 pm, his father would pick him up, and he would message at 9. He did, and next time they gave him a little more freedom.","bn":"১৬ বছরের আরিফ এক বন্ধুর বাসায় রাতের ক্রিকেট ম্যাচ দেখতে চাইল। মা জিজ্ঞেস করলেন কে কে থাকবে, কীভাবে ফিরবে। ঠিক হলো রাত ১১টার মধ্যে ফিরবে, বাবা গিয়ে নিয়ে আসবেন, আর ৯টায় একটা মেসেজ দেবে। আরিফ কথা রাখল, তাই পরের বার তাকে আরেকটু বেশি স্বাধীনতা দেওয়া হলো।"},"seek_help":{"en":["They often lie about where they are, or stay out all night","You suspect drugs, gangs, betting or a risky relationship","Conflict at home is constant: a counsellor can help","If your teen is missing or in danger, call 999"],"bn":["প্রায়ই কোথায় আছে তা নিয়ে মিথ্যা বলে, বা সারারাত বাইরে থাকে","মাদক, গ্যাং, বাজি বা ঝুঁকিপূর্ণ সম্পর্কের সন্দেহ","ঘরে ঝগড়া লেগেই থাকে: কাউন্সেলর সাহায্য করতে পারেন","সন্তানের খোঁজ না পেলে বা বিপদে থাকলে ৯৯৯-এ ফোন করুন"]}}'::jsonb, 3, 4748, 7305, '{}'::text[], 'any', ARRAY['curfew', 'staying out late', 'independence', 'friends', 'rules']::text[], false, 'in_review'::lp_review_status, 8029),
  ('tn-has-boyfriend-girlfriend', 'scenario', 'general', 'shared', 'important', 'consensus', '💌', '{"en":"My teen has a boyfriend or girlfriend","bn":"সন্তানের প্রেমের সম্পর্ক আছে"}'::jsonb, '{"en":"How you react decides whether your teen stays safe and keeps talking to you. Stay calm, share your values, and focus on safety and respect.","bn":"আপনার প্রতিক্রিয়াই ঠিক করবে সন্তান নিরাপদ থাকবে কিনা, আর আপনার সাথে কথা বলবে কিনা। শান্ত থাকুন, মূল্যবোধ জানান, আর নিরাপত্তা ও সম্মানের দিকে মন দিন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"You found out, or your teen told you, that they have a boyfriend or girlfriend.","bn":"আপনি জানতে পেরেছেন, বা সন্তান নিজেই বলেছে, তার একজন প্রেমিক বা প্রেমিকা আছে।"},"why":{"en":"Romantic feelings are a normal part of puberty. Families hold different values about relationships before marriage, often shaped by faith. How you respond affects whether your teen stays safe and keeps talking to you.","bn":"বয়ঃসন্ধিতে প্রেমের অনুভূতি স্বাভাবিক। বিয়ের আগের সম্পর্ক নিয়ে পরিবারভেদে মূল্যবোধ আলাদা, অনেক সময় তা ধর্মবিশ্বাস থেকে আসে। আপনার প্রতিক্রিয়া ঠিক করবে সন্তান নিরাপদ থাকবে কিনা আর আপনার সাথে কথা বলা চালিয়ে যাবে কিনা।"},"normal":{"en":"Crushes and attraction are normal at this age. What matters most is safety, respect, and the values your family holds.","bn":"এই বয়সে কাউকে ভালো লাগা বা আকর্ষণ বোধ করা স্বাভাবিক। সবচেয়ে জরুরি হলো নিরাপত্তা, সম্মান আর আপনার পরিবারের মূল্যবোধ।"},"do_now":{"en":["Stay calm and don''t react in anger","Thank them if they told you themselves","Calmly find out who the other person is and how old they are"],"bn":["শান্ত থাকুন, রাগের মাথায় কিছু করবেন না","সে নিজে বলে থাকলে ধন্যবাদ দিন","শান্তভাবে জেনে নিন অন্যজন কে, আর তার বয়স কত"]},"steps":{"en":["Listen first: how they met, and what they like about the person","Share your family''s and faith''s values clearly, and explain why","Talk about consent and respect, and that no one should pressure them","Explain the dangers of sharing photos, passwords or location","Agree clear rules, for example no secret meetings and meeting only in public or family settings","Keep studies, sleep and family time on track","For religious questions, talk together with a trusted, knowledgeable scholar"],"bn":["আগে শুনুন: কীভাবে পরিচয়, মানুষটার কী ভালো লাগে","পরিবার আর ধর্মের মূল্যবোধ পরিষ্কার করে জানান, কেন মানেন তা-ও বলুন","সম্মতি আর সম্মান নিয়ে কথা বলুন — কেউ যেন তাকে চাপ না দেয়","ছবি, পাসওয়ার্ড বা লোকেশন শেয়ার করার বিপদ বুঝিয়ে বলুন","পরিষ্কার নিয়ম ঠিক করুন, যেমন গোপনে দেখা নয়, দেখা হলে শুধু প্রকাশ্য জায়গায় বা পরিবারের সামনে","পড়াশোনা, ঘুম আর পরিবারের সময় যেন ঠিক থাকে","ধর্মীয় প্রশ্নে দুজনে মিলে ভরসার, জ্ঞানী কোনো আলেমের সাথে কথা বলুন"]},"avoid":{"en":["Beating, locking them up or taking them out of school","Arranging a quick marriage to ''solve'' it: child marriage is illegal and harmful","Public shaming or telling the whole family","Spying on every message as the first step"],"bn":["মারধর, ঘরে আটকে রাখা বা স্কুল ছাড়িয়ে দেওয়া","“সমাধান” হিসেবে তাড়াতাড়ি বিয়ে দেওয়া: বাল্যবিয়ে বেআইনি ও ক্ষতিকর","সবার সামনে লজ্জা দেওয়া বা পুরো পরিবারকে জানানো","প্রথম পদক্ষেপ হিসেবেই প্রতিটি মেসেজে নজরদারি"]},"example":{"en":"Mitu''s mother found messages from a classmate on her phone. Instead of shouting, she said, “I saw these. I''m not here to shame you. Let''s talk about what our family believes and how to keep you safe.” They talked about limits, and Mitu promised to tell her if anyone ever pressured her.","bn":"মিতুর মা তার ফোনে এক সহপাঠীর মেসেজ দেখলেন। চিৎকার না করে বললেন, “এগুলো দেখেছি। তোমাকে লজ্জা দিতে আসিনি। চলো কথা বলি — আমাদের পরিবার কী বিশ্বাস করে, আর তুমি কীভাবে নিরাপদ থাকবে।” তাঁরা সীমা নিয়ে কথা বললেন, আর মিতু কথা দিল কেউ কখনো চাপ দিলে মাকে জানাবে।"},"seek_help":{"en":["The other person is much older, or an adult","There is pressure, threats, blackmail or violence: contact the police on 999","Your teen seems frightened or withdrawn, or is harming themselves","A counsellor can support your teen and your family"],"bn":["অন্যজন অনেক বড়, বা প্রাপ্তবয়স্ক","চাপ, হুমকি, ব্ল্যাকমেইল বা সহিংসতা: ৯৯৯-এ পুলিশে যোগাযোগ করুন","সন্তান ভীত বা গুটিয়ে আছে, বা নিজের ক্ষতি করছে","কাউন্সেলর সন্তান ও পরিবার — দুজনকেই সহায়তা দিতে পারেন"]}}'::jsonb, 3, 4748, 7305, '{}'::text[], 'any', ARRAY['boyfriend', 'girlfriend', 'relationship', 'romance', 'values', 'consent', 'safety']::text[], false, 'in_review'::lp_review_status, 8030),
  ('tn-harassed-online', 'scenario', 'general', 'shared', 'important', 'consensus', '💬', '{"en":"My teen is being harassed online","bn":"সন্তান অনলাইনে হয়রানির শিকার"}'::jsonb, '{"en":"Insults, threats, fake profiles or shared photos follow a teen everywhere. Save evidence, block and report, never pay a blackmailer, and involve the school or police when needed.","bn":"অপমান, হুমকি, ভুয়া প্রোফাইল বা ছড়ানো ছবি — এগুলো সন্তানের পিছু ছাড়ে না। প্রমাণ রাখুন, ব্লক ও রিপোর্ট করুন, ব্ল্যাকমেইলারকে কখনো টাকা দেবেন না, আর দরকারে স্কুল বা পুলিশকে জানান।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Your teen is getting insulting, threatening or sexual messages, someone has made a fake profile of them, or their photos are being shared.","bn":"সন্তান অপমানজনক, হুমকিমূলক বা যৌন মেসেজ পাচ্ছে, কেউ তার নামে ভুয়া প্রোফাইল খুলেছে, বা তার ছবি ছড়ানো হচ্ছে।"},"why":{"en":"Online harassment can come from classmates, strangers or former friends. Anonymous accounts make people crueller, and the harassment follows teens home, so it can feel impossible to escape.","bn":"অনলাইন হয়রানি আসতে পারে সহপাঠী, অপরিচিত বা পুরোনো বন্ধুর কাছ থেকে। নাম-পরিচয় লুকানো যায় বলে মানুষ বেশি নিষ্ঠুর হয়, আর হয়রানি ঘরে পর্যন্ত পিছু নেয় — মনে হয় পালানোর কোনো পথ নেই।"},"normal":{"en":"Your teen may feel ashamed, scared or angry, and may have hidden it for fear of losing their phone. Telling you is a brave step.","bn":"সন্তান লজ্জা, ভয় বা রাগ অনুভব করতে পারে, আর ফোন হারানোর ভয়ে হয়তো লুকিয়ে রেখেছিল। আপনাকে বলাটা সাহসের কাজ।"},"do_now":{"en":["Thank them for telling you and make clear it is not their fault","Do not take their phone away as a punishment","Save evidence: screenshots, usernames, links and dates"],"bn":["বলার জন্য ধন্যবাদ দিন, পরিষ্কার করে বলুন এটা তার দোষ নয়","শাস্তি হিসেবে ফোন কেড়ে নেবেন না","প্রমাণ রাখুন: স্ক্রিনশট, ইউজারনেম, লিংক আর তারিখ"]},"steps":{"en":["Don''t reply to the harasser or hit back","Block and report the account on the platform after saving evidence","Tighten privacy settings and change passwords","If classmates are involved, talk to the school","If there are threats, sexual images or blackmail, report to the police: call 999 or go to the local police station","Never pay a blackmailer","Check in every day on how they are feeling"],"bn":["হয়রানিকারীকে উত্তর বা পাল্টা আক্রমণ নয়","প্রমাণ রাখার পর প্ল্যাটফর্মে অ্যাকাউন্টটা ব্লক ও রিপোর্ট করুন","প্রাইভেসি সেটিং শক্ত করুন, পাসওয়ার্ড বদলান","সহপাঠীরা জড়িত থাকলে স্কুলের সাথে কথা বলুন","হুমকি, যৌন ছবি বা ব্ল্যাকমেইল থাকলে পুলিশে জানান: ৯৯৯-এ ফোন করুন বা নিকটস্থ থানায় যান","ব্ল্যাকমেইলারকে কখনো টাকা দেবেন না","প্রতিদিন খোঁজ নিন সে কেমন বোধ করছে"]},"avoid":{"en":["Blaming them for posting photos or chatting","Angrily confronting the bully''s family","Deleting everything before saving evidence","Paying or bargaining with a blackmailer"],"bn":["ছবি পোস্ট বা চ্যাট করার জন্য তাকে দোষ দেওয়া","রেগে গিয়ে হয়রানিকারীর পরিবারের সাথে ঝামেলা","প্রমাণ রাখার আগেই সব মুছে ফেলা","ব্ল্যাকমেইলারকে টাকা দেওয়া বা দর-কষাকষি"]},"example":{"en":"Sabbir, 15, received threats from a fake account demanding money for an edited photo. He told his father, who said, “You did the right thing telling me.” They saved screenshots, blocked the account and went to the police station together. They did not pay.","bn":"১৫ বছরের সাব্বিরকে একটা ভুয়া অ্যাকাউন্ট থেকে এডিট করা ছবি দেখিয়ে টাকা চেয়ে হুমকি দেওয়া হচ্ছিল। সে বাবাকে জানাল। বাবা বললেন, “আমাকে বলে ঠিক কাজ করেছ।” তাঁরা স্ক্রিনশট রাখলেন, অ্যাকাউন্টটা ব্লক করলেন, আর একসাথে থানায় গেলেন। কোনো টাকা দেননি।"},"seek_help":{"en":["Harassment continues despite blocking and reporting","There are threats, blackmail or sexual images: go to the police","Your teen seems low or anxious, or avoids school: see a counsellor"],"bn":["ব্লক ও রিপোর্টের পরও হয়রানি চলছে","হুমকি, ব্ল্যাকমেইল বা যৌন ছবি: পুলিশে যান","সন্তান মনমরা বা উদ্বিগ্ন, বা স্কুল এড়িয়ে চলছে: কাউন্সেলর দেখান"]},"warning_signs":{"en":["Talk of self-harm or suicide: stay with them, call 999 or go to hospital","Not eating or sleeping, or refusing to leave the house"],"bn":["নিজের ক্ষতি বা আত্মহত্যার কথা: পাশে থাকুন, ৯৯৯-এ ফোন করুন বা হাসপাতালে যান","খাওয়া-ঘুম বন্ধ, বা ঘর থেকে বের হতে না চাওয়া"]}}'::jsonb, 3, 4748, 7305, '{}'::text[], 'any', ARRAY['cyberbullying', 'harassment', 'online', 'blackmail', 'fake profile', 'police']::text[], false, 'in_review'::lp_review_status, 8031),
  ('tn-self-harm-cutting', 'scenario', 'scientific', 'shared', 'important', 'guideline', '🩹', '{"en":"My teen cuts or hurts themself (urgent)","bn":"সন্তান নিজের শরীর কাটে বা আঘাত করে (জরুরি)"}'::jsonb, '{"en":"Self-harm is a sign of serious distress and always needs help. Stay with your teen, remove dangerous items, and get medical or emergency care now.","bn":"নিজের ক্ষতি করা গুরুতর মানসিক কষ্টের লক্ষণ, আর এতে সবসময় সাহায্য দরকার। সন্তানের পাশে থাকুন, বিপজ্জনক জিনিস সরান, এখনই চিকিৎসা বা জরুরি সেবা নিন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"You found cuts, burns or other injuries your teen made on themselves, or they told you they hurt themselves.","bn":"সন্তানের শরীরে নিজের করা কাটা, পোড়া বা অন্য আঘাত দেখেছেন, বা সে নিজেই বলেছে যে নিজেকে আঘাত করে।"},"why":{"en":"Self-harm is usually a way to cope with overwhelming feelings such as sadness, anger, shame or numbness, not attention-seeking. It can be linked to depression, anxiety, bullying, abuse, blackmail or pressure. It raises the risk of suicide, so it always needs help.","bn":"নিজের ক্ষতি করা সাধারণত মনোযোগ পাওয়ার জন্য নয়; দুঃখ, রাগ, লজ্জা বা অনুভূতিহীনতার মতো অসহ্য অনুভূতি সামলানোর একটা উপায়। এর সাথে বিষণ্নতা, উদ্বেগ, বুলিং, নির্যাতন, ব্ল্যাকমেইল বা চাপের সম্পর্ক থাকতে পারে। এতে আত্মহত্যার ঝুঁকি বাড়ে, তাই সবসময় সাহায্য দরকার।"},"normal":{"en":"This is not a phase to ignore. It is also nothing to be ashamed of: many teens recover fully with support and treatment.","bn":"এটা এড়িয়ে যাওয়ার মতো কোনো সাময়িক ব্যাপার নয়। আবার লজ্জারও কিছু নয়: সহায়তা আর চিকিৎসায় অনেক কিশোর-কিশোরী পুরোপুরি সেরে ওঠে।"},"do_now":{"en":["If a wound is deep or bleeding heavily, or they have taken pills or poison, call 999 or go to hospital now","Stay with them and stay calm","Ask gently but directly whether they are thinking of ending their life","Remove or lock away blades, medicines, pesticides and poisons"],"bn":["ক্ষত গভীর হলে বা রক্ত না থামলে, কিংবা ওষুধ বা বিষ খেয়ে থাকলে এখনই ৯৯৯-এ ফোন করুন বা হাসপাতালে যান","তার পাশে থাকুন, শান্ত থাকুন","নরম কিন্তু সরাসরি জিজ্ঞেস করুন সে জীবন শেষ করার কথা ভাবছে কিনা","ব্লেড, ওষুধ, কীটনাশক আর বিষ সরিয়ে ফেলুন বা তালাবন্ধ করুন"]},"steps":{"en":["Clean and cover small wounds; see a doctor for deep or infected ones","Say: “Thank you for telling me. I love you and we''ll get help together.”","See a doctor, psychiatrist or psychologist the same day or as soon as possible","Check in daily without constant questioning","Make a safety plan with them and their doctor: triggers, who to call, what to do","Find and deal with the causes: bullying, abuse, blackmail, exam pressure","Get support for yourself too"],"bn":["ছোট ক্ষত পরিষ্কার করে ঢেকে দিন; গভীর বা পেকে যাওয়া ক্ষত ডাক্তারকে দেখান","বলুন: “আমাকে বলার জন্য ধন্যবাদ। তোমাকে ভালোবাসি, আমরা একসাথে সাহায্য নেব।”","সেদিনই বা যত দ্রুত সম্ভব ডাক্তার, মনোরোগ বিশেষজ্ঞ বা সাইকোলজিস্ট দেখান","সারাক্ষণ প্রশ্ন না করে প্রতিদিন খোঁজ নিন","তার ও ডাক্তারের সাথে মিলে একটা নিরাপত্তা পরিকল্পনা করুন: কিসে কষ্ট বাড়ে, কাকে ফোন করবে, কী করবে","কারণ খুঁজে সমাধান করুন: বুলিং, নির্যাতন, ব্ল্যাকমেইল, পরীক্ষার চাপ","নিজের জন্যও সহায়তা নিন"]},"avoid":{"en":["Shouting, beating or shaming","Saying “You''re doing it for attention”","Promising to keep it secret from the other parent or doctors","Leaving them alone if they talk about suicide"],"bn":["চিৎকার, মারধর বা লজ্জা দেওয়া","“মনোযোগ পাওয়ার জন্য করছ” বলা","অন্য অভিভাবক বা ডাক্তারের কাছে গোপন রাখার প্রতিশ্রুতি","আত্মহত্যার কথা বললে তাকে একা রাখা"]},"example":{"en":"Farzana noticed her daughter always wore long sleeves, even in the heat. One evening she saw cuts on her arm. She sat beside her and said, “I''m not angry. I can see you''re in a lot of pain. Can you tell me about it?” The next day they saw a psychiatrist at the medical college hospital together.","bn":"ফারজানা খেয়াল করলেন, গরমেও মেয়ে সবসময় লম্বা হাতার জামা পরে। এক সন্ধ্যায় তার হাতে কাটা দাগ দেখলেন। পাশে বসে বললেন, “আমি রাগ করিনি। বুঝতে পারছি তুমি অনেক কষ্টে আছ। আমাকে একটু বলবে?” পরদিন দুজনে মিলে মেডিকেল কলেজ হাসপাতালের মনোরোগ বিশেষজ্ঞের কাছে গেলেন।"},"seek_help":{"en":["Any self-harm needs a doctor or mental health professional soon","Psychiatry departments of medical college hospitals, or the National Institute of Mental Health in Dhaka","Go back to the doctor if things get worse"],"bn":["নিজের যেকোনো ক্ষতিতেই দ্রুত ডাক্তার বা মানসিক স্বাস্থ্য বিশেষজ্ঞ দেখানো দরকার","মেডিকেল কলেজ হাসপাতালের মনোরোগ বিভাগ, বা ঢাকার জাতীয় মানসিক স্বাস্থ্য ইনস্টিটিউট","অবস্থা খারাপ হলে আবার ডাক্তারের কাছে যান"]},"warning_signs":{"en":["Talking about wanting to die, or having a plan","Has taken an overdose, pills or poison, even if they seem fine","Deep wounds or bleeding that won''t stop","Saying goodbye or giving things away","In any of these, call 999 or go to hospital now"],"bn":["মরে যেতে চাওয়ার কথা বলা, বা কোনো পরিকল্পনা থাকা","বেশি ওষুধ, ট্যাবলেট বা বিষ খেয়েছে — ঠিক আছে মনে হলেও","গভীর ক্ষত বা না থামা রক্তপাত","বিদায় নেওয়ার মতো কথা বা জিনিস দিয়ে দেওয়া","এর যেকোনোটি হলে এখনই ৯৯৯-এ ফোন করুন বা হাসপাতালে যান"]}}'::jsonb, 4, 4748, 7305, '{}'::text[], 'any', ARRAY['self-harm', 'cutting', 'suicide', 'urgent', 'mental health', '999']::text[], false, 'in_review'::lp_review_status, 8032),
  ('tn-very-angry-slams-doors', 'scenario', 'general', 'shared', 'routine', 'consensus', '🚪', '{"en":"My teen slams doors and gets very angry","bn":"সন্তান দরজা ধাক্কা দেয়, খুব রেগে যায়"}'::jsonb, '{"en":"Outbursts are common in the teen years, but violence is not acceptable. How to stay calm, set limits, teach calming skills and look for what lies underneath.","bn":"কৈশোরে রাগের বিস্ফোরণ সাধারণ, কিন্তু সহিংসতা মেনে নেওয়া যায় না। কীভাবে শান্ত থাকবেন, সীমা ঠিক করবেন, শান্ত হওয়ার কৌশল শেখাবেন, আর ভেতরের কারণ খুঁজবেন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Your teen shouts, slams doors, throws things or explodes over small issues.","bn":"সন্তান ছোট ব্যাপারে চিৎকার করে, দরজা ধাক্কা দেয়, জিনিস ছোড়ে বা ফেটে পড়ে।"},"why":{"en":"Hormones, a still-developing brain, tiredness, hunger, stress, feeling controlled or problems at school can all feed anger. Sometimes anger hides sadness, anxiety or bullying. Teens also copy how adults at home handle anger.","bn":"হরমোন, এখনও গড়ে ওঠা মস্তিষ্ক, ক্লান্তি, খিদে, চাপ, নিয়ন্ত্রিত বোধ করা বা স্কুলের সমস্যা — সবই রাগ বাড়াতে পারে। কখনো রাগের আড়ালে লুকিয়ে থাকে দুঃখ, উদ্বেগ বা বুলিং। আর ঘরের বড়রা কীভাবে রাগ সামলায়, সন্তান সেটাই শেখে।"},"normal":{"en":"Occasional outbursts, arguments and door-slamming are common in the teen years. Anger with violence, threats or destruction is not acceptable.","bn":"মাঝে মাঝে রাগ, তর্ক বা দরজা ধাক্কা দেওয়া কৈশোরে সাধারণ। কিন্তু সহিংসতা, হুমকি বা ভাঙচুরসহ রাগ মেনে নেওয়া যায় না।"},"do_now":{"en":["Stay calm and lower your voice","Give space: “Let''s talk when we''re both calm.”","Make sure everyone is safe, and move away from anything dangerous"],"bn":["শান্ত থাকুন, গলা নামিয়ে কথা বলুন","জায়গা দিন: “দুজনে শান্ত হলে কথা বলব।”","সবাই নিরাপদ কিনা দেখুন, বিপজ্জনক কিছু থাকলে সরে যান"]},"steps":{"en":["Talk later, once calm: “What was going on for you?”","Name the feeling: “You seemed really frustrated.”","Agree clear limits: being angry is OK, hitting and breaking things are not","Teach calming tools: leave the room, walk, slow breathing, write it down","Agree consequences for damage, such as helping repair it or paying towards it","Check sleep, screen time, school stress and friendships","Model calm yourself, and apologise when you lose your temper"],"bn":["শান্ত হওয়ার পর কথা বলুন: “তখন তোমার ভেতরে কী চলছিল?”","অনুভূতির নাম দিন: “তোমাকে খুব হতাশ লাগছিল।”","পরিষ্কার সীমা ঠিক করুন: রাগ হওয়া ঠিক আছে, মারা বা ভাঙা ঠিক নয়","শান্ত হওয়ার কৌশল শেখান: ঘর থেকে বেরিয়ে যাওয়া, হাঁটা, ধীরে শ্বাস নেওয়া, লিখে ফেলা","কিছু ভাঙলে পরিণাম ঠিক করুন, যেমন মেরামতে সাহায্য করা বা খরচের কিছু অংশ দেওয়া","ঘুম, স্ক্রিন টাইম, পড়ার চাপ আর বন্ধুত্বের খোঁজ নিন","নিজে শান্ত থেকে দেখান, আর মেজাজ হারালে দুঃখ প্রকাশ করুন"]},"avoid":{"en":["Shouting back or hitting","Arguing in the heat of the moment","Humiliating them in front of others","Giving in every time just to stop the outburst"],"bn":["পাল্টা চিৎকার বা মারধর","উত্তেজনার মুহূর্তে তর্ক চালিয়ে যাওয়া","অন্যদের সামনে অপমান করা","রাগ থামাতে প্রতিবারই তার কথা মেনে নেওয়া"]},"example":{"en":"When Tanvir, 14, slammed his door after being told to stop gaming, his father waited. Later he knocked and said, “You were really angry earlier. I want to understand.” Tanvir admitted he was being bullied in an online game. They agreed a gaming time and a plan to deal with the bullying.","bn":"গেম বন্ধ করতে বলায় ১৪ বছরের তানভীর দরজা ধাক্কা দিয়ে বন্ধ করল। বাবা অপেক্ষা করলেন। পরে টোকা দিয়ে বললেন, “তখন তুমি খুব রেগে ছিলে। আমি বুঝতে চাই।” তানভীর স্বীকার করল, একটা অনলাইন গেমে তাকে বুলি করা হচ্ছে। তাঁরা গেম খেলার সময় আর বুলিং সামলানোর একটা পরিকল্পনা ঠিক করলেন।"},"seek_help":{"en":["Anger is frequent, extreme or getting worse","They hurt people or animals, or damage property","Anger comes with low mood, drug use or refusing school","Talk to a doctor, psychologist or school counsellor"],"bn":["রাগ ঘন ঘন, চরম বা বাড়ছে","মানুষ বা প্রাণীকে আঘাত করে, বা জিনিস ভাঙে","রাগের সাথে মন খারাপ, মাদক বা স্কুলে যেতে না চাওয়া","ডাক্তার, সাইকোলজিস্ট বা স্কুলের কাউন্সেলরের সাথে কথা বলুন"]},"warning_signs":{"en":["Threats to hurt themselves or others: call 999 if anyone is in danger","Sudden aggression with confusion, paranoia or days without sleep: this may be drug use or illness, so get medical help"],"bn":["নিজের বা অন্যের ক্ষতি করার হুমকি: কেউ বিপদে থাকলে ৯৯৯-এ ফোন করুন","হঠাৎ আক্রমণাত্মক আচরণের সাথে বিভ্রান্তি, সন্দেহবাতিক বা কয়েক দিন না ঘুমানো: মাদক বা অসুস্থতা হতে পারে, চিকিৎসা নিন"]}}'::jsonb, 3, 4748, 7305, '{}'::text[], 'any', ARRAY['anger', 'outbursts', 'slams doors', 'aggression', 'emotions', 'teen']::text[], false, 'in_review'::lp_review_status, 8033),
  ('tn-demands-expensive-phone', 'scenario', 'general', 'shared', 'routine', 'consensus', '📲', '{"en":"My teen demands an expensive phone","bn":"সন্তান দামি ফোনের জন্য জেদ করছে"}'::jsonb, '{"en":"Wanting what friends have is normal; learning the difference between wants and needs is a life skill. How to say an honest yes, no or ''let''s save for it''.","bn":"বন্ধুদের যা আছে তা চাওয়া স্বাভাবিক; চাওয়া আর প্রয়োজনের পার্থক্য বোঝা একটা জীবন-দক্ষতা। কীভাবে সৎভাবে হ্যাঁ, না, বা “চলো জমাই” বলবেন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Your teen insists on an expensive phone because friends have one, and may sulk, argue or threaten if they don''t get it.","bn":"বন্ধুদের আছে বলে সন্তান দামি ফোনের জন্য জেদ করছে; না পেলে গোমড়া মুখ, তর্ক বা হুমকিও দিতে পারে।"},"why":{"en":"Among teens, phones are linked to status and belonging. Advertising and social media make expensive models look necessary, and your teen may truly fear being left out.","bn":"কিশোরদের মধ্যে ফোন মানে মর্যাদা আর দলে জায়গা। বিজ্ঞাপন আর সোশ্যাল মিডিয়া দামি মডেলকে অপরিহার্য বানিয়ে দেখায়, আর সন্তান সত্যিই বাদ পড়ার ভয় পেতে পারে।"},"normal":{"en":"Wanting what friends have is normal. Learning that wants and needs are different is an important life skill.","bn":"বন্ধুদের যা আছে তা চাওয়া স্বাভাবিক। চাওয়া আর প্রয়োজন যে আলাদা, তা শেখা একটা গুরুত্বপূর্ণ জীবন-দক্ষতা।"},"do_now":{"en":["Stay calm and don''t decide in the middle of an argument","Acknowledge the feeling: “I understand this feels important to you.”","Say you will talk about it as a family"],"bn":["শান্ত থাকুন, তর্কের মাঝখানে সিদ্ধান্ত নেবেন না","অনুভূতিটা স্বীকার করুন: “বুঝতে পারছি, এটা তোমার কাছে গুরুত্বপূর্ণ।”","বলুন, পরিবারের সবাই মিলে এ নিয়ে কথা বলবেন"]},"steps":{"en":["Talk about what they need the phone for: calls, study, photos","Share honestly what the family can afford","Offer options: a mid-range phone, a good second-hand phone, or saving together","Let them contribute from savings, Eid salami or earnings","Agree phone rules before any new phone is handed over","Talk about scams, theft and the risk of showing off an expensive phone in public","Praise them when they accept a fair compromise"],"bn":["কী কাজে ফোন লাগবে তা নিয়ে কথা বলুন: কল, পড়াশোনা, ছবি","পরিবারের সামর্থ্য কতটুকু, তা সৎভাবে জানান","বিকল্প দিন: মাঝারি দামের ফোন, ভালো অবস্থার পুরোনো ফোন, বা একসাথে টাকা জমানো","জমানো টাকা, ঈদের সালামি বা নিজের আয় থেকে কিছু দিতে দিন","নতুন ফোন হাতে দেওয়ার আগেই ফোনের নিয়ম ঠিক করুন","প্রতারণা, চুরি আর প্রকাশ্যে দামি ফোন দেখানোর ঝুঁকি নিয়ে কথা বলুন","ন্যায্য সমঝোতায় রাজি হলে প্রশংসা করুন"]},"avoid":{"en":["Buying on credit, or borrowing money you cannot repay","Giving in to threats or tantrums","Mocking their wish or their friends","Comparing with what other families buy"],"bn":["কিস্তিতে বা এমন ধার করে কেনা, যা শোধ করতে পারবেন না","হুমকি বা জেদের কাছে হার মানা","তার চাওয়া বা বন্ধুদের নিয়ে ঠাট্টা","অন্য পরিবার কী কেনে, তার সাথে তুলনা"]},"example":{"en":"Rima, 16, wanted the newest phone, like her friends. Her parents said they couldn''t afford it, but offered to pay half the cost of a good mid-range phone if she saved the rest from her tutoring money. It took her four months, and she took great care of it.","bn":"১৬ বছরের রিমা বন্ধুদের মতো একেবারে নতুন মডেলের ফোন চাইল। বাবা-মা বললেন অত দামি ফোন কেনার সামর্থ্য নেই, তবে ভালো একটা মাঝারি দামের ফোনের অর্ধেক টাকা তাঁরা দেবেন, বাকিটা সে টিউশনির টাকা থেকে জমাবে। চার মাস লাগল, আর ফোনটার সে খুব যত্ন নিল।"},"seek_help":{"en":["Threats of self-harm or running away over a phone: take them seriously and get help","Stealing money to buy things","Signs of betting or secret debts"],"bn":["ফোনের জন্য নিজের ক্ষতি বা বাড়ি ছেড়ে যাওয়ার হুমকি: গুরুত্ব দিন, সাহায্য নিন","জিনিস কিনতে টাকা চুরি","বাজি বা গোপন ধারদেনার লক্ষণ"]}}'::jsonb, 3, 4748, 7305, '{}'::text[], 'any', ARRAY['expensive phone', 'peer pressure', 'money', 'wants and needs', 'budget']::text[], false, 'in_review'::lp_review_status, 8034),
  ('tn-up-all-night-phone', 'scenario', 'scientific', 'shared', 'routine', 'consensus', '🌛', '{"en":"My teen stays up all night on the phone","bn":"সন্তান সারারাত ফোনে জেগে থাকে"}'::jsonb, '{"en":"Late-night phone use steals the sleep teens need for learning and mood. How to agree a phone-off time that the whole family keeps.","bn":"রাত জেগে ফোন ব্যবহার পড়াশোনা আর মেজাজের জন্য দরকারি ঘুম কেড়ে নেয়। কীভাবে এমন একটা ফোন বন্ধের সময় ঠিক করবেন, যা পুরো পরিবার মানে।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Your teen is on the phone late into the night, then is tired and irritable and struggles at school.","bn":"সন্তান অনেক রাত পর্যন্ত ফোনে থাকে, তারপর সারাদিন ক্লান্ত, খিটখিটে, আর স্কুলে মন দিতে পারে না।"},"why":{"en":"The teen body clock shifts later, and phones make it worse: bright screens delay sleep, and endless feeds, games and chats are designed to keep people hooked. Some teens also use the phone to escape worries.","bn":"কৈশোরে শরীরের ঘড়ি পিছিয়ে যায়, আর ফোন সেটা আরও বাড়ায়: উজ্জ্বল স্ক্রিন ঘুম দেরি করায়, আর শেষ না হওয়া ফিড, গেম আর চ্যাট এমনভাবে বানানো যাতে মানুষ আটকে থাকে। কেউ কেউ দুশ্চিন্তা থেকে পালাতেও ফোন ব্যবহার করে।"},"normal":{"en":"Wanting to stay up later is normal for teens. Regularly getting less than 8 hours of sleep is not healthy.","bn":"দেরিতে ঘুমাতে চাওয়া কিশোর বয়সে স্বাভাবিক। কিন্তু নিয়মিত ৮ ঘণ্টার কম ঘুম স্বাস্থ্যকর নয়।"},"do_now":{"en":["Talk at a calm time, not at midnight","Explain why sleep matters: memory, mood, growth and safety","Agree a phone-off time together"],"bn":["মাঝরাতে নয়, শান্ত কোনো সময়ে কথা বলুন","ঘুম কেন জরুরি বুঝিয়ে বলুন: স্মৃতিশক্তি, মেজাজ, বেড়ে ওঠা আর নিরাপত্তা","একসাথে ফোন বন্ধের সময় ঠিক করুন"]},"steps":{"en":["Agree that every phone charges outside the bedrooms at night, parents'' too","Phones off at least an hour before bed","Keep a regular wake-up time, even on holidays","Use the phone''s built-in screen-time and bedtime settings","Replace late screen time with a calm routine: a bath, reading, prayer, a chat","Review after two weeks and adjust together","Praise progress"],"bn":["ঠিক করুন, রাতে সবার ফোন — বাবা-মায়েরটাও — শোবার ঘরের বাইরে চার্জ হবে","ঘুমের অন্তত এক ঘণ্টা আগে ফোন বন্ধ","ছুটির দিনেও ঘুম থেকে ওঠার সময় নিয়মিত রাখা","ফোনের স্ক্রিন টাইম আর বেডটাইম সেটিং ব্যবহার করা","রাতের স্ক্রিনের বদলে শান্ত রুটিন: গোসল, বই পড়া, নামাজ, গল্প","দুই সপ্তাহ পর একসাথে দেখে দরকারমতো বদলানো","উন্নতি হলে প্রশংসা করা"]},"avoid":{"en":["Grabbing the phone in anger at night","Rules for teens that parents don''t keep themselves","A total ban that leads to secret use","Ignoring it because exams are coming"],"bn":["রাতে রেগে গিয়ে ফোন ছিনিয়ে নেওয়া","এমন নিয়ম, যা বাবা-মা নিজেরা মানেন না","পুরোপুরি নিষেধ, যাতে লুকিয়ে ব্যবহার শুরু হয়","পরীক্ষা সামনে বলে বিষয়টা এড়িয়ে যাওয়া"]},"example":{"en":"Nadia''s 15-year-old son kept falling asleep in class. They agreed that every phone in the house, including hers, would charge in the living room from 10:30 pm. The first week was hard, but by the third week he was waking up on his own.","bn":"নাদিয়ার ১৫ বছরের ছেলে ক্লাসে ঘুমিয়ে পড়ছিল। তাঁরা ঠিক করলেন, রাত সাড়ে ১০টা থেকে বাসার সব ফোন — নাদিয়ার নিজেরটাও — বসার ঘরে চার্জ হবে। প্রথম সপ্তাহ কঠিন ছিল, কিন্তু তৃতীয় সপ্তাহে ছেলে নিজে নিজেই ঘুম থেকে উঠতে লাগল।"},"seek_help":{"en":["Still can''t sleep even without the phone","Signs of gaming or internet addiction","Low mood, anxiety, or being bullied or blackmailed online","Loud snoring with pauses in breathing"],"bn":["ফোন ছাড়াও ঘুম আসে না","গেম বা ইন্টারনেট আসক্তির লক্ষণ","মন খারাপ, উদ্বেগ, বা অনলাইনে বুলিং কিংবা ব্ল্যাকমেইলের শিকার","জোরে নাক ডাকা আর ঘুমের মধ্যে শ্বাস থেমে থেমে যাওয়া"]},"warning_signs":{"en":["Very low mood with talk of hopelessness or self-harm: get help today","Sleeping most of the day and losing interest in everything"],"bn":["খুব মন খারাপের সাথে আশাহীনতা বা নিজের ক্ষতির কথা: আজই সাহায্য নিন","দিনের বেশিরভাগ সময় ঘুমানো আর সবকিছুতে আগ্রহ হারানো"]}}'::jsonb, 3, 4748, 7305, '{}'::text[], 'any', ARRAY['phone at night', 'sleep', 'screen time', 'bedtime', 'tired at school']::text[], false, 'in_review'::lp_review_status, 8035),
  ('tn-wants-to-quit-studies', 'scenario', 'general', 'shared', 'important', 'consensus', '🧭', '{"en":"My teen wants to quit studies or is unsure about the future","bn":"সন্তান পড়াশোনা ছেড়ে দিতে চায়, বা ভবিষ্যৎ নিয়ে দিশেহারা"}'::jsonb, '{"en":"“I want to quit” is often a sign your teen needs help, not a final decision. How to find the real reason and explore paths that keep doors open.","bn":"“পড়াশোনা ছেড়ে দেব” কথাটা অনেক সময় চূড়ান্ত সিদ্ধান্ত নয়, সাহায্য চাওয়ার সংকেত। আসল কারণ খুঁজে বের করা আর ভবিষ্যতের দরজা খোলা রাখে এমন পথ খোঁজার উপায়।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Your teen says they want to stop studying or drop out, or has no idea what to do with their future.","bn":"সন্তান বলছে পড়াশোনা বাদ দিতে চায় বা স্কুল ছেড়ে দেবে, কিংবা ভবিষ্যতে কী করবে কিছুই বুঝতে পারছে না।"},"why":{"en":"Behind this may be exam failure, a subject they hate, a learning difficulty, bullying, money worries, depression, pressure to earn, friends who have left school, or simply not seeing the point of studying.","bn":"এর পেছনে থাকতে পারে পরীক্ষায় ফেল, অপছন্দের কোনো বিষয়, শেখার সমস্যা, বুলিং, টাকার চিন্তা, বিষণ্নতা, আয় করার চাপ, পড়া ছেড়ে দেওয়া বন্ধুরা, বা পড়াশোনার কোনো মানে খুঁজে না পাওয়া।"},"normal":{"en":"Doubts about the future are common in the teen years, and many teens change direction more than once.","bn":"কৈশোরে ভবিষ্যৎ নিয়ে দ্বিধা খুব সাধারণ, আর অনেকেই একাধিকবার পথ বদলায়।"},"do_now":{"en":["Stay calm and avoid threats","Ask: “What''s making school so hard right now?”","Agree not to decide anything for a few weeks while you explore together"],"bn":["শান্ত থাকুন, হুমকি দেবেন না","জিজ্ঞেস করুন: “এখন পড়াশোনা এত কঠিন লাগছে কেন?”","ঠিক করুন, কয়েক সপ্তাহ কোনো সিদ্ধান্ত নয় — এর মধ্যে একসাথে খোঁজখবর নেবেন"]},"steps":{"en":["Find the real reason: subjects, teachers, friends, health or mood","Talk to the school about extra help or a change of group","Explore other paths: technical or vocational training, a polytechnic diploma, skills courses","Arrange talks with people in different jobs","Set small goals, such as finishing this year or this exam","Explain that learning can continue later, but keeping options open matters now","Support daughters and sons equally to continue"],"bn":["আসল কারণ খুঁজুন: বিষয়, শিক্ষক, বন্ধু, স্বাস্থ্য বা মন","বাড়তি সাহায্য বা বিভাগ বদল নিয়ে স্কুলের সাথে কথা বলুন","অন্য পথ খুঁজে দেখুন: কারিগরি বা বৃত্তিমূলক প্রশিক্ষণ, পলিটেকনিক ডিপ্লোমা, দক্ষতা উন্নয়ন কোর্স","নানা পেশার মানুষের সাথে কথা বলার সুযোগ করে দিন","ছোট লক্ষ্য ঠিক করুন, যেমন এই বছর বা এই পরীক্ষাটা শেষ করা","বুঝিয়ে বলুন, পরেও শেখা যায়, কিন্তু এখন দরজাগুলো খোলা রাখা জরুরি","ছেলে-মেয়ে দুজনকেই সমানভাবে পড়া চালিয়ে যেতে সাহায্য করুন"]},"avoid":{"en":["Forcing a path they hate, or comparing them with others","Arranging a marriage instead of studies","Sending an under-age teen into hazardous work","Calling them lazy or a failure"],"bn":["অপছন্দের পথে জোর করা, বা অন্যের সাথে তুলনা","পড়াশোনার বদলে বিয়ের ব্যবস্থা","অপ্রাপ্তবয়স্ককে ঝুঁকিপূর্ণ কাজে পাঠানো","অলস বা ব্যর্থ বলা"]},"example":{"en":"Hasan, 16, said he wanted to leave school and work in his uncle''s shop. His father asked why. Hasan admitted he was failing science and felt stupid. They met the school and looked into a diploma in electrical engineering after SSC. Hasan agreed to finish SSC first.","bn":"১৬ বছরের হাসান বলল সে স্কুল ছেড়ে মামার দোকানে কাজ করবে। বাবা জানতে চাইলেন কেন। হাসান স্বীকার করল, বিজ্ঞানে ফেল করছে আর নিজেকে বোকা মনে হচ্ছে। তাঁরা স্কুলে কথা বললেন, আর এসএসসির পর ইলেকট্রিক্যাল ইঞ্জিনিয়ারিংয়ে ডিপ্লোমার খোঁজ নিলেন। হাসান রাজি হলো, আগে এসএসসি শেষ করবে।"},"seek_help":{"en":["Signs of depression: low mood, no interest and sleep changes for weeks","Possible learning difficulties: ask for an assessment","Talk to a school counsellor or career adviser"],"bn":["বিষণ্নতার লক্ষণ: কয়েক সপ্তাহ ধরে মন খারাপ, কিছুতে আগ্রহ নেই, ঘুমে পরিবর্তন","শেখার সমস্যার সম্ভাবনা: পরীক্ষা করিয়ে নিন","স্কুলের কাউন্সেলর বা ক্যারিয়ার পরামর্শকের সাথে কথা বলুন"]},"warning_signs":{"en":["Talk of hopelessness or self-harm: get help today, and call 999 if they are in danger"],"bn":["আশাহীনতা বা নিজের ক্ষতির কথা: আজই সাহায্য নিন, বিপদে থাকলে ৯৯৯-এ ফোন করুন"]}}'::jsonb, 3, 4748, 7305, '{}'::text[], 'any', ARRAY['drop out', 'quit school', 'future', 'career', 'vocational', 'motivation']::text[], false, 'in_review'::lp_review_status, 8036)
