INSERT INTO lp_task_templates (key, title, description, why, benefit, steps, safety_note, task_type, frequency, assignee, subject, min_day, max_day, estimated_minutes, xp, emoji, category_key, resource_slug, source_key, sex, review_status, sort_order) VALUES
  ('tn_outing_each_parent', '{"en":"A monthly outing alone with each parent","bn":"প্রতি মাসে বাবা ও মা — প্রত্যেকে আলাদা করে সন্তানকে নিয়ে বের হোন"}'::jsonb, '{"en":"Once a month, each parent spends an hour alone with the teen doing something the teen chooses: a walk, a meal, tea at a stall, shopping or a game.","bn":"মাসে একবার বাবা আর মা আলাদা আলাদা করে সন্তানের সাথে এক ঘণ্টা কাটান — কী করবে তা সন্তানই বেছে নেবে: হাঁটা, বাইরে খাওয়া, টং দোকানে চা, কেনাকাটা বা খেলা।"}'::jsonb, '{"en":"Doing something together side by side makes talking easier, and time alone with each parent shows the teen that both of you are there for them.","bn":"পাশাপাশি কিছু করলে কথা বলা সহজ হয়, আর বাবা-মা দুজনের সাথে আলাদা সময় সন্তানকে বোঝায় — দুজনেই তার পাশে আছেন।"}'::jsonb, '{"en":"A closer bond with each parent, and more chances to hear what is really going on.","bn":"বাবা-মা দুজনের সাথেই গভীর সম্পর্ক, আর আসলে কী চলছে তা জানার বেশি সুযোগ।"}'::jsonb, '[{"en":"Let your teen choose the activity","bn":"কী করবেন, সন্তানকে বেছে নিতে দিন"},{"en":"Keep your own phone away","bn":"নিজের ফোন সরিয়ে রাখুন"},{"en":"Ask about their world, not their marks","bn":"নম্বর নয়, তার জগৎ নিয়ে জিজ্ঞেস করুন"},{"en":"Agree the date for next month before you go home","bn":"বাসায় ফেরার আগেই পরের মাসের দিন ঠিক করুন"}]'::jsonb, '{}'::jsonb, 'family', 'monthly', 'shared', 'child', 4748, 7305, 60, 20, '🚶', 'fatherhood', 'tn-father-and-teen', 'unicef_parenting', 'any', 'in_review'::lp_review_status, 8101),
  ('tn_phone_rules_review', '{"en":"Agree and review the family phone rules","bn":"পরিবারের ফোনের নিয়ম একসাথে ঠিক করুন ও দেখুন"}'::jsonb, '{}'::jsonb, '{"en":"Rules a teen helped make are kept far better than rules handed down, and a monthly review lets you give more freedom as trust grows.","bn":"যে নিয়ম বানাতে সন্তান নিজে অংশ নিয়েছে, সেটা সে অনেক বেশি মানে; আর প্রতি মাসে দেখলে আস্থা বাড়ার সাথে স্বাধীনতাও বাড়ানো যায়।"}'::jsonb, '{"en":"Fewer fights about phones, better sleep, and a teen who tells you when something online goes wrong.","bn":"ফোন নিয়ে ঝগড়া কম, ঘুম ভালো, আর অনলাইনে কিছু খারাপ হলে সন্তান আপনাকে জানায়।"}'::jsonb, '[{"en":"Agree phone-free times: meals, homework and the hour before bed","bn":"ফোন ছাড়া সময় ঠিক করুন: খাওয়া, পড়া আর ঘুমের আগের এক ঘণ্টা"},{"en":"Agree where phones charge at night, for parents too","bn":"রাতে ফোন কোথায় চার্জ হবে ঠিক করুন — বাবা-মায়েরটাও"},{"en":"Check privacy settings together","bn":"একসাথে প্রাইভেসি সেটিং দেখুন"},{"en":"Ask what worked and what was hard this month, and adjust","bn":"এ মাসে কী কাজ করল, কী কঠিন লাগল জিজ্ঞেস করে দরকারমতো বদলান"}]'::jsonb, '{}'::jsonb, 'family', 'monthly', 'shared', 'child', 4748, 7305, 20, 15, '📱', 'digital_life', 'tn-privacy-and-trust', 'aap_media', 'any', 'in_review'::lp_review_status, 8102),
  ('tn_wellbeing_checkin', '{"en":"Ask one mental-health check-in question","bn":"মন কেমন আছে — সপ্তাহে একটা প্রশ্ন করুন"}'::jsonb, '{"en":"Once a week, at a relaxed moment, ask one gentle question such as “Out of 10, how was your week?” or “What''s been on your mind lately?”","bn":"সপ্তাহে একবার, হালকা কোনো মুহূর্তে একটা নরম প্রশ্ন করুন, যেমন “দশের মধ্যে তোমার সপ্তাহটা কত?” বা “কিছুদিন ধরে কী নিয়ে বেশি ভাবছ?”"}'::jsonb, '{"en":"Depression and anxiety often start in the teen years and are easy to miss. A regular, gentle question makes it normal to talk about feelings.","bn":"বিষণ্নতা আর উদ্বেগ প্রায়ই কৈশোরে শুরু হয় এবং সহজে চোখ এড়িয়ে যায়। নিয়মিত একটা নরম প্রশ্ন অনুভূতি নিয়ে কথা বলাকে স্বাভাবিক করে তোলে।"}'::jsonb, '{"en":"You notice changes early, and your teen learns that feelings can be talked about at home.","bn":"পরিবর্তন আগেভাগে চোখে পড়ে, আর সন্তান শেখে — ঘরে অনুভূতি নিয়ে কথা বলা যায়।"}'::jsonb, '[{"en":"Choose a calm moment, not during an argument","bn":"ঝগড়ার সময় নয়, শান্ত মুহূর্ত বেছে নিন"},{"en":"Ask one question and listen without fixing","bn":"একটা প্রশ্ন করুন, সমাধান না দিয়ে শুনুন"},{"en":"Note any change that lasts two weeks or more","bn":"দুই সপ্তাহ বা তার বেশি থাকা কোনো পরিবর্তন খেয়াল রাখুন"}]'::jsonb, '{"en":"If your teen talks about wanting to die or harming themselves, stay with them and get help now: call 999 or go to hospital.","bn":"সন্তান মরে যেতে চাওয়া বা নিজের ক্ষতির কথা বললে তার পাশে থাকুন, এখনই সাহায্য নিন: ৯৯৯-এ ফোন করুন বা হাসপাতালে যান।"}'::jsonb, 'observe', 'weekly', 'any', 'child', 4748, 7305, 10, 10, '💚', 'mental_wellbeing', 'tn-teen-mental-health', 'who_adolescent_health', 'any', 'in_review'::lp_review_status, 8103),
  ('tn_teach_life_skill', '{"en":"Teach one real-life skill this month","bn":"এ মাসে একটা বাস্তব জীবন-দক্ষতা শেখান"}'::jsonb, '{"en":"Pick one skill a month and do it together: cooking a full meal, using a bank or mobile banking safely, filling in a form, paying a bill, a simple repair, or using public transport alone.","bn":"মাসে একটা দক্ষতা বেছে নিয়ে একসাথে করুন: পুরো এক বেলার রান্না, নিরাপদে ব্যাংক বা মোবাইল ব্যাংকিং ব্যবহার, ফরম পূরণ, বিল দেওয়া, ছোটখাটো মেরামত, বা একা গণপরিবহনে চলা।"}'::jsonb, '{"en":"Teens grow in confidence and independence when they are trusted with real tasks before they leave home.","bn":"বাড়ি ছাড়ার আগেই সত্যিকারের কাজের দায়িত্ব পেলে কিশোর-কিশোরীর আত্মবিশ্বাস আর স্বাধীনতা বাড়ে।"}'::jsonb, '{"en":"A capable young adult, ready for university, work or living away from home.","bn":"বিশ্ববিদ্যালয়, চাকরি বা বাড়ির বাইরে থাকার জন্য তৈরি দক্ষ একজন তরুণ।"}'::jsonb, '[{"en":"Let your teen choose from a list of skills","bn":"দক্ষতার তালিকা থেকে সন্তানকে বেছে নিতে দিন"},{"en":"Show once, then let them do it while you watch","bn":"একবার দেখিয়ে দিন, তারপর আপনি পাশে থেকে তাকে করতে দিন"},{"en":"Teach sons and daughters the same skills","bn":"ছেলে-মেয়েকে একই দক্ষতা শেখান"}]'::jsonb, '{}'::jsonb, 'learn', 'monthly', 'shared', 'child', 4748, 7305, 45, 15, '🍳', 'life_skills', 'tn-family-rules-together', 'unicef_parenting', 'any', 'in_review'::lp_review_status, 8104),
  ('tn_helmet_check', '{"en":"Helmet and seatbelt check","bn":"হেলমেট ও সিটবেল্ট চেক"}'::jsonb, '{}'::jsonb, '{"en":"A properly fastened helmet greatly reduces the risk of serious head injury on a motorbike or bicycle, and seatbelts save lives in every seat.","bn":"ঠিকমতো আটকানো হেলমেট মোটরবাইক বা সাইকেলে মাথার গুরুতর আঘাতের ঝুঁকি অনেক কমায়, আর যেকোনো সিটে সিটবেল্ট জীবন বাঁচায়।"}'::jsonb, '{"en":"A family habit that protects your teen on every trip.","bn":"পরিবারের এমন একটা অভ্যাস, যা প্রতিটি যাত্রায় সন্তানকে সুরক্ষা দেয়।"}'::jsonb, '[{"en":"Check the helmet fits snugly and the strap is fastened under the chin","bn":"হেলমেট মাথায় ঠিকমতো বসে কিনা আর থুতনির নিচে বেল্ট আটকানো কিনা দেখুন"},{"en":"Look for cracks; replace a helmet after any crash","bn":"ফাটল আছে কিনা দেখুন; দুর্ঘটনার পর হেলমেট বদলান"},{"en":"Remind: seatbelt in every seat, front and back","bn":"মনে করিয়ে দিন: সামনে-পেছনে প্রতিটি সিটে সিটবেল্ট"}]'::jsonb, '{"en":"In Bangladesh a driving licence, including for a motorbike, requires the rider to be at least 18. Do not let an unlicensed teen ride.","bn":"বাংলাদেশে মোটরবাইকসহ ড্রাইভিং লাইসেন্স পেতে বয়স কমপক্ষে ১৮ হতে হয়। লাইসেন্স ছাড়া সন্তানকে বাইক চালাতে দেবেন না।"}'::jsonb, 'must_do', 'weekly', 'any', 'child', 4748, 7305, 5, 5, '🪖', 'safety', 'tn-road-safety', 'who_child_injury', 'any', 'in_review'::lp_review_status, 8105),
  ('tn_budget_together', '{"en":"Plan the month''s budget together","bn":"একসাথে মাসের বাজেট করুন"}'::jsonb, '{"en":"Sit with your teen to plan their pocket money or earnings for the month: what to spend, what to save, and what to give.","bn":"সন্তানের সাথে বসে তার মাসের হাতখরচ বা আয়ের পরিকল্পনা করুন: কতটা খরচ, কতটা সঞ্চয়, আর কতটা দান।"}'::jsonb, '{"en":"Teens who practise budgeting with real money are better prepared to avoid debt, scams and gambling later.","bn":"আসল টাকা দিয়ে বাজেট করার অভ্যাস থাকলে পরে ধারদেনা, প্রতারণা আর জুয়া থেকে দূরে থাকা সহজ হয়।"}'::jsonb, '{"en":"Healthy money habits, and an open channel to talk about money.","bn":"টাকাপয়সার সুস্থ অভ্যাস, আর টাকা নিয়ে খোলাখুলি কথা বলার সুযোগ।"}'::jsonb, '[{"en":"Review last month''s spending together","bn":"গত মাসের খরচ একসাথে দেখুন"},{"en":"Split this month''s money into spend, save and share","bn":"এ মাসের টাকা খরচ, সঞ্চয় আর দানে ভাগ করুন"},{"en":"Set or check a savings goal","bn":"সঞ্চয়ের লক্ষ্য ঠিক করুন বা কতদূর এগোল দেখুন"},{"en":"Remind: never share a PIN or OTP","bn":"মনে করিয়ে দিন: পিন বা ওটিপি কাউকে নয়"}]'::jsonb, '{}'::jsonb, 'learn', 'monthly', 'shared', 'child', 4748, 7305, 30, 15, '💰', 'life_skills', 'tn-money-scams-gambling', 'unicef_parenting', 'any', 'in_review'::lp_review_status, 8106),
  ('tn_period_iron_plan', '{"en":"Period-care and iron check","bn":"মাসিকের যত্ন ও আয়রন চেক"}'::jsonb, '{"en":"Once a month, check with your daughter that she has pads or clean cloths, a plan for period pain, and iron-rich food on the menu.","bn":"মাসে একবার মেয়ের সাথে দেখে নিন: প্যাড বা পরিষ্কার কাপড় আছে কিনা, ব্যথা হলে কী করবে তা ঠিক আছে কিনা, আর খাবারে আয়রনসমৃদ্ধ কিছু থাকছে কিনা।"}'::jsonb, '{"en":"Monthly blood loss and fast growth raise the risk of anaemia, and a simple plan stops periods from keeping a girl home from school.","bn":"প্রতি মাসের রক্তক্ষরণ আর দ্রুত বেড়ে ওঠায় রক্তস্বল্পতার ঝুঁকি বাড়ে; আর সহজ একটা পরিকল্পনা থাকলে মাসিকের জন্য মেয়েকে স্কুল কামাই করতে হয় না।"}'::jsonb, '{"en":"More energy, fewer missed school days, and a daughter who feels supported.","bn":"বেশি শক্তি, কম স্কুল কামাই, আর পাশে আছেন — এমন অনুভূতি।"}'::jsonb, '[{"en":"Restock pads or clean cloths and the school-bag pouch","bn":"প্যাড বা পরিষ্কার কাপড় আর স্কুলব্যাগের থলে ভরে দিন"},{"en":"Keep a hot-water bottle ready and agree what helps her pain","bn":"গরম পানির ব্যাগ হাতের কাছে রাখুন, কিসে তার ব্যথা কমে তা ঠিক করে নিন"},{"en":"Plan iron-rich foods for the week: eggs, fish, meat, dal, green leafy vegetables","bn":"সপ্তাহের খাবারে আয়রনসমৃদ্ধ খাবার রাখুন: ডিম, মাছ, মাংস, ডাল, সবুজ শাক"},{"en":"Check she is taking any iron–folic acid tablet given at school, as advised","bn":"স্কুল থেকে আয়রন–ফলিক অ্যাসিড ট্যাবলেট দিলে পরামর্শমতো খাচ্ছে কিনা দেখুন"}]'::jsonb, '{"en":"See a doctor if periods last more than 7 days, she soaks a pad every 1–2 hours, pain stops her going to school, or she feels faint or breathless.","bn":"মাসিক ৭ দিনের বেশি চললে, প্রতি ১–২ ঘণ্টায় প্যাড ভিজে গেলে, ব্যথার জন্য স্কুলে যেতে না পারলে, বা মাথা ঘুরলে বা শ্বাসকষ্ট হলে ডাক্তার দেখান।"}'::jsonb, 'recommended', 'monthly', 'any', 'child', 4748, 7305, 15, 10, '🌸', 'puberty', 'tn-puberty-girls', 'who_adolescent_health', 'female', 'in_review'::lp_review_status, 8107),
  ('tn_career_talk', '{"en":"Have a career-interest talk","bn":"পছন্দ ও ভবিষ্যৎ পেশা নিয়ে আলাপ করুন"}'::jsonb, '{"en":"Every few months, talk with your teen about what they enjoy, what they are good at, and which study paths and jobs they are curious about.","bn":"কয়েক মাস পরপর সন্তানের সাথে কথা বলুন: কী ভালো লাগে, কোনটায় সে ভালো, আর কোন পড়াশোনা বা পেশা নিয়ে তার কৌতূহল।"}'::jsonb, '{"en":"Teens make better choices about study groups and careers when they feel heard and have explored real options early.","bn":"নিজের কথা শোনা হচ্ছে মনে হলে আর আগেভাগে বাস্তব বিকল্পগুলো দেখে নিলে বিভাগ ও পেশা বাছাইয়ে সন্তান ভালো সিদ্ধান্ত নেয়।"}'::jsonb, '{"en":"A path your teen owns, and less conflict and stress at decision time.","bn":"সন্তানের নিজের বেছে নেওয়া পথ, আর সিদ্ধান্তের সময় কম দ্বন্দ্ব ও চাপ।"}'::jsonb, '[{"en":"Ask what they enjoyed and found hard this term","bn":"এই টার্মে কী ভালো লেগেছে আর কী কঠিন লেগেছে জিজ্ঞেস করুন"},{"en":"Explore one new path together: science, business studies, humanities, technical or vocational","bn":"একসাথে একটা নতুন পথ খুঁজে দেখুন: বিজ্ঞান, ব্যবসায় শিক্ষা, মানবিক, কারিগরি বা বৃত্তিমূলক"},{"en":"Arrange a chat with someone who works in a field they are curious about","bn":"যে পেশা নিয়ে কৌতূহল, সেখানে কাজ করেন এমন কারও সাথে কথা বলিয়ে দিন"},{"en":"Listen to their ideas before sharing yours","bn":"নিজের মত দেওয়ার আগে তার ভাবনা শুনুন"}]'::jsonb, '{}'::jsonb, 'family', 'quarterly', 'shared', 'child', 4748, 7305, 45, 20, '🧭', 'career', 'tn-study-group-career', 'unicef_parenting', 'any', 'in_review'::lp_review_status, 8108)
